/**
 * THE shared API↔client wire contract — single source of truth.
 *
 * This module is **dependency-free on purpose**: no imports (not Drizzle, not
 * anything). It is the file both clients' `src/api/contracts.ts` are GENERATED
 * from (verbatim + a banner, via each repo's `npm run sync:contracts`), so it
 * must never drag server code (Drizzle schema, Node APIs) into a browser
 * bundle. Keep it pure types + literal value tuples + pure helpers. The
 * generators strip exactly THIS first doc block and copy the rest verbatim —
 * one leading doc block, zero `import` statements, ever.
 *
 * Layout (fixed section order, 1.13.0 — designs/wire-contract-completion.md §2):
 *   §0      this header + WIRE_CONTRACT_VERSION + the conventions block
 *   §1      THE error contract (ApiErrorCode + envelope + details union) — orchestrator-owned
 *   §2      shared enums + value tuples (everything used by ≥2 domains) — orchestrator-owned
 *   §3–§15  one fenced section per domain, ALPHABETICAL:
 *             auth-media · bookings · credits · dogs-profile · enrollments ·
 *             events · messaging · notifications ·
 *             payments-invoices · rates-availability · refunds · reports
 *           + settings (2.0.0-lg1.1, design §1.1:588-593: alphabetical, so the
 *             LAST domain section, after reports and before §16; the §16
 *             label is kept, not renumbered)
 *   §16     WireTupleConformance (tuple ↔ union set-equality pins) — orchestrator-owned
 *
 * Domain sections are delimited by `// >>> domain:<name>` / `// <<< domain:<name>`
 * fence comments the merge protocol keys on. Within a domain: (a) domain-local
 * enums + tuples → (b) response wires → (c) request bodies + query shapes →
 * (d) per-endpoint 422 union aliases → (e) pure helpers owned by the domain.
 *
 * Two halves, as ever:
 *   1. **Enum unions + value tuples.** Declared here as literals. Their values
 *      are canonically owned by the DB (`schema.sql` → Drizzle `pgEnum`); the
 *      literals here are a hand-maintained mirror that `contracts/conformance.ts`
 *      pins to the Drizzle enums with a compile-time `Equal<…>` assert — so if
 *      `schema.sql` changes an enum, `tsc` fails until this file is updated.
 *      (We assert rather than rewire `pgEnum(...)` because `schema.ts` is
 *      drizzle-introspection-generated and a `db:introspect` pull would clobber
 *      any hand-wired tuple import.) §16 additionally pins every full-union
 *      value tuple to its union, self-contained, so the guard travels with
 *      every generated copy.
 *   2. **Wire interfaces.** The JSON shapes the API emits. snake_case keys are
 *      intentional — they're the literal JSON keys on the wire. These have no
 *      other canonical home, so THIS file is their single definition; the API's
 *      `lib/*Wire.ts` + the staff routes import them from here.
 */

// ---- contract version ------------------------------------------------------

/**
 * Semver for this contract. Bump on EVERY edit to this file, log the change in
 * `src/contracts/CHANGELOG.md`, and resync BOTH generated clients (portal +
 * mobile `npm run sync:contracts`) in their own repos' commits:
 *   major — remove/rename/retype an existing field or enum member
 *   minor — additive (new field, interface, enum member, tuple value)
 *   patch — comment/doc-only (still changes generated bytes → still resync)
 *
 * Landing-group prereleases (the v1 build, design §1.3): `X.Y.Z-lg<g>.<k>` is
 * step k of landing group g toward `X.Y.Z`, and the group's last unit sets
 * `X.Y.Z` itself. A step may be breaking or additive; its CHANGELOG entry says
 * which, and the bump rules above apply step to step. LG1: 2.0.0-lg1.1 (P01,
 * additive), 2.0.0-lg1.2 (P02, breaking), 2.0.0 (P03, additive, LG1's close).
 * LG2, M1's part (design 3.0.0's S05 and S17 only): 3.0.0-lg2.1 (P05,
 * breaking), 3.0.0 (P12, breaking, its close). The rest of design 3.0.0
 * ships after M1 as 7.0.0 (LG2b), so a design label from 6.1.0 up reads one
 * major up here; 4.0.0, 5.0.0 and 6.0.0 keep theirs (build DECISIONS 6;
 * plan.json `wire_label_map`). LG3: 4.0.0-lg3.1 (P13, breaking),
 * 4.0.0-lg3.2 (P15, breaking), 4.0.0 (P16, breaking, its close). LG4:
 * 5.0.0-lg4.1 (P17, breaking), 5.0.0-lg4.2 (P18, breaking), 5.0.0 (P19,
 * additive, its close). LG5: 6.0.0-lg5.1 (P20, breaking), 6.0.0-lg5.2 (P21,
 * breaking).
 */
export const WIRE_CONTRACT_VERSION = '6.0.0-lg5.2';

// ---- conventions (the 1.13.0 rulebook, applied file-wide) ------------------
//
// · Response shapes: `XxxWire` (entity) — net-new endpoint-specific envelopes:
//   `<Method><PathPascal>Response`. Request bodies, net-new:
//   `<Method><PathPascal>Request`; query-string shapes: `<Method><PathPascal>Query`
//   (HTTP method PascalCase + path segments PascalCase, `:params` dropped).
//   Grandfathered pre-1.13.0 names promote/stay VERBATIM, never renamed —
//   renaming is a major bump.
// · Optional `?` keys are OMITTED when null/empty, never emitted as null,
//   unless the field's own doc comment states an explicit non-omit exception.
// · Cross-field request rules ("text or attachments, one required") are doc
//   comments on the request type, not type gymnastics — the type states
//   key-level optionality truthfully; the comment states the semantic rule
//   and where it is enforced.
// · Promoted declarations carry provenance: the source file:line they were
//   transcribed from and the audit-digest item that asked for them.
// · Idempotency-Key — required header on EVERY mutating endpoint. One parse
//   site for all of them: `db/mutation.ts:80-94 requireIdempotencyKey`
//   (`schema.sql` Transaction contract notes, IDEMPOTENCY). Transcribed 1.13.0
//   from that function — digest refunds/S "Document the Idempotency-Key length
//   contract":
//     · missing, non-string, or empty        → 400 `bad_request`
//     · longer than 206 characters           → 400 `bad_request`; the error
//       message names the live number — read it rather than hard-coding this one
//     · sent more than once on one request   → the values are JOINED: Node
//       delivers duplicate non-set-cookie headers as ONE comma-joined string,
//       so the key becomes `"A, B"` — matching NEITHER attempt. mutation.ts:81's
//       array branch is unreachable for this header. SEND THE HEADER EXACTLY
//       ONCE: a proxy or client that duplicates it with a differing value
//       defeats the replay guarantee (the retry becomes a NEW mutation — on a
//       money endpoint, a second charge). 2.6 adversary finding, fix round 1;
//       server-side rejection of comma-joined keys is a phase-3 hardening
//       candidate.
//     · same key + a different `METHOD path`, or a different canonical-JSON body
//       hash                                 → 422 `idempotency_mismatch`
//     · same key still executing             → 409 `idempotency_inflight`.
//       On a route that rides the order engine (4.0.0-lg3.2, § payments-invoices)
//       the claim stays open until the order settles, so a key whose charge
//       Stripe still reports `processing` answers this even after its 201
//     · a completed key replays the ORIGINAL status and body verbatim; errors
//       are never stored, so a retry after a failure re-attempts the work. The
//       one exception is the order engine's committed 402 `payment_failed`
//       (design §2.7:3939-3952): it IS stored, a replay returns the same 402,
//       the card is not tried again, and the next try takes a fresh key
//   There is NO format, charset, or uniqueness rule: any non-empty string within
//   the bound is accepted. A v4 UUID (36 chars) is what both clients mint and
//   what the contract recommends — it is not a validation.
//   206 is DERIVED, not chosen (`mutation.ts:15-70`): 255, Stripe's own
//   idempotency-key cap, minus 49 — the longest suffix this API appends to your
//   key before sending a DERIVED key to Stripe (`:dog:<uuid>:capture`). Adding a
//   longer suffix TIGHTENS the bound automatically, and moving it is a wire
//   change that takes a bump. The bound is application-level only:
//   `idempotency_keys.key` is unbounded `text` (`schema.sql:1539`), so this
//   boundary check IS the whole contract.

// ============================================================================
// §1 · THE error contract (orchestrator-owned)
// ============================================================================
//
// Promoted 1.13.0 from runtime truth: `lib/errors.ts` (codes + statuses),
// `lib/bookingErrors.ts` (detail shapes), `auth/plugin.ts:188-207` (envelope
// serializer). BUSINESS-LOGIC/api-conventions.md R1 documents the envelope;
// its :151 documents the 'internal' trap this union closes. The server folds
// back onto these types (`lib/errors.ts` imports them), so a route inventing
// a code or details literal outside this contract is a `tsc` error at the
// construction site — the drift guard the old opaque typing deliberately
// lacked.

/**
 * All codes the API can emit. The 23 thrown codes (promoted verbatim from
 * `lib/errors.ts:43`) + `'internal'`, the serializer's fallback for any
 * non-ApiError throw (`auth/plugin.ts:203-206`) — NOT throwable via ApiError's
 * own sites, but a client switch written against the thrown codes alone
 * misses it (api-conventions.md:151). Clients key behavior off `code`;
 * `message` is UI prose.
 *
 * 2.0.0-lg1.1 appends a 24th thrown code, `'setting_inert'` (422), AFTER
 * `'internal'` — appended, never inserted, so no existing tuple position
 * moves (design §1.1:590-591, :641-644). The fallback-only status of
 * `'internal'` is unchanged by its no longer being last.
 *
 * `'not_provisioned'` (403) and the expired staffer, documented 2.0.0-lg1.2
 * for EVERY staff route (design §1.1:720-721; existing behavior,
 * `auth/plugin.ts:115-121`): a staffer whose `staff.expired_at` is set
 * (`npm run staff:provision --expire`) has no live mirror row
 * (`auth/mirror.ts:33` reads `expired_at IS NULL` and nothing else), so a
 * bearer that still verifies is refused 403 `not_provisioned`, no `details`,
 * on every `[auth]` route, staff routes included, until it expires. The
 * portal signs out on this code and on no other 403 (design §2.10:4636-4640);
 * every role refusal is `forbidden` or a named code instead. The owner app
 * answers it on `GET /me` with its one screen for a session whose token has
 * no owner row — "No account yet: open the link we emailed you, or message
 * the school" — and Log Out (design §2.2:2244; ACCT-U14).
 *
 * 3.0.0-lg2.1 appends a 25th thrown code, `'profile_incomplete'` (422),
 * after `'setting_inert'` — appended, never inserted (design §1.1:758-763,
 * :822-827; ACCT-U04). `PATCH /me` is its first route; the booking arms
 * (ACCT-U11) and `POST /evaluations` join it when they land.
 *
 * 4.0.0-lg3.1 appends five thrown codes, the 26th to the 30th, after
 * `'profile_incomplete'` — appended, never inserted (design §1.1:914-916,
 * :936): `'program_not_offered'`, `'same_day_cutoff_passed'`,
 * `'beyond_booking_horizon'`, `'capacity_below_booked'` and
 * `'service_not_offered'`, each 422. Only `'capacity_below_booked'` carries
 * `details` (`CapacityBelowBookedDetails`); on the other four the code is the
 * whole signal. Each route's doc says which of them it can answer.
 *
 * 4.0.0-lg3.2 appends one thrown code, the 31st, after `'service_not_offered'`
 * — appended, never inserted (design §1.1:925-928; PAY-U05):
 * `'invoice_payment_in_flight'`, 409, no `details`. `InvoicePayRequest` says
 * when it answers.
 *
 * 4.0.0 appends one thrown code, the 32nd, after `'invoice_payment_in_flight'`
 * — appended, never inserted (design §1.1:917-920; CRED-U12):
 * `'credit_expired_before_date'`, 422, with `details`
 * (`CreditExpiredBeforeDateDetails`). Its predicate landed at 5.0.0-lg4.2.
 *
 * 5.0.0-lg4.2 appends six thrown codes, the 33rd to the 38th, after
 * `'credit_expired_before_date'` — appended, never inserted (design
 * §1.1:986-987, :996-1000; CRED-U10, CRED-U04, CRED-U14, CRED-U15):
 * `'alumni_tier_requires_alumni_dog'`, `'count_not_allowed'`,
 * `'lot_insufficient'`, `'expiry_not_in_future'` and `'pool_not_bookable'`, each
 * 422, and `'credit_edit_role_required'`, 403. None carries `details`: the code
 * is the whole signal. Each route's doc says which of them it can answer.
 *
 * 5.0.0 appends two thrown codes, the 39th and 40th, after
 * `'credit_edit_role_required'` — appended, never inserted (design
 * §1.1:984-986, §2.4:3060-3068; ALUM-U11, EVAL-U20): `'alumni_package_ineligible'`,
 * 422, with `details` (`AlumniPackageIneligibleDetails`), and
 * `'pack_requires_evaluated_dog'`, 422, no `details`. The second is typed here
 * and thrown by no route until EVAL-U20 lands (plan unit P11).
 *
 * 6.0.0-lg5.1 appends eight thrown codes, the 41st to the 48th, after
 * `'pack_requires_evaluated_dog'` — appended, never inserted (design
 * §1.1:1064-1082, §2.3:2371-2398, :2418-2447; DAY-U29, DAY-U33, CXL-U09), each
 * 409: the request is well-formed and the booking's state refuses it. The
 * cancels answer `'session_checked_in'`, `'session_ended'`,
 * `'session_cancelled'`, `'payment_pending'` and `'per_dog_cancel_off'`; the
 * board's six verbs answer `'attendance_state_conflict'`, `'session_not_today'`
 * and `'no_show_too_early'`, and `'session_cancelled'` and `'payment_pending'`
 * too. Four carry `details` (`SessionEndedDetails`,
 * `AttendanceStateConflictDetails`, `SessionNotTodayDetails`,
 * `NoShowTooEarlyDetails`); on the other four the code is the whole signal.
 *
 * 6.0.0-lg5.2 appends one thrown code, the 49th, after `'no_show_too_early'` —
 * appended, never inserted (design §1.1:1083-1085, §2.3:2558-2564; DAY-U43):
 * `'after_school_full'`, 422, with `details` (`AfterSchoolFullDetails`).
 * `POST /bookings` is its one route.
 */
export type ApiErrorCode =
  | 'unauthenticated' // missing/malformed Authorization header or bad token
  | 'not_provisioned' // token verifies, but no live mirror row for this uid
  | 'forbidden' // authenticated, but the role gate rejected the route
  | 'not_found' // resource exists or doesn't, but not visible to this principal
  | 'bad_request' // client sent a malformed/unaccepted request body
  | 'invalid_payload' // signature OK, but the payload is semantically unusable
  | 'conflict' // request conflicts with current state (e.g. DELETE referenced)
  | 'idempotency_mismatch' // Idempotency-Key reused on a different endpoint+body
  | 'idempotency_inflight' // duplicate Idempotency-Key request still in progress
  | 'ambiguous_principal' // integrity: uid in BOTH owners and staff
  | 'payment_required' // booking blocked — owner has no live payment_methods row
  | 'vaccine_missing' // booking blocked — required vaccines missing/expired (per dog)
  | 'agreement_unsigned' // booking blocked — required agreements unsigned at current version
  | 'insufficient_credits' // booking blocked — credits do not cover the dates, or a top_up no longer fits them
  | 'insufficient_capacity' // booking blocked — the (location,date) seat cap is exhausted
  | 'cohort_full' // enrollment blocked — cohort.filled + requested > cohort.capacity
  | 'eligibility_missing' // enrollment blocked — dog(s) missing OR-prereq for cohort's class
  | 'evaluation_required' // booking blocked — dog(s) missing passed evaluation for gated category
  | 'already_booked' // day-program booking blocked — dog already has a live booking for (category, day)
  | 'already_enrolled' // enrollment blocked — dog already enrolled in this cohort
  | 'already_requested' // request blocked — dog already has an open request of this category
  | 'event_full' // event RSVP blocked — live rsvp dogs + requested > events.capacity
  | 'payment_failed' // a charge did not complete — nothing it was to pay for stands
  | 'internal' // serializer fallback for any non-ApiError throw — never thrown as ApiError
  | 'setting_inert' // settings PATCH blocked — a key in the body has no v1 reader (2.0.0-lg1.1)
  | 'profile_incomplete' // PATCH /me blocked — the body would blank a mandatory sign-up field (3.0.0-lg2.1)
  | 'program_not_offered' // booking blocked — the campus does not offer this day program (4.0.0-lg3.1)
  | 'same_day_cutoff_passed' // booking blocked — today's same-day cutoff has passed at this campus (4.0.0-lg3.1)
  | 'beyond_booking_horizon' // create blocked — a date is past day.booking_horizon_months (4.0.0-lg3.1)
  | 'capacity_below_booked' // cap edit blocked — a booked date would fall below its count (4.0.0-lg3.1)
  | 'service_not_offered' // request blocked — the service is off at the campus (4.0.0-lg3.1)
  | 'invoice_payment_in_flight' // invoice pay blocked — another order's charge on it is in flight (4.0.0-lg3.2)
  | 'credit_expired_before_date' // booking blocked — a date no credit she holds or can buy today reaches (4.0.0)
  | 'alumni_tier_requires_alumni_dog' // booking blocked — `tier: 'alumni'` names a dog that is not alumni (5.0.0-lg4.2)
  | 'count_not_allowed' // purchase blocked — `count` on a pack, or past the single-day limit (5.0.0-lg4.2)
  | 'lot_insufficient' // hand removal blocked — more credits than the lot has unspent (5.0.0-lg4.2)
  | 'expiry_not_in_future' // hand edit blocked — the date is not later than now (5.0.0-lg4.2)
  | 'pool_not_bookable' // hand add blocked — no v1 booking can draw from this pool (5.0.0-lg4.2)
  | 'credit_edit_role_required' // hand edit blocked — the role is off its list (5.0.0-lg4.2)
  | 'alumni_package_ineligible' // purchase blocked — an alumni-tier row, and no dog on the account is alumni (5.0.0)
  | 'pack_requires_evaluated_dog' // purchase blocked — no dog on the account holds a passed evaluation (5.0.0; thrown from P11)
  | 'session_checked_in' // cancel blocked — a dog of the session, or the dog named, is past `expected` (6.0.0-lg5.1)
  | 'session_ended' // cancel blocked — Chicago now has reached the session's `day.pickup_close_time` (6.0.0-lg5.1)
  | 'session_cancelled' // board verb or one-dog cancel blocked — the session or that dog's share is cancelled (6.0.0-lg5.1)
  | 'payment_pending' // board verb or one-dog cancel blocked — the row's top-up charge has not settled (6.0.0-lg5.1)
  | 'per_dog_cancel_off' // owner one-dog cancel blocked — `cxl.per_dog_cancel_enabled` is off (6.0.0-lg5.1)
  | 'attendance_state_conflict' // board verb blocked — the dog's folded state does not allow it (6.0.0-lg5.1)
  | 'session_not_today' // board verb blocked — the session's date is not one this verb takes (6.0.0-lg5.1)
  | 'no_show_too_early' // *Didn't come* blocked — before `day.pickup_close_time` on the date (6.0.0-lg5.1)
  | 'after_school_full'; // booking blocked — a date's after-school session cannot take the dogs ticked for it (6.0.0-lg5.2)

