  'payment_required',
  'vaccine_missing',
  'agreement_unsigned',
  'insufficient_credits',
  'insufficient_capacity',
  'cohort_full',
  'eligibility_missing',
  'evaluation_required',
  'already_booked',
  'already_enrolled',
  'already_requested',
  'event_full',
  'payment_failed',
  'internal',
  'setting_inert',
  'profile_incomplete',
  'program_not_offered',
  'same_day_cutoff_passed',
  'beyond_booking_horizon',
  'capacity_below_booked',
  'service_not_offered',
  'invoice_payment_in_flight',
  'credit_expired_before_date',
  'alumni_tier_requires_alumni_dog',
  'count_not_allowed',
