// >>> domain:auth-media =======================================================

// --- (a) domain-local enums -------------------------------------------------

/** The human display label the owner/staff `/me` wire carries for a location —
 *  the ONE surface that does not use the `LocationKey` slug. Every other
 *  location field on this contract (bookings, credits, capacity, rates) is a
 *  slug end-to-end. Promoted 1.13.0 from `lib/locations.ts:14-15`
 *  (`LOCATION_DISPLAY_NAMES` / `LocationDisplay`) — digest auth-media/M.
 *  Slug ↔ label translation is server-side (`slugToDisplay`/`displayToSlug`,
 *  `lib/locations.ts:27-33`); `locations.display_name` is the DB source of
 *  truth for the label and this union is a hand mirror of it — there is no
 *  pgEnum to pin it to, so a third school added to `locations` without
 *  updating this union emits a label outside the type (the mirror-drift hole
 *  `lib/locations.ts:9-11` already documents). Filed, not fixed. */
export type LocationDisplay = 'Fayetteville, AR' | 'Bentonville, AR';

/** Where a row came from — a hand-maintained mirror of the `record_source`
 *  pgEnum (`schema.sql:194`), in its order, which `conformance.ts` pins to the
 *  Drizzle enum. `'app'` = written by the app or by staff; `'gingr'` = imported
 *  from Gingr (R6; the import is LG10's); `'seed'` = a curated preload. New
 *  2.0.0 (P03): it reaches the wire through `StaffOwnerWire.source` only. No
 *  value tuple: nothing iterates it. */
export type RecordSource = 'app' | 'gingr' | 'seed';

// --- (b) response wires -----------------------------------------------------

/** `POST /media/upload` + `GET /media/:id` response. `url` + derivative URLs are
 *  short-lived presigned GETs; `derivatives` is empty until the derivatives
 *  worker runs (the source is still readable at original size — that's `url`). */
export interface MediaWire {
  id: string;
  purpose: MediaPurpose;
  kind: MediaKind;
  url: string;
  expires_at: string;
  blurhash: string | null;
  width: number | null;
  height: number | null;
  duration_ms: number | null;
  derivatives: Record<string, string>;
}

/** The owner's emergency contact, nested on `MeWire`. The DB stores these as
 *  flat `emergency_*` columns and the API denormalizes them on read (the same
 *  pattern as Booking). Promoted 1.13.0 from `ownerProfile` (`routes/me.ts`)
 *  — digest auth-media/M. NON-OMIT EXCEPTION to the file-wide omit-on-null
 *  rule: each nullable column emits `''`, never `null` and never an omitted
 *  key, so the mobile `toUser` translator's unconditional property reads can't
 *  hit `undefined` (the "frozen wire shape" comment in `routes/me.ts`;
 *  BUSINESS-LOGIC/auth-accounts.md:38 R13). */
export interface MeEmergencyContactWire {
  name: string;
  relationship: string;
  phone: string;
}

/** The owner's mailing address, nested on `MeWire`. Same denormalize-on-read +
 *  `''`-never-`null` contract as `MeEmergencyContactWire`. Promoted 1.13.0 from
 *  `ownerProfile` (`routes/me.ts`) — digest auth-media/M. */
export interface MeAddressWire {
  line1: string;
  line2: string;
  city: string;
  state: string;
  zip: string;
}

/** `GET /me` (owner principal) and `PATCH /me` response — the SAME projection
 *  (`ownerProfile`, both call sites, `routes/me.ts`). Promoted 1.13.0 from that
 *  function — digest auth-media/M. Rules: BUSINESS-LOGIC/auth-accounts.md:38
 *  (R13, the frozen owner shape) and :39 (R14, the PATCH contract).
 *
 *  A staff principal on `GET /me` gets `StaffMeWire` instead — see
 *  `GetMeResponse`. `PATCH /me` hard-403s staff (the handler's `principal.kind`
 *  check, `routes/me.ts`).
 *
 *  This shape was frozen long before it was contracted: it is the exact key set
 *  the mobile `toUser` translator reads, and mobile hand-mirrors it as `RawUser`
 *  (`mobile/src/repositories/userRepository.ts:52`, deleted at 2.4 §10).
 *
 *  3.0.0-lg2.1 is the first change since that freeze (design §1.1:738,
 *  :760-762; ACCT-U04; migration M2.01). BREAKING: `name`, `phone` and
 *  `location` become nullable — an imported family may arrive without any of
 *  them (MIG-57), and a field the sign-up map marks `asked` may be cleared —
 *  so a client that reads them as always-present strings breaks. ADDED:
 *  `missing_mandatory_fields`. The `''`-never-`null` rule of the two nested
 *  objects is unchanged. */
export interface MeWire {
  id: string;
  /** NON-OMIT: `null` when the family has none, never `''` and never omitted
   *  (3.0.0-lg2.1, M2.01). A stored value with no visible character reads as
   *  `null` too (the test is on `ProfileIncompleteDetails`). A reader that
   *  prints a name falls back to `email` (design §2.2:2244). */
  name: string | null;
  email: string;
  /** NON-OMIT: `null` when the family has none, never `''` and never omitted
   *  (3.0.0-lg2.1, M2.01). A stored value with no visible character reads as
   *  `null` too, as on `name`. */
  phone: string | null;
  /** DISPLAY label, not the slug (`slugToDisplay` in `ownerProfile`).
   *  `PatchMeRequest.location` speaks the same vocabulary. NON-OMIT: `null` when the family has no home campus
   *  (3.0.0-lg2.1, M2.01). */
  location: LocationDisplay | null;
  /** Never `null` and never omitted (`?? ''`, `ownerProfile`). A media-asset
   *  UUID is resolved to a 1h signed GET URL at read time; a bundled/seed path
   *  or `''` passes through unchanged (`lib/profileImageUrls.ts:26,40-59`), so
   *  the value is EITHER an opaque stored path OR an expiring URL — clients must
   *  not persist it. Writes are ownership-guarded (`assertOwnedImagePath`). */
  avatar_image_path: string;
  emergency_contact: MeEmergencyContactWire;
  address: MeAddressWire;
  push_notifications_enabled: boolean;
  /** `unknown`, deliberately — NOT `Record<string, unknown>`. The column is
   *  `jsonb NOT NULL DEFAULT '{}'` with no CHECK (`schema.sql:248`), so it can
   *  hold any JSON value, and the server's own enforcement code says so and
   *  narrows defensively at the point of use: "the jsonb is untyped at the DB
   *  seam, so we narrow rather than trust its shape" (`lib/pushPreferences.ts:76-95`;
   *  `OwnerPushPrefs.pushNotificationCategories: unknown` @ :81). Typing it
   *  `Record<string, unknown>` here does not compile against the real emission
   *  (proof: patch Evidence E4). The TIGHTENING IS FILED, NOT ENACTED (§14.1):
   *  the approved §6-batch #4 collapsed the toggle PANEL to 2 + master; the
   *  wire KEY vocabulary remains genuinely open (2.6 adversary, fix round 1),
   *  phase 3 rules it + adds the CHECK, and only then can this narrow.
   *
   *  LIVE KEYS, for readers who need them today: the account screen's six
   *  toggles — `booking-confirmations`, `booking-reminders`, `report-cards`,
   *  `session-photos`, `urgent-updates`, `announcements`
   *  (`lib/pushPreferences.ts:17-25`; mobile `types/user.ts:26-32`). Only
   *  `booking-reminders` and `urgent-updates` gate anything server-side
   *  (`PUSH_TYPE_CATEGORY`, `lib/pushPreferences.ts:53-67`). Semantics are
   *  opt-OUT: a missing key, a non-boolean, or `true` all mean SEND; only an
   *  explicit `false` mutes. The contract fixture emits a DIFFERENT vocabulary
   *  entirely (`{ booking: true, message: true }`,
   *  `test/contracts/_fixture.ts:361`) — which is precisely why the wire cannot
   *  promise a closed key set. */
  push_notification_categories: unknown;
  email_notifications_enabled: boolean;
  /** Same unconstrained-`jsonb` truth as `push_notification_categories`
   *  (`schema.sql:250`). No sender reads it at all today — email prefs have no
   *  consumer (DISCREPANCIES.md:519 DRIFT-46). */
  email_notification_categories: unknown;
  /** Opt-OUT gate on the pre-login public gallery (`GET /welcome-dogs`);
   *  persists via `PATCH /me`. BUSINESS-LOGIC/auth-accounts.md:49 (R24). */
  show_dogs_on_welcome: boolean;
  /** The sign-up fields `acct.signup_field_requirement_map` marks `mandatory`
   *  that are EMPTY on this account, in `SIGNUP_FIELDS` order; `[]` when none
   *  (NON-OMIT, never `null`). Empty is the test `ProfileIncompleteDetails`
   *  states. `email` is never listed: it is the login identity, never empty,
   *  and fixed `mandatory` in the map. Read from Postgres on every `GET /me`
   *  and `PATCH /me` (no cache), so a field staff flip to `mandatory` shows at
   *  the family's next read. Only an imported family (MIG-57) or a field
   *  flipped `mandatory` later (ACCT-08) can carry one (design §2.2:2237).
   *  New 3.0.0-lg2.1 (design §1.1:762; ACCT-U04). The booking pre-check reads
   *  the same test when it lands (ACCT-U11). */
  missing_mandatory_fields: SignupField[];
}

/** `GET /me` (staff principal) response — the staff mirror row. Promoted 1.13.0
 *  from `staffProfile` (`routes/me.ts`) — digest auth-media/S.
 *
 *  RATIFIED + FROZEN at 1.13.0. The source comment called this "a Day-2 design
 *  choice, not a frozen contract … Ratify when the portal lands"
 *  (over `staffProfile`, replaced by this ratification), logged as NOTE-35
 *  (`BUSINESS-LOGIC/DISCREPANCIES.md:849`) and as the freeze-before-consume caveat in
 *  `.claude/backend/PORTAL-ENDPOINT-MAP.md` § auth/me. This declaration IS that
 *  ratification: the shape is frozen exactly as emitted today, nothing added,
 *  nothing renamed.
 *
 *  2.0.0-lg1.2 (P02; design §1.1:598-605, :695-709) is the first change since
 *  that freeze, three breaking and one additive: `role`'s vocabulary is
 *  rebuilt (STAFF-U02); `location` becomes `home_locations` (STAFF-U03);
 *  `active` is removed with `staff.active` (M1.20; question 34); and
 *  `capabilities` is added (STAFF-U07). Portal alignment notes, so the portal
 *  wave does not re-litigate them:
 *    · `role` is `StaffRole` (§2), now `owner | manager | trainer`. That
 *      rebuild IS the "eventual StaffRole vocabulary migration" that DRIFT-43
 *      (DISCREPANCIES.md:501) and Adjudication 2 deferred, so the portal's
 *      `permissions: 'owner'|'manager'|'trainer'` (`portal
 *      src/api/types.ts:219`) now has the wire's words. It is still not a
 *      second authorization model: the portal draws from `capabilities`,
 *      never from `role`, and `role` is for display ("signed in as Amber ·
 *      Manager", design §2.10:4640-4641).
 *    · The portal calls this field `campus`; the wire carries `home_locations`,
 *      DISPLAY labels (same translation as `MeWire.location`).
 *    · `isTrainer` / `availability` are not on `/me` and are not added.
 *  An expired staffer never reaches this shape: sign-in reads
 *  `staff.expired_at` only (`auth/mirror.ts:33`), and her bearer is 403
 *  `not_provisioned` on every route, this one included (see `ApiErrorCode`). */
export interface StaffMeWire {
  id: string;
  name: string;
  /** Descriptive: what the staffer is called, never what she may do — that is
   *  `capabilities`. */
  role: StaffRole;
  /** The staffer's home campuses as DISPLAY labels (`slugToDisplay` of each
   *  `staff.home_locations` slug), NEVER EMPTY: M1.20's
   *  `CHECK (cardinality(home_locations) > 0)` holds it in the database
   *  (design §1.1:601-602; §2.1:1940-1949). Read it as a set; its order
   *  carries no meaning.
   *
   *  Descriptive only (STAFF-71): no route refuses a staffer outside her home
   *  campuses, and no 403 `campus_mismatch` exists anywhere in v1
   *  (§2.1:1943-1945). Replaces 1.13.0's `location: LocationDisplay | null`
   *  (BREAKING, 2.0.0-lg1.2; STAFF-U03, E67), so the null case is gone. */
  home_locations: LocationDisplay[];
  /** `''`, never `null` (`?? ''`, `staffProfile`). Unlike `MeWire`'s avatar
   *  this is NOT resolved to a signed URL — the staff read path has no
   *  equivalent of `withResolvedAvatar`, so a media-asset UUID stored here
   *  would reach the client unresolved. Transcribed as-is (§14.1); the
   *  resolver-parity question belongs to the portal wave. */
  image_path: string;
  /** What this staffer may do, computed by the server for the caller (new
   *  2.0.0-lg1.2; STAFF-U07; design §1.1:695-709, §2.1:2049-2079). */
  capabilities: StaffCapabilitiesWire;
}

/**
 * `StaffMeWire.capabilities` — nine booleans the server computes on each
 * `GET /me` from the caller's role, the settings registry, the five role lists
 * of `staff_settings` (`StaffSettingsWire`) and `pay.refund_any_role_limit_cents`
 * (design §1.1:695-709; §2.1:2049-2079). Replaces 1.13.0's "no per-`StaffRole`
 * authorization gating exists anywhere in the backend" note: from 2.0.0-lg1.2
 * the backend gates by role (`requireStaffRole`) and by registry class
 * (`RefusedKeysDetails`). The list-gated verbs (refund, credit hand-edit, desk
 * sale, custom invoice, end-of-day totals) land at design 5.0.0 and later; each
 * will read its list at the verb.
 *
 * Each flag uses the rule its verb's guard uses, or will use when the verb
 * lands. `edit_prices` is false for every role, and from 5.0.0-lg4.2
 * `POST /staff/rates` takes no price but the evaluation's seed, 0
 * (§2.1:2087-2091; DAY-U23, moved from design 4.0.0 by §1.3). A list-backed
 * flag is true when the caller's role is `owner` OR is on that list: the owner
 * role passes every list whatever the list holds (STAFF-09), so the owner
 * can never be edited out of a verb. Five of the nine are data (owner-edited
 * lists), not role constants, which is why a client reads these booleans and
 * never derives them from `role`.
 *
 * A courtesy, not the gate: the portal hides what a flag says is false, and
 * the server refuses it anyway (design §2.1:2079, §2.10:4924-4926). The values
 * are as of this response, so an owner's edit of a list shows at the caller's
 * next `GET /me`. Seeded values: owner every flag true but `edit_prices`; manager
 * the same; trainer only `desk_sale` and `cash_day_totals` (s18,
 * SIGNOFF.md:121). No `refund_over_limit` (never built: no refund ladder
 * exists, F2; §1.1:729-731) and no `open_cash_totals`.
 */
export interface StaffCapabilitiesWire {
  /** Edit a `price`-class setting (STAFF-14). FALSE FOR EVERY ROLE IN v1, the
   *  owner included: the `price` class has no role (question 27 → (a); every
   *  price is its seed), so the registry refuses every price key with 403
   *  `refused_keys`. True only when PAY-U44 gives prices an editor.
   *  The legacy `POST /staff/rates` and `/staff/rates/:id/void` do NOT read
   *  this flag: they are owner and manager by role, and the POST takes only
   *  the evaluation's seed (DAY-U23, moved from design 4.0.0 by §1.3;
   *  §2.1:2084-2091). */
  edit_prices: boolean;
  /** Edit a `money`-class setting (STAFF-77). Owner and manager; the trainer
   *  never. A fixed role rule with no list or switch (STAFF-U08 folds in;
   *  §3.14:5957-5958). The same two roles pass the legacy editor's
   *  `requireStaffRole('owner', 'manager')`: `POST /staff/rates` and its
   *  void. `PATCH /staff/cancel-window/:category` is removed at 6.0.0-lg5.2:
   *  the cancellation policy is the `cxl` settings domain's. */
  edit_money_policy: boolean;
  /** Open the money reports (STAFF-12). Owner and manager; the trainer never.
   *  The end-of-day totals are NOT behind this flag: they follow
   *  `cash_day_totals` (s15, SIGNOFF.md:118; §1.1:699-701). */
  open_money_reports: boolean;
  /** See a family's payment history and cards on file (STAFF-13). Owner and
   *  manager; the trainer never. A trainer still opens any family's
   *  invoices. */
  open_payment_history: boolean;
  /** Refund money, any amount up to what was paid (F2, R4). True for the
   *  owner, for a role on `StaffSettingsWire.refund_roles` (seeded owner,
   *  manager), and for EVERY role while `pay.refund_any_role_limit_cents` is
   *  above 0 (seeded 0) (§1.1:697-699). The refund verbs it gates land at
   *  design 6.0.0. */
  refund_money: boolean;
  /** Add or remove credits by hand and move a lot's expiry (A11, R4). True for
   *  the owner and for a role on `StaffSettingsWire.credit_hand_edit_roles`
   *  (seeded owner, manager). It mirrors the guard on `POST
   *  /staff/owners/:ownerId/credit-adjustments`, `PATCH /staff/credit-lots/:id`
   *  and `PATCH /staff/credit-packages/:key`, each 403
   *  `credit_edit_role_required` for any other role. */
  edit_credits: boolean;
  /** Raise, charge and void a custom invoice: the portal's *New invoice* and
   *  *Charge card on file* (R8; C5). True for the owner and for a role on
   *  `StaffSettingsWire.custom_invoice_roles` (seeded owner, manager). Not
   *  *Mark paid*: that follows `desk_sale`. The verbs land at design 6.1.0. */
  custom_invoice: boolean;
  /** Record a cash or check desk sale, and *Mark paid: cash / check* on an open
   *  custom invoice (A7, A10; conflict 4). True for the owner and for a role
   *  on `StaffSettingsWire.desk_sale_roles` (seeded owner, manager, trainer).
   *  The verbs land at design 6.1.0. */
  desk_sale: boolean;
  /** See the end-of-day sheet's totals, the one gate on them (s15,
   *  SIGNOFF.md:118; reverses conflict 10's "the totals follow
   *  `open_money_reports`"). True for the owner and for a role on
   *  `StaffSettingsWire.cash_day_totals_roles` (seeded owner, manager,
   *  trainer). The sheet lands at design 6.1.0. */
  cash_day_totals: boolean;
}

/** `GET /me` returns ONE OF TWO SHAPES, chosen by the caller's principal kind
 *  (the `GET /me` handler in `routes/me.ts`): owner → `MeWire`, staff →
 *  `StaffMeWire`. Promoted 1.13.0 — digest auth-media/S + /M.
 *
 *  The union carries NO discriminant field — there is no `kind` on either arm,
 *  and adding one would be a behavior change, not a doc change, so it is
 *  documented rather than fixed. In practice a client knows its own principal
 *  kind; one that does not must probe structurally (`'role' in res`). */
export type GetMeResponse = MeWire | StaffMeWire;

/** `POST /uploads/sign` response. Promoted 1.13.0 from `routes/uploadsSign.ts:56-68`
 *  — digest auth-media/M; name GRANDFATHERED verbatim (§4.4). Step 1 of the
 *  mobile presign-direct path: sign → client PUTs bytes straight to R2 →
 *  `POST /media` registers (BUSINESS-LOGIC/reports-media.md:73 R15). */
export interface UploadsSignResponse {
  /** Presigned PUT URL — the client PUTs bytes directly to this URL. */
  url: string;
  /** Headers the client MUST send with the PUT (signed-in Content-Type). */
  headers: Record<string, string>;
  /**
   * The R2 object key the upload lands at. Pass this to POST /media after
   * the PUT completes. Server-generated — clients cannot specify.
   */
  key: string;
  /** ISO timestamp at which the presigned URL stops working. 15-minute TTL
   *  (`uploadsSign.ts:32`; reports-media.md:80 R22). */
  expires_at: string;
}

/**
 * `GET /staff/owners` `[staff]` row — one family, for the owner picker every
 * portal money screen opens from (Desk sale, New invoice, Refund, Add credits).
 * New 2.0.0 (P03; design-added, §1.1:718-719, §2.1:2153-2157, r3-opus #22).
 *
 * Any staff role reads it; an owner (family) principal is 403 `forbidden`.
 * **No money field**, by design: no card, invoice, credit or payment fact. A
 * family's payment history and cards stay owner and manager only (STAFF-13),
 * on `GET /staff/owners/:id/payments` and `/payment-methods` (§ payments-invoices).
 *
 * The list is every LIVE owner row (`owners.expired_at IS NULL`; a deleted
 * account is expired and its contact columns scrubbed), ordered by what a
 * reader prints, `lower(coalesce(name, email))`, then `id`. No query string
 * and no paging: the whole list (five families in the pilot; LG10's import
 * brings the rest — a paging parameter would be an additive change). Each
 * field mirrors its `owners` column, except that a stored `name` or `phone`
 * with no visible character reads (and sorts) as `null`. BREAKING
 * 3.0.0-lg2.1 (M2.01; ACCT-U04):
 * `name`, `phone` and `location` may be `null` (NON-OMIT: never omitted);
 * `id`, `email` and `source` never are. A reader that prints a name prints
 * `email` when `name` is `null` (design §2.2:2244).
 */
export interface StaffOwnerWire {
  id: string;
  /** `null` when the family has none (3.0.0-lg2.1); print `email` then. */
  name: string | null;
  email: string;
  /** `null` when the family has none (3.0.0-lg2.1). */
  phone: string | null;
  /** The family's home campus — `owners.location` as the SLUG, as every
   *  location field on this contract but `/me`'s. `MeWire.location` is the
   *  same column as a display label; a client must not compare the two. The
   *  design calls it "campus". A third `locations` row emits a slug outside
   *  `LocationKey` — the mirror hole `LocationDisplay` documents. `null` when
   *  the family has no home campus (3.0.0-lg2.1). */
  location: LocationKey | null;
  /** `owners.source`, as stored; `'gingr'` marks a family LG10's import
   *  wrote. */
  source: RecordSource;
}

/** `GET /staff/owners` response (200) — see `StaffOwnerWire`. */
export type GetStaffOwnersResponse = StaffOwnerWire[];

// --- (c) request bodies + query shapes --------------------------------------

/** `PATCH /me` body — owner self-edit. Promoted 1.13.0 from `patchMeSchema`
 *  — digest auth-media/M. Pinned to the Zod schema by `PatchMeBodyConformance`
 *  (`routes/me.ts`, §5.1.3). Rule: BUSINESS-LOGIC/auth-accounts.md:39 (R14).
 *
 *  Semantics the type cannot state (§4.6 — doc comments, not type gymnastics):
 *    · Every key is optional (`.partial()`), but an EMPTY effective patch is a
 *      400, not a no-op (the handler's `Object.keys(set)` check, `routes/me.ts`).
 *    · Unknown keys are REJECTED (`.strict()`) — a typo 400s rather than
 *      silently no-opping.
 *    · `email` is deliberately absent: identity is not self-editable here.
 *    · `emergency_contact` and `address` are WHOLE-OBJECT REPLACE, not merge:
 *      every sub-key is required (omitting one is a 400), and `''` blanks that
 *      column (`patchMeSchema`, `toOwnerUpdate`).
 *    · An `Idempotency-Key` header is REQUIRED; the write runs through the
 *      audited `withMutation` wrapper (actor `owner:<id>`, retries replay the
 *      stored outcome) — `requireIdempotencyKey` and `withMutation` in the
 *      `PATCH /me` handler; auth-accounts.md:107.
 *    · Staff principals get 403 (the handler's `principal.kind` check); a
 *      staff self-edit route does not exist.
 *    · The sign-up map (`acct.signup_field_requirement_map`), read on every
 *      call — 3.0.0-lg2.1 (design §2.2:2244; ACCT-U04). `name`, `phone` and
 *      `location` take `null` to clear; a `name` or `phone` with no visible
 *      character is the same as `null`; either is stored as NULL, so `MeWire`
 *      reads `null`, never `''`. A body that would leave a `mandatory` field
 *      empty (each field's test is on `ProfileIncompleteDetails`) is 422
 *      `profile_incomplete`. A body that NAMES a field the map marks `off` is
 *      400 `bad_request`, whatever its value — send only the fields that
 *      changed. Refusal order: every 400 (the Idempotency-Key, the strict
 *      parse, an empty patch, an `off` field) before the 422. The other keys
 *      (avatar, notification prefs, `show_dogs_on_welcome`) are outside the
 *      map and never refused by it.
 *    · `POST /me/signup` is RESERVED: not built in v1 and not typed (design
 *      §1.1:758-760; question 29: ACCT-U06's route half and ACCT-U07 are
 *      dated before the full transfer). The invite and the Stage A seed are
 *      the only doors to an owner row.
 *  Response is `MeWire`. */
export interface PatchMeRequest {
  /** `null` clears (3.0.0-lg2.1); a string with no visible character is the
   *  same as `null`. */
  name?: string | null;
  /** As `name`. */
  phone?: string | null;
  /** The DISPLAY label, not the slug — translated to the slug server-side
   *  (`displayToSlug` in `toOwnerUpdate`). `null` clears (3.0.0-lg2.1). */
  location?: LocationDisplay | null;
  /** A media-asset UUID here MUST be the caller's own, live, and of purpose
   *  `owner-avatar`, or the write 4xxs (`assertOwnedImagePath` in the
   *  `PATCH /me` handler) — the guard that stops an owner pointing their
   *  avatar at another tenant's media id. A non-UUID path is left permissive. */
  avatar_image_path?: string;
  emergency_contact?: MeEmergencyContactWire;
  address?: MeAddressWire;
  push_notifications_enabled?: boolean;
  /** An ARBITRARY record — `z.record(z.unknown())` (`patchMeSchema`): any
   *  string key, any JSON value, no vocabulary enforced, written straight to
   *  the jsonb column. This is the truthful transcription of what the endpoint
   *  ACCEPTS, and it is deliberately NOT tightened to the six live toggles
   *  (§14.1; the vocabulary is a phase-3 ruling — approved §6-batch #4
   *  collapsed the panel only). See `MeWire.push_notification_categories`
   *  for the live key list and the opt-OUT semantics. Note the ASYMMETRY with
   *  the response, which is `unknown`: the request is what this route validates,
   *  the response is what the unconstrained column may hold. */
  push_notification_categories?: Record<string, unknown>;
  email_notifications_enabled?: boolean;
  /** Same open-record truth as `push_notification_categories`. No sender reads
   *  it (DISCREPANCIES.md:519 DRIFT-46). */
  email_notification_categories?: Record<string, unknown>;
  show_dogs_on_welcome?: boolean;
}

/** `POST /uploads/sign` body. Promoted 1.13.0 from `routes/uploadsSign.ts:50-54`
 *  — digest auth-media/M; name GRANDFATHERED verbatim (§4.4). Pinned by
 *  `UploadsSignBodyConformance` (`routes/uploadsSign.ts`, §5.1.3).
 *
 *  Semantics: `.strict()` (unknown keys rejected). NO `Idempotency-Key` is
 *  required — this route writes no DB row; a retry just mints a fresh key + URL
 *  and the orphan object is tolerated until a Day-20+ sweep
 *  (`uploadsSign.ts:26-29`; reports-media.md:83 R25). `content_type` must match
 *  `purpose` or the request 400s (`assertContentTypeMatchesPurpose`,
 *  `lib/mediaKeys.ts:34-61`): image purposes take
 *  jpeg/png/webp/heic/heif, `report-video` takes mp4/quicktime/webm, and
 *  `message-attachment` takes EITHER. */
export interface UploadsSignRequest {
  /** ALL FIVE purposes are accepted here from ANY authenticated principal —
   *  owner or staff (`uploadsSign.ts:42-48,86`) — even though `POST /media`
   *  splits the same five by role (owner: dog-profile/owner-avatar/
   *  message-attachment; staff: report-photo/report-video —
   *  `routes/media.ts:134-139`). So a signed URL is obtainable for a purpose
   *  the caller cannot then register. Transcribed, not fixed: whether to gate
   *  purposes here is digest item auth-media (design/S), deferred. */
  purpose: MediaPurpose;
  content_type: string;
  /** ADVISORY at sign time: logged for observability, never enforced
   *  (`uploadsSign.ts:110-113`). The real bytes are read back with
   *  `r2.headObject` at register time and THAT is what the row records
   *  (reports-media.md:74 R16). Zod caps it at `MAX_UPLOAD_BYTES` = 25 MB
   *  (`lib/mediaKeys.ts:15`), so an over-cap CLAIM 400s even though an
   *  under-claimed large upload does not. */
  byte_size: number;
}

/** `POST /media` body — register an upload that already landed in R2. Promoted
 *  1.13.0 from `routes/media.ts:84-91` — digest auth-media/M. Pinned by
 *  `PostMediaBodyConformance` (`routes/media.ts`, §5.1.3).
 *
 *  Semantics the key-level types cannot state (§4.6):
 *    · `.strict()`; `Idempotency-Key` REQUIRED (`media.ts:128`).
 *    · The route splits on `purpose` BEFORE any R2 round-trip: `report-photo`/
 *      `report-video` are STAFF-only (owner → 403) and the row's owner is
 *      resolved `report_id → report.dog_id → dogs.owner_id`; the other three
 *      are OWNER-only (staff → 403) — `media.ts:134-139`; reports-media.md:138.
 *    · `dog_id` is REQUIRED for `dog-profile` and forbidden for every other
 *      purpose; `report_id` is REQUIRED for the two staff purposes and
 *      forbidden for the owner purposes; supplying `dog_id` alongside a staff
 *      purpose 400s (it is derived from the report) — `media.ts:365-374,413-438`.
 *      Both keys are optional-and-nullable at the TYPE level because that is
 *      what the schema accepts; the combination rules are enforced in code.
 *    · Missing R2 object → 422 `invalid_payload` with
 *      `MediaUploadMissingDetails` (`kind: 'media-upload-missing'` — kebab-case,
 *      historically; §3.2 note 2), `media.ts:502-512`; reports-media.md:74 R16.
 *  Response is `MediaWire` (201). */
export interface PostMediaRequest {
  /** The SERVER-generated R2 object key returned by `POST /uploads/sign`.
   *  Clients cannot choose or collide one (`lib/mediaKeys.ts:8-12,69-75`). */
  key: string;
  purpose: MediaPurpose;
  dog_id?: string | null;
  report_id?: string | null;
}

/** `POST /media/upload` query string — the Day-19c staff/portal proxy path,
 *  where the file bytes ride in the raw request body and the metadata rides
 *  here. Promoted 1.13.0 from `routes/media.ts:95-106` — digest auth-media/M
 *  (named "MediaUploadQuery" there; `<Method><PathPascal>Query` per §4.3).
 *  Pinned by `PostMediaUploadQueryConformance` (`routes/media.ts`, §5.1.3).
 *
 *  Semantics: `.strict()`; STAFF-ONLY (owner → 403, `media.ts:247`);
 *  `Idempotency-Key` REQUIRED, and its request hash covers THIS query (stable
 *  metadata), not the per-call random R2 key — so a replay returns the first
 *  row and the second PUT's object becomes a swept-later orphan
 *  (`media.ts:259-274`; reports-media.md:83 R25). Body cap 25 MB
 *  (`MAX_UPLOAD_BYTES`); the request's `Content-Type` header must match
 *  `purpose` (`media.ts:251-252`); an empty body 400s. `dog_id` is DERIVED from
 *  the report and is deliberately not a parameter. Response is `MediaWire` (201). */
export interface PostMediaUploadQuery {
  /** Only the two staff report purposes — a strict subset of `MediaPurpose`
   *  (`media.ts:103`). */
  purpose: Extract<MediaPurpose, 'report-photo' | 'report-video'>;
  report_id: string;
}

// --- (d) per-endpoint 422 union aliases -------------------------------------
//
// None this pass. §3.5 ships the typed-422 aliases for POST /bookings,
// POST /requests, POST /enrollments and POST /events/:id/rsvp only; minting a
// fifth for POST /media would be out of charter. The one arm this domain can
// 422 with is `MediaUploadMissingDetails` (§1) — cited on `PostMediaRequest`.

// <<< domain:auth-media =======================================================

// >>> domain:bookings =========================================================

export interface BookingWire {
  id: string;
  dog_id: string;
  additional_dog_ids?: string[];
  category: ServiceCategory;
  status: BookingStatus;
  /** The session's scheduled start as an ISO instant (UTC, e.g.
   *  `2026-11-11T13:30:00.000Z`), never a bare calendar day: a client takes the
   *  day it shows from this instant in America/Chicago (P20 round 2, M1). */
  date: string;
  trainer?: string;
  duration_minutes?: number;
  notes?: string;
  session_report_id?: string;
  location?: LocationKey;
  // Omit-on-null: `bookings.cancel_deadline_at`, where a free-cancel window
  // used to close (Δ 2026-07-08). From 6.0.0-lg5.2 no cancel forfeits and no
  // route stamps one (design §2.7:4115-4127, question 54; CXL-U04): M5.08 drops
  // `cancel_window_settings`, its one source, so a row booked from this version
  // never carries it. A row stamped earlier keeps its instant, which nothing
  // reads: no cancel consults it, and the app shows no cancel warning (CXL-U05).
  // Not a deadline to show.
  cancel_deadline_at?: string;
  cancelled_at?: string;
  // On a cancelled row only. From 6.0.0-lg5.2 every cancel writes `false`:
  // nothing is withheld (CXL-U04, CXL-01; design §2.7:4115-4127; 12-:67-69 "no
  // true penalty"), and no amount is reported (`cancel_withheld_cents` is never
  // built, §1.1:1135-1136). `true` stays only on a row cancelled before this
  // version inside the old 48-hour window.
  cancel_forfeited?: boolean;
  // Who cancelled + why (R5, Allison sim-QA 2026-07-27). Emitted only on a
  // cancelled booking, omit-on-null like `cancelled_at`. `cancelled_by` = 'owner'
  // (self-cancel → "You cancelled this on …") or 'staff' ("The school cancelled
  // this on …"); `cancel_reason` is the optional staff-supplied reason line.
  cancelled_by?: 'owner' | 'staff';
  cancel_reason?: string;
  // Group-class only (DATA-CONTRACT §A Amendment 2026-06-01). `cohort_id` is the
  // stable key the FE groups weekly sessions by; `group_class_name` titles the card.
  cohort_id?: string;
  group_class_name?: string;
  // Private-lesson only (Δ 2026-07-14): where the lesson happens — 'home'
  // (client's home) or 'public' (public spot). Owner-picked at request time,
  // copied onto the booking at approve; omitted on every other category.
  lesson_setting?: LessonSetting;
  // The order this session belongs to (4.0.0-lg3.2, M3.02; PAY-U04). Every
  // session of one `POST /bookings` carries the same id. Omit-on-null: a row
  // made any other way has no order, and neither does an older one.
  order_id?: string;
  // Whether a cancel of the WHOLE session would be accepted now (6.0.0-lg5.1;
  // design §1.1:1064-1067, §2.3:2418-2428; CXL-U09, CXL-U10). Present on every
  // day-school and day-care row and omitted on every other category (the
  // evaluation row joins with P09, plan `deferred_arms`). `false` once the
  // session is cancelled, once any dog still on it has folded past `expected`
  // (`AttendanceStatus`; an undone check-in does not count), and once Chicago
  // now reaches the campus's `day.pickup_close_time` on its date. It reads the
  // same fold and clock as the cancel's 409s, so a `true` can still meet one if
  // a check-in or the clock lands between the read and the tap: show that 409
  // as a refusal, never as a connection error. A pending row is cancellable (it
  // cancels its whole order, `BookingStatus`).
  can_cancel?: boolean;
  // One entry per dog the session was booked for, the shares cancelled alone
  // included (6.0.0-lg5.1; design §1.1:1068-1075, §2.3:2429-2447; CXL-U09, s11).
  // Present on every day-school and day-care row, a one-dog session included,
  // and omitted on every other category. Order: `dog_id`, then
  // `additional_dog_ids` in their order, then the shares cancelled alone,
  // ascending by `cancelled_at`.
  //   `can_cancel`: whether `POST /bookings/:id/dogs/:dogId/cancel` (an owner's
  //   read) or `POST /staff/bookings/:id/dogs/:dogId/cancel` (a staff read) would
  //   accept this dog now: her share and the session not cancelled, the row not
  //   `payment-pending`, the clock before `day.pickup_close_time`, and HER folded
  //   state `expected`. On an owner's read it is also `false` while
  //   `cxl.per_dog_cancel_enabled` is off, which a staff cancel ignores.
  //   `after_school`: this dog is opted in to that day's after-school session
  //   (6.0.0-lg5.2; design §1.1:1083-1085, §2.3:2558-2564; DAY-U43), as
  //   `PostBookingsRequest.after_school` sent it. Always `false` on a day-care
  //   row. No route changes it after the booking.
  //   `return_expires_at`: ISO-8601 (6.0.0-lg5.2; design §2.3:2741-2748,
  //   §2.7:4412-4414; CXL-U05), on each share still on an `'upcoming'` session
  //   whose credit has not come back: the expiry that credit would carry if it
  //   came back now, so a cancel sheet names it before Confirm. It is her live
  //   debit's lot's `expires_at` while that lot expires after the next Chicago
  //   midnight; else the fresh lot's, now plus `cred.returned_credit_expiry_months`
  //   (seeded 1; design §2.4:2958-2964). Two arms keep the lot's own date even
  //   when it is passed or passing today: with that key at 0 the credit comes
  //   back into its lot dead, and the sheet says so; with
  //   `cred.expiry_enforced_enabled` off nothing expires, so the credit goes
  //   back into its lot and the date names the lot, not a deadline.
  //   `cred.booking_outlives_lot_expiry_enabled` plays no part: a returned
  //   credit is unbooked, so a lot dying tonight would take it. Read on
  //   `can_cancel`'s clock; the return itself reads the lot again under its
  //   locks.
  //   `cancelled_at`: ISO-8601, on a share cancelled alone, before its session.
  //   A share that went with its session carries none (read `cancelled_at`
  //   above), and that includes the last dog of a session cancelled one dog at a
  //   time: cancelling her cancels the session.
  // `dog_id` and `additional_dog_ids` list only the dogs whose shares were not
  // cancelled alone, so a card never names a dog who is not coming. When the
  // lead's share is cancelled alone, `dog_id` is the first remaining dog in
  // `additional_dog_ids`' order and she leaves that list.
  dog_shares?: {
    dog_id: string;
    can_cancel: boolean;
    after_school: boolean;
    return_expires_at?: string;
    cancelled_at?: string;
  }[];
}

/** Δ 2026-07-14 — where a private lesson happens. */
export type LessonSetting = 'home' | 'public';

/**
 * The six kinds of the check-in log, the `checkin_event_kind` pgEnum (M5.01;
 * 6.0.0-lg5.1; design §1.1:1027-1031, conflict 20; DAY-U29, DAY-U33), which
 * `conformance.ts` pins. `'no-show'` is the board's *Didn't come*. There is no
 * `attended` kind and no `hand-off` kind: a hand-off to Shanthi is a
 * `check-out` whose `note` says so (DAY-51), and settles nothing. The three
 * settling kinds are `'turn-away'`, `'sent-home'` and `'no-show'`: a share holds
 * at most one (M5.02's partial unique index), and none can be undone.
 */
export type CheckinEventKind =
  | 'check-in'
  | 'check-out'
  | 'undo'
  | 'turn-away'
  | 'sent-home'
  | 'no-show';

/**
 * One appended event of one dog on one booking (6.0.0-lg5.1; design
 * §1.1:1027-1041, §2.3:2354-2405; DAY-U29, DAY-U33). The log is append-only: no
 * event is ever edited or deleted, and a mistake is corrected by an `undo` that
 * names it (`undoes_event_id`).
 *
 * `at` is the server's clock when the verb ran, ISO-8601; no body sets it, and
 * it is display only. `by_staff_id` is the staffer who tapped. Optional keys are
 * omitted where the column is null:
 *   - `undoes_event_id` on an `undo`: the event it removed.
 *   - `training_completed` on a `sent-home`: the *Finished training day* box.
 *   - `reissue_credit` on a `check-out`: the *Re-issue the credit* box.
 *   - `note` on a `check-out` that carried one.
 *   - `settlement` on an event that decided a credit: each settling kind, and a
 *     `check-out` with `reissue_credit: true`. `returned_credits` is the credits
 *     that event's own transaction returned to the owner's pool, `1` or `0` (a
 *     send-home marked finished): what was written then, not a recomputation
 *     from today's fractions.
 */
export interface CheckinEventWire {
  id: string;
  booking_id: string;
  dog_id: string;
  kind: CheckinEventKind;
  at: string;
  by_staff_id: string;
  undoes_event_id?: string;
  training_completed?: boolean;
  reissue_credit?: boolean;
  note?: string;
  settlement?: { returned_credits: number };
}

/**
 * The response of each of the six board verbs, `POST
 * /staff/bookings/:id/dogs/:dogId/{check-in | check-out | undo | turn-away |
 * send-home | no-show}`: that dog's folded state on that booking after the
 * verb, and her whole log on it, in append order, undone events and the `undo`s
 * included (6.0.0-lg5.1, BREAKING; design §1.1:1042-1044; DAY-U29). Was the
 * response of `POST /staff/bookings/:id/attendance`, `{booking_id, dog_id,
 * attendance, checked_in_at}`, removed.
 */
export interface AttendanceWire {
  status: AttendanceStatus;
  events: CheckinEventWire[];
}

/**
 * One row of `GET /staff/checkin-board?location&date`: one dog's share of one
 * session at that campus on that date (6.0.0-lg5.1; design §1.1:1044-1049,
 * §2.3:2406-2428, §2.10:5051-5069; DAY-U29, DAY-U30, DAY-U33, DAY-U40, CXL-U09,
 * CXL-U11). The board lists every share still on a day-school or day-care
 * session that is not cancelled; a share or session cancelled leaves it. The
 * evaluation row joins with P09 (plan `deferred_arms`).
 *
 * `booking_id`, `dog_id` and `events` are the row's address and its log: the
 * six verbs and the one-dog cancel take the first two in their path, and the
 * stamped times and the undo target are read from `events` (as `AttendanceWire`).
 * The session's own facts — category, the other dogs, the order — are
 * `BookingWire`'s, read from `GET /staff/bookings` with `from` and `to` the
 * board's date and the same `location`.
 *
 *   - `state`: the folded state (`AttendanceStatus`).
 *   - `booking_status`: the session's, `'upcoming'` or `'payment-pending'`
 *     (never `'cancelled'`, which leaves the board). `payment_pending` is `true`
 *     exactly when it is `'payment-pending'`: a top-up order still processing,
 *     on which every verb answers 409 `payment_pending` until Stripe answers.
 *   - `late_pickup_due`: on site (`'in'` or `'sent-home'`) and Chicago now at or
 *     past the campus's `day.late_pickup_call_time` on the board's date: the
 *     courtesy call. Never `true` in any other state. Nothing checks a dog out
 *     on its own (DAY-68).
 *   - `settled`: the share holds a settling event (`CheckinEventKind`), so no
 *     cancel, second settling event or `undo` of it is accepted. A sent-home dog
 *     checked out folds `'out'` and stays settled.
 *   - `can_cancel`: as `BookingWire.dog_shares[].can_cancel` on a staff read,
 *     for this dog.
 *   - `after_school`: as `BookingWire.dog_shares[].after_school`, for this dog
 *     (6.0.0-lg5.2; DAY-U43). `late_pickup_due` does not read it: an
 *     after-school dog on site is flagged at `day.late_pickup_call_time` like
 *     any other (question 89's default; DAY-U41, which moves her flag to
 *     `day.after_school_end_time`, is later), and staff read past the flag.
 *   - `gate_warnings`: a gate this dog fails on the board's date that her
 *     booking passed, read with the booking gate's own reads, `[]` when none.
 *     Check-in still lands (the door decides, DAY-05); the row offers *Turn
 *     away*. `'vaccine_lapsed'` is sent from 6.0.0-lg5.1. `'spay_neuter_overdue'`
 *     is typed and sent from P09 (S11), and `'reevaluation_due'` typed and sent
 *     once S14 lands (dated): no route sends either before then.
 * `draft_report_id?` joins at design 8.0.0 (RPT-U07). There is no
 * `unrecorded_earlier`: a day nobody recorded is fixed on that date's board
 * (question 50 → (c)).
 */
export interface CheckinBoardWire {
  booking_id: string;
  dog_id: string;
  state: AttendanceStatus;
  events: CheckinEventWire[];
  booking_status: BookingStatus;
  late_pickup_due: boolean;
  settled: boolean;
  can_cancel: boolean;
  after_school: boolean;
  payment_pending: boolean;
  gate_warnings: ('vaccine_lapsed' | 'spay_neuter_overdue' | 'reevaluation_due')[];
}

/** `GET /staff/checkin-board` response: the board's rows. No order is promised;
 *  the portal sorts. `[]` for a day with no share. */
export type GetStaffCheckinBoardResponse = CheckinBoardWire[];

export interface PendingRequestNotesWire {
  per_dog?: string;
  joint?: string;
}

export interface PendingRequestFocusWire {
  staff_preference?: string;
  // Δ 2026-06-17: staff-defined multi-select trait pills replaced the single
  // `comfort_level` enum.
  descriptor_keys?: string[];
}

export interface PendingRequestWire {
  id: string;
  dog_id: string;
  additional_dog_ids?: string[];
  category: ServiceCategory;
  submitted_at: string;
  preferred_dates: string[];
  notes?: PendingRequestNotesWire;
  focus: PendingRequestFocusWire;
  length_weeks?: number;
  status: RequestStatus;
  approved_at?: string;
  // Δ 1.13.0 (digest bookings/S; closes DRIFT-8 @
  // BUSINESS-LOGIC/DISCREPANCIES.md:291). The staff actor on a STAFF-driven
  // resolution — stamped by approve (`markApprovedAwaitingPayment`,
  // `markConverted`) and by deny (`markCancelled`), all in `staffRequests.ts`,
  // and left NULL by an owner self-cancel (`POST /requests/:id/cancel`).
  // It is the discriminator the client branches on to render "Denied by the
  // school" vs "You cancelled this", because `request_status` has no 'denied'
  // member (DATA-CONTRACT.md:1217-1222; the column is on `pending_requests`). Omit-on-null
  // like its neighbours: present ⇒ staff acted, absent ⇒ they did not.
  approved_by_staff_id?: string;
  converted_booking_id?: string;
  // Private-lesson only (Δ 2026-07-14): where the lesson should happen.
  lesson_setting?: LessonSetting;
}

/**
 * `POST /bookings` 201 body (4.0.0-lg3.2; design §1.1:857-863; PAY-U04, DAY-U16).
 * It replaces the bare `BookingWire[]`: one Confirm is one order, credits-only
 * included. `sessions` holds one row per date, ascending by `scheduled_at`, each
 * with `order_id` = `order.id`. A same-key replay returns this body as stored.
 *
 * `order.charge_status` is `'none'` unless a top-up was charged, and every
 * session is then `'upcoming'`. With a top-up it is `'succeeded'`, every session
 * `'upcoming'`, or `'requires_payment'`, every session `'payment-pending'`
 * (`PostBookingsRequest`).
 */
export interface PostBookingsResponse {
  order: OrderWire;
  sessions: BookingWire[];
}

// ---- (a) domain-local value tuples -----------------------------------------
// Runtime arm lists for the two per-endpoint 422 aliases below (§2.1(d)). They
// exist because a type alias cannot be asserted in the backend's `test/` tree —
// it runs type-ERASED (designs/wire-contract-completion.md §14.5) — so the
// §3.5 "provoke an arm, parse the envelope as the alias" pin needs a runtime
// value to check membership against. `satisfies` guards the bogus-member
// direction here; §16 pins set equality (WC-A1 form).

/** Every `details.kind` `POST /bookings` can refuse with — the runtime twin of
 *  `PostBookingsErrorDetails`, 422 but for `payment_failed`, which is 402. Order
 *  mirrors the gate/check execution order in `lib/bookingGatePreCheck.ts` then
 *  `lib/createDayProgramBookings.ts`, then the charge.
 *  New 1.13.0 (digest bookings/L). */
export const POST_BOOKINGS_ERROR_DETAIL_KINDS = [
  'payment_required',
  'evaluation_required',
  'vaccine_missing',
  'agreement_unsigned',
  'credit_expired_before_date',
  'insufficient_credits',
  'already_booked',
  'insufficient_capacity',
  'after_school_full',
  'payment_failed',
] as const satisfies readonly [
  PostBookingsErrorDetails['kind'],
  ...PostBookingsErrorDetails['kind'][],
];

/** Every `details.kind` `POST /requests` can 422 with — the runtime twin of
 *  `PostRequestsErrorDetails`. New 1.13.0 (digest bookings/L). */
export const POST_REQUESTS_ERROR_DETAIL_KINDS = [
  'evaluation_required',
  'already_requested',
] as const satisfies readonly [
  PostRequestsErrorDetails['kind'],
  ...PostRequestsErrorDetails['kind'][],
];

// ---- (c) request bodies + query shapes -------------------------------------

/**
 * `POST /bookings` body — day-program creation only (day-school / day-care).
 * Promoted 1.13.0 from `postBookingBodySchema` in `routes/bookings.ts`
 * (digest bookings/M "contract every request body"); pinned to that schema by
 * `PostBookingsBodyConformance` in the route file (§5.1.3, `z.input`).
 *
 * Every other category reaches its booking by a different door — group-class
 * via `POST /enrollments`, PL/B&T/boarding via `POST /requests` + staff
 * approve, evaluation via a staff-picked slot — so `category` is genuinely two
 * values here, not a narrowed `ServiceCategory`.
 *
 * A day-program booking carries no arrival time (4.0.0-lg3.1; DAY-U11): each
 * session's `scheduled_at` is the campus's `day.dropoff_open_time` on its date,
 * America/Chicago, and the reminders follow from it. No cancel deadline is
 * stamped (6.0.0-lg5.2; question 54).
 *
 * Zod-enforced bounds, transcribed (NOT tightenable by a client rereading
 * this): `dates` 1..30 entries (`MAX_DATES_PER_REQUEST`, a constant: a
 * request-size guard), each `YYYY-MM-DD` and a real calendar date;
 * `additional_dog_ids` ≤ 99 (a hostile-body ceiling, not the roster rule, which
 * is the setting below); `notes` ≤ 2000 chars. The body is `.strict()`: an
 * unknown key is 400 `bad_request`,
 * like every Zod failure on this route (`parseOrThrow`), and since 4.0.0-lg3.1
 * that includes `dropoff_time`. `payment` and `payment.top_up` are `.strict()`
 * too. `top_up.count` and `top_up.expected_total_cents` are positive integers,
 * `top_up.payment_method_id` a UUID, `top_up.package_key` a `CreditPackageWire`
 * key.
 *
 * Cross-field rules Zod does not express (§4.6 — doc comments, not type
 * gymnastics). Each limit is a setting read at runtime, never a constant, and
 * a client reads it from `GET /settings`:
 *   - `lead_dog_id` must not repeat inside `additional_dog_ids`, and the ids
 *     must be distinct (`invalid_payload`).
 *   - at most `day.max_dogs_per_booking_count` dogs, the lead included
 *     (`invalid_payload`).
 *   - every date is distinct and today-or-later in America/Chicago
 *     (`invalid_payload`).
 *
 * Four refusals have a code of their own (4.0.0-lg3.1, the last 5.0.0-lg4.2;
 * design §2.3:2325-2328, §2.4:2949-2951),
 * each 422 with no `details`, and each refuses the whole request:
 *   - `program_not_offered` — `offerings[category].offered` is false at
 *     `location` (DAY-U04): as seeded, day-care at Fayetteville.
 *   - `beyond_booking_horizon` — a date is later than
 *     `day.booking_horizon_months` calendar months after today in
 *     America/Chicago, a day the target month lacks falling on its last day
 *     (DAY-U10, DAY-09).
 *   - `same_day_cutoff_passed` — a date is today in America/Chicago and the
 *     clock has reached the campus's `day.same_day_cutoff_time` (DAY-U10,
 *     DAY-07). This route is owner-only; the cutoff binds owners only (DAY-08).
 *   - `alumni_tier_requires_alumni_dog` — `payment.tier` is `'alumni'` and a dog
 *     of the request is not `is_alumni` (CRED-U10). An alumni credit pays only
 *     for an alumni dog, so one such dog refuses the whole body.
 * A closed date has no refusal of its own: its cap is 0, so the request meets
 * `insufficient_capacity`. `PostBookingsErrorDetails` lists the arms that do
 * carry `details`.
 *
 * `after_school` is the after-school opt-in, per dog per date (6.0.0-lg5.2;
 * design §1.1:1083-1085, §2.3:2558-2564; DAY-U43, question 47): a dog of this
 * request → the dates of `dates` on which she stays for the campus's
 * after-school session (`day.after_school_start_time` to
 * `day.after_school_end_time`). Each tick is her
 * `BookingWire.dog_shares[].after_school` on that date's session; omitted, or a
 * dog absent from it, opts no one in. A key that is not a dog of this request,
 * a date not in `dates` or listed twice, or any tick on a `day-care` request is
 * 422 `invalid_payload`; a key that is not a UUID or a value that is not a
 * calendar date is 400 `bad_request`, the strict parse. The session's price is
 * `day.after_school_price_cents` (seeded 0), never charged in v1 (DAY-U45
 * later). Each date's ticks are counted under its `(location, date)` lock,
 * right after its seats, against the campus's `day.after_school_capacity_count`:
 * a date that cannot take them all is 422 `after_school_full`
 * (`AfterSchoolFullDetails`), and the whole order is refused before any charge.
 *
 * Credits are the only tender (4.0.0; design §1.1:864-874; R1). `payment` is
 * required, so every booking says so, and it has no pay-as-you-go and no card
 * arm: a day is never charged, and the one charge a booking can carry buys
 * credits (`top_up`). The strings `'credits'` and `'payg'`, a
 * missing `payment` and a top-level `payment_method_id` are each 400
 * `bad_request`.
 *
 * `payment.tier` names the pool: a booking debits the owner's pool for its
 * campus, program and tier, `'regular'` when omitted (design §2.4:2949-2953;
 * CRED-U10). The server picks no pool. When two fit, the app asks her and sends
 * `tier` (CRED-20).
 *
 * `payment.top_up` buys the missing credits inside this request (design
 * §2.3:2613-2630, §2.7:4061-4092; PAY-U09). The client answers the 422's
 * `top_up_offer` by re-sending the same body with `top_up` under a fresh
 * `Idempotency-Key`, so *Yes* is one order and a decline books nothing.
 * `count` and `expected_total_cents` are what the sheet showed, and
 * `payment_method_id` the card it named. `package_key` defaults to the offer's
 * row and may name any live catalog row of the booking's pool; a pack is bought
 * whole, so its `count` is 1. Under its locks, before it writes anything, the
 * server re-reads the row and recomputes the shortfall. A total that differs, a
 * `count` of single days other than the shortfall, a pack with fewer credits
 * than the shortfall, a pack whose own lot would not pay every short date, or a
 * key naming neither row answers a fresh 422 `insufficient_credits`, with nothing
 * written and no Stripe call, so she is never charged a price she did not see,
 * for more days than the dates need, or for a lot that cannot pay them.
 * A `payment_method_id` that is not a live card of hers is the generic 404.
 * `cred.single_day_purchase_max_count` does not cap `count`: the dates do.
 *
 * A `top_up` that fits rides the order engine, one charge under the
 * `cancel-order` failure policy (design §2.3:2664-2677, §2.7:4083-4098):
 *   - 201, `order.charge_status: 'succeeded'`: the bought lot is granted and
 *     spent on the dates her lots could not pay, and every session is `'upcoming'`.
 *   - 201, `order.charge_status: 'requires_payment'` and `order.client_action:
 *     'processing'`: every session is `'payment-pending'` until Stripe answers.
 *     Do not retry.
 *   - 402 `payment_failed` (`PaymentFailedDetails`): nothing is booked, every
 *     debit is returned and nothing is granted. A replay returns the same 402,
 *     so the next try takes a fresh key.
 *   - 409 `idempotency_inflight`: no answer exists yet. Re-send under the same
 *     key; nothing more is charged.
 *
 * `Idempotency-Key` is required on this endpoint (§0 conventions). The
 * response is 201 `PostBookingsResponse`.
 * BUSINESS-LOGIC/bookings-scheduling.md R20 @ :90.
 */
export interface PostBookingsRequest {
  category: 'day-school' | 'day-care';
  lead_dog_id: string;
  additional_dog_ids?: string[];
  /** `YYYY-MM-DD` Chicago calendar days, 1..30, distinct. */
  dates: string[];
  location: LocationKey;
  notes?: string;
  /** Dog id → `YYYY-MM-DD` dates of `dates` (see above; 6.0.0-lg5.2). */
  after_school?: Record<string, string[]>;
  /** Credits, the only tender (see above). */
  payment: {
    kind: 'credits';
    tier?: CreditTier;
    top_up?: {
      count: number;
      payment_method_id: string;
      package_key?: string;
      expected_total_cents: number;
    };
  };
}

/**
 * `POST /requests` body — the owner-side request submission for the three
 * approval-flow categories (DATA-CONTRACT §C.1 Model 3). Promoted 1.13.0 from
 * `postRequestBodySchema` in `routes/requests.ts` (digest bookings/M); pinned
 * by `PostRequestsBodyConformance`.
 *
 * `notes` / `focus` reuse the response sub-shapes (`PendingRequestNotesWire`,
 * `PendingRequestFocusWire`): the request Zod objects `notesBodySchema` and
 * `focusBodySchema` are structurally identical to them today, and
 * the §5.1.3 pin is what keeps that true — if either side moves, the pin
 * fails and the wire type is corrected to the schema (§14.1).
 *
 * Zod-enforced bounds, transcribed: `preferred_dates` 1..3 ISO-8601 datetimes
 * WITH offset; `additional_dog_ids` ≤ 4; `length_weeks` 1..12;
 * `focus.staff_preference` ≤ 100 chars (trimmed); `focus.descriptor_keys`
 * ≤ 20 keys × ≤ 64 chars (trimmed, each non-empty); each note ≤ 2000 chars.
 * `.strict()` at both levels.
 *
 * Cross-field rules (`validatePostRequestBody`, `routes/requests.ts`):
 *   - board-and-train is SINGLE-DOG (`additional_dog_ids` rejected) and
 *     REQUIRES `length_weeks`; private-lesson + boarding must OMIT it.
 *   - `lesson_setting` is private-lesson only (Δ 2026-07-14).
 *   - dog ids distinct; every preferred date strictly in the future.
 * All of the above are `invalid_payload` (422).
 *
 * Two refusals have a code of their own (4.0.0-lg3.1), each 422 with no
 * `details`:
 *   - `service_not_offered` — the service is off (design §1.1:936, §2.6:3727;
 *     question 2). The body names no campus and a request stores none, so the
 *     campus is the family's home campus (`owners.location`, read on
 *     `MeWire.location`), and `offerings[category].offered` false there
 *     refuses. A family with no home campus is refused only when no campus
 *     offers the service. As seeded, all three services are off everywhere.
 *   - `beyond_booking_horizon` — a preferred date is later than the horizon,
 *     reckoned as on `PostBookingsRequest` (DAY-U10; PL-39, BRD-06, BT-09).
 *
 * `Idempotency-Key` required.
 */
export interface PostRequestsRequest {
  category: 'private-lesson' | 'board-and-train' | 'boarding';
  lead_dog_id: string;
  additional_dog_ids?: string[];
  /** 1..3 ISO-8601 datetimes with offset, ranked; ordinal = array order. */
  preferred_dates: string[];
  notes?: PendingRequestNotesWire;
  focus?: PendingRequestFocusWire;
  /** board-and-train ONLY, and REQUIRED there. 1..12. */
  length_weeks?: number;
  /** private-lesson ONLY. */
  lesson_setting?: LessonSetting;
}

/**
 * `PATCH /requests/:id` body — the owner's edit surface while a request is
 * still `'submitted'`. Promoted 1.13.0 from `patchRequestBodySchema` in
 * `routes/requests.ts` (digest bookings/M); pinned by
 * `PatchRequestsBodyConformance`.
 *
 * Tri-state per key, and the type says so honestly: **omitted** = leave
 * unchanged, **`null`** = clear, **value** = set. `focus: null` clears BOTH
 * inner fields (`descriptor_keys` clears to `[]` — the column is NOT NULL);
 * `focus: { descriptor_keys: [] }` clears only that one
 * (`validatePatchRequestBody`). Empty/whitespace strings normalize to
 * cleared, so the response's omit-on-null round-trips.
 *
 * The three identity keys are typed `unknown` because that is exactly what
 * the schema accepts: they are listed in the `.strict()` object ONLY so an
 * attempt to change them meets a route-specific 422 ("category cannot be
 * changed after submission", `validatePatchRequestBody`) instead of Zod's
 * generic unrecognized-key error. Sending ANY value for one — `null`
 * included — is a 422. Typing them as `never` would be a tightening (§14.1):
 * the schema accepts the key and the route rejects it, which is not the same
 * thing as the client being unable to express it.
 *
 * Editing a request that is not `'submitted'` is 409 `conflict`;
 * `lesson_setting` on a non-private-lesson request is 422. A preferred date
 * later than the horizon is 422 `beyond_booking_horizon`, no `details`, as on
 * `POST /requests` (4.0.0-lg3.1; the two share
 * `assertPreferredDatesWithinWindow`). `Idempotency-Key` required (the body
 * rides the request hash, so a same-key replay with a
 * different body is 422 `idempotency_mismatch`).
 */
export interface PatchRequestsRequest {
  preferred_dates?: string[];
  notes?: PendingRequestNotesWire | null;
  focus?: PendingRequestFocusWire | null;
  length_weeks?: number | null;
  lesson_setting?: LessonSetting | null;
  /** Locked identity key — accepted by the schema, 422'd by the route. */
  category?: unknown;
  /** Locked identity key — accepted by the schema, 422'd by the route. */
  lead_dog_id?: unknown;
  /** Locked identity key — accepted by the schema, 422'd by the route. */
  additional_dog_ids?: unknown;
}

/**
 * `POST /requests/:id/confirm-payment` body — the board-and-train conversion
 * verb (Day 15, `[auth, $]`). Promoted 1.13.0 from `confirmBodySchema` in
 * `routes/requestConfirmPayment.ts` (digest bookings/M); pinned by
 * `PostRequestsConfirmPaymentBodyConformance`.
 *
 * **`pay_later` is optional-with-a-default, and this type documents the
 * SEND side**: the schema is `z.boolean().optional().default(false)`, so a
 * client may omit it and the server reads `false`. That gap between
 * `z.input` and `z.infer` is precisely why §5.1.3 pins `z.input`.
 *
 * Cross-field rules — these two live in the schema itself, as `.refine`s
 * (§4.6 renders them as prose, not as types):
 *   - `due_at` is REQUIRED when `pay_later: true`.
 *   - `pickup_at` must be strictly after `dropoff_at`.
 * Both surface as 400 `bad_request` (this route's `parseBody` uses
 * `bad_request`, unlike the `invalid_payload` used by the routes above —
 * transcribed as-is; unifying it would be a behavior change).
 *
 * Money semantics the client must not re-derive: the amount is SERVER
 * authority (`boardTrainPriceCentsForLengthWeeks(request.length_weeks)`) —
 * the body never carries a price.
 * `scheduled_at` and `dropoff_at` are the same instant for B&T (two columns
 * for the schema CHECK). Pay-now is all-or-nothing: a confirm that does not
 * reach `succeeded` cancels its PaymentIntent and throws 402 `payment_failed`
 * with a `PaymentFailedDetails` — that arm
 * has no per-endpoint alias this bump (see the §3.5 debt note in the
 * bookings patch). `Idempotency-Key` required.
 */
export interface PostRequestsConfirmPaymentRequest {
  payment_method_id: string;
  /** ISO-8601 datetime; equals `dropoff_at` for B&T. */
  scheduled_at: string;
  dropoff_at: string;
  /** ISO-8601 datetime, strictly after `dropoff_at`. */
  pickup_at: string;
  location: LocationKey;
  notes?: string;
  /** Omitted ⇒ `false` (charge now). `true` writes an open invoice instead. */
  pay_later?: boolean;
  /** REQUIRED when `pay_later: true`. */
  due_at?: string;
}

/**
 * `POST /staff/requests/:id/approve` body `[staff]`. Promoted 1.13.0 from
 * `approveBodySchema` in `routes/staffRequests.ts` (digest bookings/M);
 * pinned by `PostStaffRequestsApproveBodyConformance`.
 *
 * Flat and fully optional ON PURPOSE: which keys are required depends on the
 * LOCKED request row's category, which is not known until the row is read, so
 * a discriminated union on the body alone could not help (the comment over
 * `approveBodySchema`). The per-category requirements, enforced in
 * `validateApproveBody` as 422 `invalid_payload`:
 *   - private-lesson: `scheduled_at` AND `location` required; `pickup_at`
 *     rejected.
 *   - boarding: `scheduled_at`, `location` AND `pickup_at` required, with
 *     `pickup_at` strictly after `scheduled_at`.
 *   - board-and-train: the body is IGNORED entirely — approval parks the
 *     request at `'approved-awaiting-payment'` and creates no booking.
 * A `day-school` or `day-care` request cannot be created any more (3.0.0);
 * approving one that survives answers 409 `conflict` and books and charges
 * nothing; the row stays `submitted`, and deny still works.
 * An absent body is accepted (`request.body ?? {}`, the approve handler).
 * `Idempotency-Key` required.
 */
export interface PostStaffRequestsApproveRequest {
  /** ISO-8601 datetime with offset. Required for private-lesson + boarding. */
  scheduled_at?: string;
  /** ISO-8601 datetime with offset. Boarding ONLY, and required there. */
  pickup_at?: string;
  /** Required for private-lesson + boarding. */
  location?: LocationKey;
  notes?: string;
}

/**
 * `POST /staff/requests/:id/deny` body `[staff]`. Promoted 1.13.0 from
 * `denyBodySchema` in `routes/staffRequests.ts` (digest bookings/S); pinned
 * by `PostStaffRequestsDenyBodyConformance`.
 *
 * **`reason` is accepted and DISCARDED.** No column stores it — the schema
 * calls it "reserved for future use" and `markCancelled` never receives it
 * (the deny handler), so a denial reason typed by a staffer is lost.
 * This is documented, not fixed: persisting it needs DDL (`deny_reason` does
 * not exist on `pending_requests`) and is deferred to
 * phase 3. (An earlier draft cited "§6-batch #7" — the delivered batch's
 * item 7 contains no requests-policy discussion; corrected in the 1.13.0
 * fix round, 2.6 adversary.) Already on the ledger —
 * BUSINESS-LOGIC/DISCREPANCIES.md:671; do not re-file it as new.
 *
 * The one thing `reason` DOES affect: it rides the idempotency request hash
 * (`hashRequestBody({ id, ...body })`, the deny handler), so replaying
 * the same `Idempotency-Key` with a different reason is 422
 * `idempotency_mismatch` rather than a silent no-op.
 *
 * Denial writes `status: 'cancelled'` + `approved_by_staff_id` — the
 * `request_status` enum has no `'denied'` member. Clients
 * branch on `PendingRequestWire.approved_by_staff_id` being present to render
 * "Denied by the school" vs "You cancelled this" (DATA-CONTRACT.md:1221).
 * An absent body is accepted. `Idempotency-Key` required.
 */
export interface PostStaffRequestsDenyRequest {
  /** Accepted, length-capped at 500 — and then dropped. See above. */
  reason?: string;
}

/**
 * The board's six verbs `[staff]`, any role, at either campus (6.0.0-lg5.1,
 * BREAKING; design §1.1:1027-1041, :1079-1082, §2.3:2371-2405, :2477-2550;
 * DAY-U29, DAY-U33, DAY-U34, s09, s10). They replace `POST
 * /staff/bookings/:id/attendance` and its body `PostStaffBookingsAttendanceRequest`,
 * both removed.
 *
 *   POST /staff/bookings/:id/dogs/:dogId/check-in    no body
 *   POST /staff/bookings/:id/dogs/:dogId/check-out   PostStaffBookingsDogsCheckOutRequest
 *   POST /staff/bookings/:id/dogs/:dogId/undo        no body
 *   POST /staff/bookings/:id/dogs/:dogId/turn-away   no body
 *   POST /staff/bookings/:id/dogs/:dogId/send-home   PostStaffBookingsDogsSendHomeRequest
 *   POST /staff/bookings/:id/dogs/:dogId/no-show     no body (*Didn't come*)
 *
 * Each requires an `Idempotency-Key`, appends at most one event, and answers 200
 * `AttendanceWire`; the no-body verbs read no body. Day-school and day-care
 * sessions; the evaluation row's arms are P09's (plan `deferred_arms`).
 *
 * Each verb's date (the session's, America/Chicago) and the state it needs:
 *   - `check-in`: date today; `'expected'` at any hour, before drop-off too and
 *     with a `gate_warnings` entry on the row; or `'out'` with no settling event
 *     on the share — a dog collected for the vet and brought back (s10). That
 *     re-check-in spends nothing, unless the check-out it reopens re-issued the
 *     credit: then it takes one credit back (to the lot that return went to, else
 *     the soonest-expiring lot live today), so a day spends one credit, or none
 *     when the box was ticked at her last departure. With no live credit it is 422
 *     `insufficient_credits` with no `details` (the board sells nothing: sell a
 *     single day first). A check-in moves `DogWire.last_seen_on`.
 *   - `check-out`: date today or earlier; `'in'` or `'sent-home'`.
 *     `reissue_credit: true` needs `'in'`: a sent-home dog's credit was decided
 *     at the send-home.
 *   - `undo`: date today or earlier; removes the newest live event that is not
 *     an `undo` and not already undone. Refused when there is none, when it is a
 *     settling event, and when it moved a credit (a check-out that re-issued it,
 *     a re-check-in that took it back): that is corrected by a hand edit on
 *     the role list (CRED-U14). Check in, check out, undo, undo ends at
 *     `'expected'` with `last_seen_on` restored.
 *   - `turn-away`: date today; `'expected'`. Not a check-in: it never moves
 *     `last_seen_on`, and her seat is free for the rest of the day.
 *   - `send-home`: date today; `'in'`.
 *   - `no-show`: date today or earlier, and Chicago now at or past the campus's
 *     `day.pickup_close_time` on that date; `'expected'`.
 *
 * What comes back, always a credit and never money (the refund ruling): a
 * `turn-away`, a `no-show` and a `send-home` not marked finished return
 * `day.sent_home_before_training_return_fraction` (seeded 1) credits, a
 * `send-home` marked finished `day.sent_home_after_training_return_fraction`
 * (seeded 0), and a `check-out` with `reissue_credit: true` one. The return goes
 * to the lot the share's live debit came from, keeping that lot's expiry while it
 * can pay a later date, and otherwise lands as a fresh one-credit lot of
 * `cred.returned_credit_expiry_months` (`CreditLotDetailWire.reason`). A plain
 * check-out returns nothing. `CheckinEventWire.settlement` reports it.
 *
 * Refusals, in this order: 404 `not_found` (no live booking, or the dog was never
 * on it); 409 `session_cancelled` (the session, or this dog's share, is
 * cancelled); 409 `payment_pending` (`BookingStatus`); 409 `session_not_today`
 * (`SessionNotTodayDetails`); 409 `no_show_too_early` (`NoShowTooEarlyDetails`);
 * 409 `attendance_state_conflict` (`AttendanceStateConflictDetails`): the state
 * above is not met, a second settling event is attempted, or the undo is
 * refused; then the re-check-in's 422. No verb reads `status = 'upcoming'`. A
 * refused verb appends nothing and moves no credit.
 */

/**
 * `POST /staff/bookings/:id/dogs/:dogId/check-out` body `[staff]` (6.0.0-lg5.1;
 * design §1.1:1035-1041, §2.3:2532-2550; s09, s10, answer 12). The whole body may
 * be absent. `note` is trimmed, 1..500 characters, the rule of
 * `PostStaffBookingsCancelRequest.reason`: "went home with Shanthi" is the
 * hand-off (DAY-51). `reissue_credit` is the *Re-issue the credit* box, omitted =
 * `false`, unticked: the credit stays used. Ticked, the check-out returns it (see
 * the verbs above) and queues the owner's "was picked up early" notice. Any staff
 * role may tick it: a call at the door, not a hand credit. `Idempotency-Key`
 * required.
 */
export interface PostStaffBookingsDogsCheckOutRequest {
  note?: string;
  reissue_credit?: boolean;
}

/**
 * `POST /staff/bookings/:id/dogs/:dogId/send-home` body `[staff]` (6.0.0-lg5.1;
 * design §1.1:1036-1037, §2.3:2477-2490, :2528-2550; s09, DAY-44). The whole body
 * may be absent. `training_completed` is the *Finished training day* box, omitted
 * = `false`, unticked: the credit comes back. Ticked, it stays spent. Either way
 * she stays on site until her `check-out`. `Idempotency-Key` required.
 */
export interface PostStaffBookingsDogsSendHomeRequest {
  training_completed?: boolean;
}

/**
 * `POST /staff/bookings/:id/cancel` body `[staff]` (R5, Allison sim-QA
 * 2026-07-27). Promoted 1.13.0 from `cancelBodySchema` in
 * `routes/staffBookings.ts` (digest bookings/M); pinned by
 * `PostStaffBookingsCancelBodyConformance`.
 *
 * Unlike the deny body's `reason`, THIS one is persisted and emitted — it
 * comes back as `BookingWire.cancel_reason` under "The school cancelled this
 * on …". Trimmed, 1..500 chars; an empty string is a 422, an omitted key is
 * "cancelled without a note". The whole body may be absent
 * (`parseCancelReason`, `staffBookings.ts`). It rides the idempotency
 * request hash, so a same-key replay with a different reason is 422
 * `idempotency_mismatch`. The owner-side `POST /bookings/:id/cancel` takes NO
 * body at all — deliberately asymmetric. `Idempotency-Key` required.
 *
 * From 6.0.0-lg5.1 both whole-session cancels, the owner's and this one, refuse
 * an `'upcoming'` day-school or day-care session with 409 `session_ended`
 * (`SessionEndedDetails`) once its day has ended, then 409 `session_checked_in`
 * while any dog still on it has folded past `'expected'` (design §1.1:1064-1067,
 * §2.3:2418-2428; CXL-U09). A pending row still cancels its whole order, as
 * before. `BookingWire.can_cancel` reads the same two checks.
 *
 * From 6.0.0-lg5.2 no cancel forfeits (CXL-U04; design §1.1:1064-1067,
 * §2.7:4115-4133; s07, s17). A whole-session cancel of an `'upcoming'`
 * day-school or day-care session, the owner's or any staff role's, of any date
 * it accepts, returns one credit for each dog still on it, each to the lot her
 * debit named while that lot can pay a later date, else as a fresh lot
 * (`CreditLotDetailWire.reason`), and moves no money; `cancel_forfeited` is
 * `false`. A staff cancel's notice to the owner quotes this `reason` verbatim
 * (NOTIF-U17; design §2.9).
 */
export interface PostStaffBookingsCancelRequest {
  reason?: string;
}

/**
 * One dog of several (6.0.0-lg5.1; design §1.1:1068-1075, §2.3:2429-2447,
 * §2.10:5065-5069; CXL-U09, s11):
 *   POST /bookings/:id/dogs/:dogId/cancel          owner, no body
 *   POST /staff/bookings/:id/dogs/:dogId/cancel    staff, any role, this body
 * Each requires an `Idempotency-Key` and answers 200 `BookingWire`, the session
 * after the cancel (`dog_shares` names the dog's `cancelled_at`). That dog's share
 * leaves the session: her seat is free and one credit goes back to the owner's
 * pool (the family's, not the dog's), to the lot her debit named while it can pay
 * a later date, else as a fresh lot (`CreditLotDetailWire.reason`). Cancelling
 * the last dog still on the session cancels the session.
 *
 * Refusals, in this order: 404 `not_found` (no live booking, not hers on the owner
 * route, or the dog was never on it); 422 `invalid_payload` (not a day-school or
 * day-care session); on the owner route, 409 `per_dog_cancel_off` while
 * `cxl.per_dog_cancel_enabled` is off (seeded on; staff are unaffected); 409
 * `session_cancelled` (the session, or this dog's share, is cancelled); 409
 * `payment_pending` (cancel the whole order instead); 409 `session_ended`; 409
 * `session_checked_in` while THIS dog's folded state is not `'expected'`.
 *
 * `reason` is trimmed, 1..500 characters, and required: the board's *Cancel*
 * opens a reason sheet. It rides the idempotency hash, and from 6.0.0-lg5.2
 * the owner's notice quotes it verbatim (NOTIF-U17; design §2.9). No column
 * stores a share's reason, so `BookingWire.cancel_reason` stays the session's.
 */
export interface PostStaffBookingsDogsCancelRequest {
  reason: string;
}

/**
 * `GET /staff/bookings` query `[staff]` — the server-side filters for the
 * cross-owner triage queue (digest bookings/S). Contract-first at 1.13.0 and
 * BUILT in 2.3b: the handler parses this query, filters on the four keys,
 * and a malformed value on any of them is a 400 `bad_request`
 * (`routes/staffBookings.ts` + `staff-bookings.test.ts`). Keys OUTSIDE this
 * contract remain inert (the schema is deliberately non-strict, §14.1).
 * `from > to` is legal and returns `[]` — an empty range is empty, not an
 * error; a staffer seeing an unexpectedly empty queue should check the pair.
 *
 * Every key is OPTIONAL and all-omitted must reproduce today's response
 * exactly: every live, non-cancelled booking across all owners, soonest
 * scheduled first (`bookingsRepository.findLiveActive`). That is the additive
 * floor 2.3b builds against — filters narrow, they never widen. In
 * particular the queue still EXCLUDES cancelled and soft-expired rows; adding
 * a `status` filter would be a widening, and is deliberately not here
 * (PORTAL-ENDPOINT-MAP.md:458 open question).
 *
 * `from` / `to` are the pair the route's own Day-20 hardening note flagged
 * (over `GET /staff/bookings`); `category` + `location` come from the portal
 * demand line (PORTAL-ENDPOINT-MAP.md:453). Semantics for 2.3b, fixed here so
 * the build has no room to guess:
 *   - `from`/`to` are `YYYY-MM-DD` **America/Chicago calendar days**,
 *     INCLUSIVE on both ends, compared against the same day label
 *     `BookingWire.date` carries. Either may be sent alone (open-ended).
 *   - `category` and `location` are exact-match single values.
 *   - a malformed value is 400 `bad_request` — the query-parse convention
 *     already used by `parseView` (`routes/bookings.ts`) and each
 *     `parseStatusQuery` (`requests.ts`, `staffRequests.ts`) (a route body's
 *     cross-field rules use `invalid_payload`; queries use `bad_request`).
 * The proposed `search=<str>` free-text filter (PORTAL-ENDPOINT-MAP.md:453)
 * is NOT here — see the bookings patch's STOP item.
 */
export interface GetStaffBookingsQuery {
  /** `YYYY-MM-DD`, Chicago, inclusive lower bound. */
  from?: string;
  /** `YYYY-MM-DD`, Chicago, inclusive upper bound. */
  to?: string;
  category?: ServiceCategory;
  location?: LocationKey;
}

/**
 * `GET /staff/checkin-board` query `[staff]`, any role, either campus
 * (6.0.0-lg5.1; design §1.1:1044, §2.3:2417; DAY-U29). Both keys are required.
 * `date` is a Chicago calendar day, today or any earlier day, so a day nobody
 * recorded is fixed on its own board; a later date, a malformed value or a
 * missing key is 400 `bad_request`, the query convention. An owner principal is
 * 403 `forbidden`. Response `GetStaffCheckinBoardResponse`.
 */
export interface GetStaffCheckinBoardQuery {
  location: LocationKey;
  /** `YYYY-MM-DD`, Chicago, today or earlier. */
  date: string;
}

/**
 * `GET /staff/owners/:ownerId/bookings?from=<date>` query `[staff]`, any role,
 * either campus (6.0.0-lg5.2; design §1.1:1076-1078, §2.3:2448-2455,
 * §2.10:5069-5072; CXL-U04, s17): the family's day sessions for the profile's
 * *Bookings*, from which a staff cancel reaches any future date, not only the
 * board's today. `from` is required, a Chicago calendar day; a missing or
 * malformed value is 400 `bad_request`, the query convention. An `:ownerId`
 * that names no owner is 404 `not_found`; an owner principal is 403 `forbidden`.
 *
 * Response `GetStaffOwnersBookingsResponse`: every live day-school and day-care
 * session of that owner dated `from` or later that is not cancelled, soonest
 * first, each a staff read of `BookingWire`. So `can_cancel` and
 * `dog_shares[].can_cancel` are the staff cancels' own (the
 * `cxl.per_dog_cancel_enabled` switch ignored), on the same fold and clock as
 * their 409s: a dog whose state is not `'expected'` reads `false`, and so does
 * every dog of a day that has ended. A share cancelled alone stays in
 * `dog_shares` with its `cancelled_at`. *Cancel* is `POST
 * /staff/bookings/:id/cancel` (the whole session) or `POST
 * /staff/bookings/:id/dogs/:dogId/cancel` (one dog), any role, credits only.
 */
export interface GetStaffOwnersBookingsQuery {
  /** `YYYY-MM-DD`, Chicago, inclusive lower bound. */
  from: string;
}

/** `GET /staff/owners/:ownerId/bookings` response: `[]` when she has none. */
export type GetStaffOwnersBookingsResponse = BookingWire[];

// ---- (d) per-endpoint 422 detail unions (§3.5) -----------------------------

/**
 * Every `details` arm `POST /bookings` can refuse with, so a client can narrow
 * `ApiErrorEnvelope['error']['details']` once for this endpoint instead of
 * switching over every arm (digest bookings/L). Emit sites, in the order
 * the request hits them:
 *   1. `payment_required`      — `checkBookingGates` (`lib/bookingGatePreCheck.ts`)
 *   2. `evaluation_required`   — `checkBookingGates`
 *   3. `vaccine_missing`       — `checkBookingGates`
 *   4. `agreement_unsigned`    — `checkBookingGates`
 *   5. `credit_expired_before_date` — `createDayProgramBookings`
 *      (`lib/createDayProgramBookings.ts`). Before arm 6, because the credit
 *      check's first pass finds it and its second counts the shortfall
 *      (design §2.3:2634-2639): a top-up cannot complete a booking with such a
 *      date in it, so she is not offered one.
 *   6. `insufficient_credits`  — `createDayProgramBookings`
 *   7. `already_booked`        — `createDayProgramBookings`
 *   8. `insufficient_capacity` — `dayCapacityRepository.assertCapacityWithinLock`
 *   9. `after_school_full`     — the date's after-school count, under the same
 *      lock right after that date's seats (6.0.0-lg5.2; `PostBookingsRequest`).
 *  10. `payment_failed`        — 402, not 422: the top-up's charge did not
 *      complete (`PaymentFailedDetails`). Every row is cancelled, every debit
 *      returned, nothing granted, and the 402 is stored.
 * Arms 1-4 can also arrive from the DB trigger floor with EMPTY arrays
 * (`gateTriggerErrorToApiError`, `lib/bookingErrors.ts`) in the race
 * window — `missing: []` is a legal emission, see §1.
 *
 * The route's other 422s carry no `details`, so they are not arms here:
 * `invalid_payload`, 4.0.0-lg3.1's `program_not_offered`,
 * `beyond_booking_horizon` and `same_day_cutoff_passed`, and 5.0.0-lg4.2's
 * `alumni_tier_requires_alumni_dog` (`PostBookingsRequest`), which runs after the
 * gates and before arm 5.
 *
 * Arm 6 runs before arm 7, so a date she already holds is met only once the
 * credits fit. Arms 1 to 9 all answer inside tx1, before any Stripe call, so a
 * `top_up` refused by one of them charges nothing.
 */
export type PostBookingsErrorDetails =
  | PaymentRequiredDetails
  | EvaluationRequiredDetails
  | VaccineMissingDetails
  | AgreementUnsignedDetails
  | CreditExpiredBeforeDateDetails
  | InsufficientCreditsDetails
  | AlreadyBookedDetails
  | InsufficientCapacityDetails
  | AfterSchoolFullDetails
  | PaymentFailedDetails;

/**
 * Every `details` arm `POST /requests` can 422 with (digest bookings/L).
 * Much smaller than the booking set by design: submission runs no payment,
 * vaccine, agreement, credit or capacity gate — those fire later, at the
 * staff approve verb's booking INSERT (the comment over the `POST /requests`
 * handler). Two arms only:
 *   1. `evaluation_required` — `evaluationRequiredError` in the handler, the
 *      LEAD dog only, and only for board-and-train + boarding. Private-lesson
 *      is staff-curated and does not gate here.
 *   2. `already_requested`   — `alreadyRequestedError` in the handler, the
 *      residential duplicate guard (board-and-train + boarding,
 *      roster-matched). Private-lesson is EXEMPT: an owner may keep several
 *      pending at once.
 * The endpoint's other 422s carry NO `details`: `invalid_payload`, because
 * every cross-field rule in `validatePostRequestBody` throws message-only, and
 * 4.0.0-lg3.1's `service_not_offered` and `beyond_booking_horizon`
 * (`PostRequestsRequest`).
 */
export type PostRequestsErrorDetails = EvaluationRequiredDetails | AlreadyRequestedDetails;

// <<< domain:bookings =========================================================

// >>> domain:credits ==========================================================

// (a) domain-local enums + tuples — NONE. Credits reference only §2 shared
//     unions: `BookingMode` (the credit axis: one credit = one booked day of
//     that mode), `LocationKey` (balances are per-school since Δ 2026-06-04) and
//     `CreditTier` (5.0.0-lg4.2). The first two are already conformance-pinned
//     to their canonical sources (`contracts/conformance.ts`
//     `ContractEnumConformance`: `BookingMode` ↔ the `booking_mode` pgEnum;
//     `LocationKey` ↔ `LOCATION_SLUGS`), so a promoted field typed
//     `BookingMode`/`LocationKey` here is a type IDENTITY with the route's local
//     alias, NOT a §14.2 narrowing. No credits union is minted.
//
// The routes (5.0.0-lg4.2; design §1.1:953-1011, §2.4:2856-3111). An owner
// (family) principal on a `/staff/…` route is 403 `forbidden`, and a staff
// principal on `GET /credits` or the purchase is the same.
//   GET   /credits?location=                       → OwnerCreditsWire        owner
//   GET   /credit-packages?location=               → CreditPackageWire[]     any
//   POST  /credit-packages/:key/purchase           → CreditPurchaseWire      owner
//   GET   /staff/owners/:ownerId/credits           → StaffOwnerCreditsWire   any role
//   POST  /staff/owners/:ownerId/credit-adjustments → StaffCreditPoolWire    role list
//   PATCH /staff/credit-lots/:id                   → CreditLotDetailWire     role list
//   PATCH /staff/credit-packages/:key              → CreditPackageWire       role list

// (b) response wires ----------------------------------------------------------

/**
 * A live expiring lot's remaining credits + lapse date (soonest-first list):
 * `OwnerCreditPoolWire.expiring_lots`.
 *
 * Promoted 1.13.0 from `routes/credits.ts:32-37` (digest credits/M — "Promote
 * the credits READ surface"). Grandfathered name, kept verbatim (§4.4).
 *
 * ⚠️ This is the expiring-lot MINI-row, not the staff full-lot shape, which is
 * `CreditLotDetailWire`. The name does not move, because renaming a shipped
 * export is a major bump (§4.4).
 *
 * `remaining` = the lot's grant plus every allocation (debit −/refund +) tagged
 * to it. Exhausted and expired lots are never listed.
 *
 * `expires_at` is always set and live from 5.0.0-lg4.2 (CRED-U05, CRED-U17): the
 * never-expiring class is retired, so every lot, a 1-credit pack and an import
 * included, stops paying at its date. It is stamped once, at grant.
 *
 * `expires_at` is wire ISO-8601 (`…THH:MM:SS[.mmm]Z`), converted at the
 * raw-SQL boundary by `pgTimestampToIso` — NOT Postgres's space-separated `+00`
 * form, which Hermes (RN) refuses to parse.
 */
export interface CreditLotWire {
  mode: BookingMode;
  remaining: number;
  expires_at: string;
}

/**
 * One pool of `OwnerCreditsWire`: the caller's credits for one program and tier
 * at the campus asked about.
 */
export interface OwnerCreditPoolWire {
  mode: BookingMode;
  tier: CreditTier;
  /** The pool's live credits, the sum of `lots[].remaining`. */
  balance: number;
  /** Every live lot with credits left, soonest-expiring first, so the app can
   *  word "1 expires Mon 19 Oct, 8 expire Tue 10 Nov". */
  lots: { remaining: number; expires_at: string }[];
  /**
   * The lots within `cred.expiry_warning_lead_days`, its longest lead, soonest
   * first. Never `[]` by a switch: it reads the lots' dates, with
   * `cred.expiry_enforced_enabled` either way, and a lot past its date is never
   * in it.
   */
  expiring_lots: CreditLotWire[];
}

/**
 * `GET /credits?location=<key>` response `[auth, owner]` — the caller's credit
 * pools at one campus (5.0.0-lg4.2; design §1.1:957-961; CRED-U10, CRED-U33). It
 * replaces `CreditsWire` and `GET /dogs/:id/credits`: credits are the owner's,
 * one pool per campus, program and tier, and no balance is a dog's.
 *
 * Query shape: `GetCreditsQuery` below — `location` is REQUIRED (400
 * `bad_request` without it), so a family that uses both campuses reads twice.
 *
 * Balances are DERIVED, never stored counters: `SUM(delta)` over the
 * append-only `credit_ledger`, counting only rows attached to live lots
 * (`lot_is_live`, M4.08). Expiry is passive — no sweep writes an "expired" row;
 * the view simply stops counting.
 *
 * ZERO SENTINEL: a pool is listed only while it holds a live credit, so an owner
 * with none at this campus reads `{ location, pools: [] }`, never a 404. `pools`
 * is ordered by `mode` (`booking_mode` enum order), then regular before alumni.
 *
 * No warning lead here: the app reads `cred.expiry_warning_lead_days` from
 * `GET /settings` (`OwnerCreditSettingsWire`).
 */
export interface OwnerCreditsWire {
  location: LocationKey;
  pools: OwnerCreditPoolWire[];
}

/**
 * One row of `GET /credit-packages?location=<key>` `[auth]` — the catalog of
 * purchasable credit packs currently effective at a location (DATA-CONTRACT §B
 * CreditPackage Δ 2026-05-20; effective-dated since Δ 2026-06-08). Ten rows are
 * seeded, every one buyable, each with its one campus, program and tier (design
 * §2.4:2865-2874; CRED-U04, CRED-U07), so `location` and `mode` are never null.
 *
 * Promoted 1.13.0 from `routes/creditPackages.ts:56-64` (digest credits/M).
 * Query shape: `GetCreditPackagesQuery` below (`location` REQUIRED).
 *
 * Reference data, not user data: the rows come from one shared per-(campus,
 * Chicago day) cache (`creditPackages.ts:134`), and owner and staff principals
 * read the same rows. Since 5.0.0 an owner's read adds `withheld_reason` per
 * owner, computed after the cache read and never inside it (design
 * §2.4:2875-2877); a staff read never carries it. Ordering is `mode ASC, credits ASC` with
 * Postgres enum sort order (`booking_mode` is declared `('school','daycare')`),
 * so school packs precede daycare packs — pinned by
 * `test/contracts/snapshots/credit-packages.json`.
 *
 * `key` is the catalog's natural key and stays `string` deliberately: rows are
 * seed data plus `PATCH /staff/credit-packages/:key` (`credit_packages.key`,
 * `[a-z0-9-]{1,64}` at the path param), not a closed enum — typing it as a union
 * would be a promotion-time tightening of open data (§14.1). A key names one
 * row's campus (M4.05): the two campuses' rows have different keys.
 *
 * `price_cents` is integer cents; a purchase charges `price_cents × count` and
 * grants `credits × count` with no server-side rounding, ever, `count` being 1
 * on every row that is not `single_day` (`PostCreditPackagesPurchaseRequest`).
 *
 * RETIREMENT is the closed `[effective_from, effective_to)` window, NOT an
 * `active` flag — the route's own header comment says otherwise and is stale
 * (already on the ledger as DRIFT-11, BUSINESS-LOGIC/DISCREPANCIES.md:309-313).
 * Neither `effective_from`/`effective_to` nor the surrogate `id` is on the
 * wire: the filter is server-side, so a retired pack never surfaces.
 */
export interface CreditPackageWire {
  key: string;
  location: LocationKey;
  mode: BookingMode;
  /** The pool a purchase lands in; an `'alumni'` row is the Alumni 10 Visits
   *  pack. */
  tier: CreditTier;
  credits: number;
  price_cents: number;
  label: string;
  is_popular: boolean;
  /** One credit, sold by `count` (`PostCreditPackagesPurchaseRequest`). The row a
   *  booking's `top_up_offer` names. */
  single_day: boolean;
  /** Whole America/Chicago months a lot of this row lasts, stamped once at grant
   *  (`cred.package_expiry_months`; seed 1). Lots already sold keep their date. */
  expiry_months: number;
  /**
   * Why THIS owner cannot buy the row (5.0.0; design §1.1:980-983,
   * §2.4:3060-3069; ALUM-U11, EVAL-U20). OMITTED when she can, and on every
   * staff read. The row is still listed: the app greys it with the reason's
   * copy ("For alumni dogs", "Pass an evaluation first"; ALUM-U13, EVAL-U21)
   * and never offers its purchase. The purchase route refuses the same row
   * with the matching 422, so the field is advice and the route is the rule:
   *   - `'alumni-only'`: a `tier: 'alumni'` row, and no live dog on the account
   *     is `is_alumni` → `alumni_package_ineligible`.
   *   - `'no-evaluated-dog'`: no dog on the account holds `passed` →
   *     `pack_requires_evaluated_dog`. Typed here; sent by no route until
   *     EVAL-U20 lands (plan unit P11).
   * When both hold, `'no-evaluated-dog'` is sent (the household's first gate).
   */
  withheld_reason?: CreditPackageWithheldReason;
}

/** `CreditPackageWire.withheld_reason` (5.0.0). Computed per owner at read,
 *  never stored. */
export type CreditPackageWithheldReason = 'no-evaluated-dog' | 'alumni-only';

/**
 * One lot as staff read it: an element of `StaffCreditPoolWire.lots`, and the
 * response of `PATCH /staff/credit-lots/:id` (5.0.0-lg4.2; design §1.1:990-994,
 * §2.4:3092-3098; CRED-U14, CRED-U15, CRED-U38). `id` is the grant row's
 * `credit_ledger.id`.
 *
 * `reason` is the grant row's ledger label: `'purchase'`, `'adjustment'` (a hand
 * add), or `'settlement-return'`, a returned credit whose own lot could pay no
 * later date, written as a fresh one-credit lot of
 * `cred.returned_credit_expiry_months` (§2.4:2957-2973). 6.0.0-lg5.1 (M5.03,
 * BREAKING) makes `'settlement-return'` the one label of every return — a cancel
 * of the session or of one dog, a turn-away, *Didn't come*, an unmarked
 * send-home, a check-out that re-issued the credit — and `'cancel-refund'` leaves
 * this union: no writer writes it, and a lot written under it before reads
 * `'settlement-return'`. `'gingr-import'` joins at the import (M10.06).
 *
 * `granted` is the grant's credits and `granted_at` its row's time. `remaining`
 * is the grant plus every allocation tagged to it, read whether or not the lot
 * is live. `expires_at` is always set. `live` is `lot_is_live` (M4.08), computed
 * at read: a lot past its date is live again the moment its date is moved later
 * (CRED-62). All instants are wire ISO-8601.
 *
 * `package_id` and `charge_id` are omitted on a lot no purchase made, and `note`
 * and `created_by_staff_id` on a lot no staffer wrote, or whose staffer's row is
 * gone (`ON DELETE SET NULL`).
 *
 * NON-OMIT: `last_expiry_edit` is `null` while the date has never been moved,
 * and otherwise the newest `credit_lot_expiry_edits` row. `staff_id` in it is
 * `null` once the staffer's row is deleted.
 *
 * `booked_ahead` is the lot's debits on upcoming days, so a screen can name them
 * ("3 days are booked on this pack"): `dates` has one `YYYY-MM-DD` entry per
 * live debit (one whose credit has not come back: no `settlement-return` names
 * it; 6.0.0-lg5.2), ascending, so its length is `count`, and it is
 * `{ count: 0, dates: [] }` when there are none. A dog cancelled alone, turned
 * away, sent home or marked *Didn't come* on a day still upcoming no longer
 * counts.
 */
export interface CreditLotDetailWire {
  id: string;
  reason: 'purchase' | 'adjustment' | 'settlement-return';
  granted: number;
  remaining: number;
  granted_at: string;
  expires_at: string;
  live: boolean;
  package_id?: string;
  charge_id?: string;
  note?: string;
  created_by_staff_id?: string;
  last_expiry_edit: {
    from: string;
    to: string;
    staff_id: string | null;
    note: string;
    at: string;
  } | null;
  booked_ahead: { count: number; dates: string[] };
}

/** One pool of `StaffOwnerCreditsWire`, and the response of `POST
 *  /staff/owners/:ownerId/credit-adjustments`: the changed pool. `balance` is the
 *  live balance, as the owner reads it. `lots` is every lot of the pool, spent
 *  and expired included, newest first. */
export interface StaffCreditPoolWire {
  location: LocationKey;
  mode: BookingMode;
  tier: CreditTier;
  balance: number;
  lots: CreditLotDetailWire[];
}

/**
 * `GET /staff/owners/:ownerId/credits` response — every pool of one owner, at
 * both campuses (5.0.0-lg4.2; design §1.1:988-994; CRED-U14, CRED-U38, DAY-U15).
 * Any staff role reads it; the three hand edits are what the role list gates. An
 * unknown owner is 404 `not_found`.
 *
 * `expiry_enforced` is the live `cred.expiry_enforced_enabled`. No screen reads
 * it: §2.10:5001 shows the expiry date on every lot, flag on or off (DECISIONS
 * 177(e); 5.0.0-lg4.2). A pool is listed once it has a lot, whatever is left
 * in it, ordered by `location`, `mode`, then regular before alumni. `pools` is
 * `[]` for an owner with none.
 */
export interface StaffOwnerCreditsWire {
  owner_id: string;
  expiry_enforced: boolean;
  pools: StaffCreditPoolWire[];
}

// (c) request bodies + query shapes -------------------------------------------

/**
 * `POST /credit-packages/:key/purchase` body `[auth, owner, $]`. Since
 * 5.0.0-lg4.2 it is `{payment_method_id, count?}` (design §1.1:953-956,
 * §2.4:2879-2882; CRED-U30, CRED-U10, CRED-U04): the row carries its campus, the
 * credits land in the owner's pool for its campus, program and tier, and no dog
 * is named.
 *
 * Promoted 1.13.0 from `routes/creditPackages.ts:98-108` `purchaseBodySchema`
 * (digest credits/S — "Contract the credits request bodies"). Pinned to that
 * schema in the route file by `PostCreditPackagesPurchaseBodyConformance`
 * (§5.1.3, `z.input` — what a client may SEND, pre-default).
 *
 * `.strict()`: an unknown key is a 400 `bad_request`, not a silent drop, so a
 * client still sending `dog_id`, `location` or `quantity` is refused.
 * `Idempotency-Key` is REQUIRED. Reusing a key with a different body is
 * `idempotency_mismatch` (422, no `details`). Its length bound lives in the §0
 * conventions block.
 *
 * The route rides the order engine since 5.0.0-lg4.2 (design §2.4:2978-3022,
 * §2.7; CRED-U10), one order and one charge under the `cancel-order` failure
 * policy. Nothing is granted before the money:
 *   - 201 `CreditPurchaseWire` with `charge_status: 'succeeded'`: one charge of
 *     `price_cents × count`, one lot of `credits × count`, one paid invoice. A
 *     route that loses the race to the webhook answers the same 201 with the
 *     webhook's lot.
 *   - 201 with `charge_status: 'requires_payment'`, `credits_granted: 0` and
 *     `charge_blocker: 'processing'`: Stripe has not answered, so do not retry.
 *     The credits are added when it clears.
 *   - 402 `payment_failed` (`PaymentFailedDetails`): the order ended unpaid and
 *     nothing is granted; a decline was a 201 until now. A replay returns the
 *     same 402, so the next try takes a fresh key, with this card or another.
 *   - 409 `idempotency_inflight`: no answer exists yet. Re-send under the same
 *     key; the final answer replays once the order has settled. Nothing more is
 *     charged.
 *
 * 404 collapses for unknown key / retired package / unknown or soft-expired
 * payment method — id enumeration is the security concern, so all three answer
 * identically. 422 `count_not_allowed`: see `count`.
 *
 * Since 5.0.0 the household's gates run before any order commits, so a refusal
 * charges nothing and writes nothing (design §2.4:3060-3069):
 *   - 422 `alumni_package_ineligible` (`AlumniPackageIneligibleDetails`): an
 *     alumni-tier row, and no live dog on the account is `is_alumni` (ALUM-U11).
 *   - 422 `pack_requires_evaluated_dog`: no dog on the account holds `passed`
 *     (EVAL-U20). Typed at 5.0.0; thrown by no route until plan unit P11.
 * The row's `withheld_reason` names the same refusal ahead of time.
 *
 * No total rides the body, unlike a booking's `top_up.expected_total_cents`:
 * no v1 route writes `price_cents` or `credits` (`PatchStaffCreditPackagesRequest`
 * writes `expiry_months` only), so the price on the row she read is the price
 * charged (build DECISIONS 216).
 */
export interface PostCreditPackagesPurchaseRequest {
  /** UUID of one of the caller's stored payment methods (`payment_methods.id`,
   *  NOT a Stripe id). */
  payment_method_id: string;
  /**
   * Single days bought in ONE charge and ONE lot: a positive integer, OMITTED =
   * 1. Accepted only on a row with `single_day: true`, up to
   * `cred.single_day_purchase_max_count` (seed 30), read at runtime. On any other
   * row, or above that limit, 422 `count_not_allowed`: a pack is bought one at a
   * time, and `count: 1` on a pack is refused like any other.
   */
  count?: number;
}

/**
 * `POST /staff/owners/:ownerId/credit-adjustments` body: a hand edit of one pool
 * (5.0.0-lg4.2; design §1.1:994-1001, §2.4:3084-3091; CRED-U14). `.strict()`;
 * `Idempotency-Key` REQUIRED. Response 201 `StaffCreditPoolWire`, the changed
 * pool. No count cap: the role list is the limit.
 *
 * 403 `credit_edit_role_required` for a role off
 * `staff.credit_hand_edit_role_list` (`StaffSettingsWire.credit_hand_edit_roles`;
 * the owner role always passes). Unknown owner: 404 `not_found`.
 *
 * `credits` is a positive integer. `note` is required, 1..500 characters: every
 * hand edit is explained (M4.12).
 *
 * `'add'` writes a grant lot in the pool. `expires_at` is ISO-8601, omitted for
 * `cred.manual_grant_expiry_months` from now, and any instant later than now
 * otherwise (422 `expiry_not_in_future`). 422 `pool_not_bookable` for a pool no
 * v1 booking can draw from: a campus and program with no seeded package row, or
 * the alumni tier on an account with no alumni dog.
 *
 * `'remove'` debits one lot, the pool and owner read from the lot, whether or not
 * it is live. 422 `lot_insufficient` above the lot's unspent; a lot that is not
 * this owner's grant row is the generic 404.
 */
export type PostStaffOwnersCreditAdjustmentsRequest =
  | {
      kind: 'add';
      location: LocationKey;
      mode: BookingMode;
      tier: CreditTier;
      credits: number;
      expires_at?: string;
      note: string;
    }
  | { kind: 'remove'; lot_id: string; credits: number; note: string };

/**
 * `PATCH /staff/credit-lots/:id` body: move a lot's expiry (5.0.0-lg4.2; design
 * §1.1:997-998, §2.4:3092-3098; CRED-U15, Shanthi's condition, 12- #6.11).
 * `.strict()`; `Idempotency-Key` REQUIRED. Response 200 `CreditLotDetailWire`.
 *
 * `expires_at` is ISO-8601 and must be later than now, else 422
 * `expiry_not_in_future`: taking credits away is the removal's job and leaves a
 * row. `note` is required, 1..500 characters. Each edit writes one
 * `credit_lot_expiry_edits` row. 403 `credit_edit_role_required` as above; an id
 * that is no grant row is the generic 404.
 */
export interface PatchStaffCreditLotsRequest {
  expires_at: string;
  note: string;
}

/**
 * `PATCH /staff/credit-packages/:key` body: one row's expiry window (5.0.0-lg4.2;
 * design §1.1:1002-1004, §2.4:3099-3106; CRED-U08 narrowed to this one field).
 * `.strict()`; `Idempotency-Key` REQUIRED. Response 200 `CreditPackageWire`.
 *
 * `expiry_months` is an integer, 1..120. It opens a new effective-dated row from
 * today in America/Chicago, or corrects today's row in place, so a second edit
 * the same day answers 200. The next purchase stamps the new months; lots already
 * sold keep their date. Price and credit count are reference data: no route edits
 * them. 403 `credit_edit_role_required` as above; a key with no live row is 404
 * `not_found`.
 */
export interface PatchStaffCreditPackagesRequest {
  expiry_months: number;
}

/**
 * `GET /credits` query string. Promoted 1.13.0 from `routes/credits.ts:30`
 * `creditsQuerySchema` (digest credits/S, §7 Fills) as `GET /dogs/:id/credits`'s;
 * the route moved at 5.0.0-lg4.2 and kept it.
 * `location` is REQUIRED — omitting it is 400 `bad_request`, not a default —
 * because balances are per-school since Δ 2026-06-04. Pinned in the route file
 * by `GetCreditsQueryConformance`.
 */
export interface GetCreditsQuery {
  location: LocationKey;
}

/**
 * `GET /credit-packages` query string. Promoted 1.13.0 from
 * `routes/creditPackages.ts:92` `packagesQuerySchema` (digest credits/S, §7
 * Fills). `location` REQUIRED (400 without it) — catalog and price are
 * per-location since Δ 2026-06-04. Pinned by
 * `GetCreditPackagesQueryConformance`.
 */
export interface GetCreditPackagesQuery {
  location: LocationKey;
}

// (d) per-endpoint 422 detail unions — NONE on this surface, deliberately.
//     No 422 a credits route can raise carries a `details` payload, so there is
//     no arm to alias (§3.5). The one `details`-carrying money arm is the
//     purchase's 402 `payment_failed` / `PaymentFailedDetails`, which is not a
//     422. `CreditGap` and `InsufficientCreditsDetails` (wire.ts §1, skeleton)
//     belong to the BOOKING/ENROLLMENT surfaces that spend credits; their
//     per-endpoint alias is `PostBookingsErrorDetails`, owned by the bookings
//     lane.

// (e) domain-owned pure helpers — NONE. Credits emit no derived/display value
//     the clients must recompute identically; balances are server-derived.

// <<< domain:credits ==========================================================

// >>> domain:dogs-profile =====================================================

// ---- (a) domain-local enums ------------------------------------------------

/**
 * The five day-school curriculum programs — the "5 courses" whose completion
 * makes a dog ALUMNI (BUSINESS-LOGIC/dogs-evaluations.md R20 @ :75; the flag is
 * stored from 5.0.0-lg4.2, `DogWire.is_alumni`). Written as an `Extract` of
 * `ReportProgram` (§2) so a typo cannot mint a non-program, and so the
 * relationship to the report vocabulary is visible: this set is exactly
 * `ReportProgram` minus `SESSION_PROGRAMS` (§2). Promoted 1.13.0 from
 * `lib/alumni.ts:17-23` (`CURRICULUM_PROGRAMS`), whose DB floor is the
 * `dog_completed_programs.program` CHECK (`schema.sql:475-476`) — a
 * `report_program` column further constrained to these five. Digest
 * dogs-profile/S ("type its program field"). `routes/staffAlumni.ts` carries
 * the compile-time pin that this union equals `CURRICULUM_PROGRAMS`.
 */
export type CurriculumProgram = Extract<
  ReportProgram,
  'foundation' | 'advanced' | 'loose-leash' | 'house-manners' | 'cgc'
>;

// ---- (b) response wires ----------------------------------------------------

/**
 * A veterinary practice. Emitted standalone by `GET /vets?q=` (typeahead) and
 * `GET /vets/:id`, by the `POST /vets` / `PATCH /vets/:id` mutation responses,
 * and nested as `DogWire.vet`. Optional keys follow the omit-on-null rule —
 * `phone`/`email`/`address`/`notes` are absent, never `null`, when unset
 * (`lib/vetWire.ts:22-28`). Promoted 1.13.0 from `lib/vetWire.ts:13` (digest
 * dogs-profile/L, the dog wire family). Table `vets` (`schema.sql:376`); the
 * `source`/`external_ref` columns are server-internal and are NOT on the wire.
 */
export interface VetWire {
  id: string;
  name: string;
  phone?: string;
  email?: string;
  address?: string;
  notes?: string;
}

/**
 * One vaccination record on a dog. Emitted inside `DogWire.vaccines` and as the
 * `POST /dogs/:id/vaccines` (201) / `PATCH /dogs/:id/vaccines/:vid` (200)
 * response body. `expires_at` is a `YYYY-MM-DD` calendar date (Postgres `date`,
 * not a timestamp — BUSINESS-LOGIC/dogs-evaluations.md :135). Promoted 1.13.0
 * from `lib/dogWire.ts:30` (digest dogs-profile/L).
 */
export interface VaccineWire {
  id: string;
  name: string;
  expires_at: string;
  /** Omit-on-null: the `dog_vaccines.requirement_key` FK to
   *  `required_vaccines.key` (Day-9d amendment 2026-05-22). A row WITHOUT it is
   *  a display-only record that never gates a booking (`schema.sql:422-423`);
   *  display-only on the client too — the booking gate reads the DB column
   *  directly (BUSINESS-LOGIC/dogs-evaluations.md R11-R13 @ :60-62). */
  requirement_key?: string;
}

/**
 * One medication on a dog. Emitted inside `DogWire.medications` and as the
 * `POST /dogs/:id/medications` (201) / `PATCH /dogs/:id/medications/:mid` (200)
 * response body. All four keys always emit (all NOT NULL, `schema.sql:431`).
 * Promoted 1.13.0 from `lib/dogWire.ts:40` (digest dogs-profile/L).
 */
export interface MedicationWire {
  id: string;
  name: string;
  dose: string;
  frequency: string;
}

/**
 * A dog's feeding plan (1:1 with the dog, `schema.sql:441`). Emitted inside
 * `DogWire.feeding` and as the `PUT /dogs/:id/feeding` (200) response body.
 *
 * **Explicit non-omit exception to the file-wide omit-on-null rule:** `notes`
 * is `string | null` and ALWAYS present — the client reads `feeding.notes`
 * unconditionally, so a missing key would break it (`lib/dogWire.ts:18-19`, restated on the interface).
 * A dog with no `dog_feeding` row still emits this object, with `''` for the
 * three text fields and `null` for `notes` (`lib/dogWire.ts:158`) — absence of
 * a feeding plan is NOT signalled by absence of the key.
 * Promoted 1.13.0 from `lib/dogWire.ts:47` (digest dogs-profile/L).
 */
export interface FeedingWire {
  brand: string;
  amount: string;
  frequency: string;
  notes: string | null;
}

/**
 * THE dog shape — `GET /dogs` (owner's live dogs; staff get `[]`),
 * `GET /dogs/:id`, and the `POST /dogs` (201) / `PATCH /dogs/:id` (200)
 * response bodies. Promoted 1.13.0 from `lib/dogWire.ts:54` (digest
 * dogs-profile/L); `toDogWire` stays the server-side mapper and the lib
 * re-exports this type.
 *
 * Emission notes, transcribed rather than tidied (§14.1):
 *   - `profile_image_path` is REQUIRED and never null — a null column emits
 *     `''` (`lib/dogWire.ts:96`) — and is resolved at READ time to a signed
 *     URL when it holds a `media_assets` UUID; bundled asset paths pass
 *     through unchanged (`lib/profileImageUrls.ts`, `routes/dogs.ts:252-264`).
 *   - `age_months` is DERIVED per request from `birthdate` or
 *     `age_months_override` (`lib/ageMonths.ts`); neither raw column is on the
 *     wire.
 *   - `is_alumni` is STORED from 5.0.0-lg4.2 (`dogs.is_alumni`, M4.11; ALUM-U02):
 *     set when the fifth live `dog_completed_programs` row is recorded, and never
 *     cleared by un-recording a level.
 *   - `evaluation_status` is the hard booking gate for the four in-school
 *     categories (R8 @ :54). It is TODAY owner-writable through `POST`/`PATCH
 *     /dogs` — the trust inversion recorded as DISCREPANCIES BUG-11 /
 *     dogs-evaluations.md D2 @ :204. This contract documents that; the fix is
 *     phase 3 (Adjudication 5), not this bump.
 *   - There is NO `field_overrides` key: DATA-CONTRACT §B promises one and
 *     mobile reads one, but no server code has ever emitted it (DRIFT-27).
 *     Deciding it is a named out-of-scope design item (§17).
 *   - Date conventions: `spay_neuter_planned_on` and `last_seen_on` are
 *     `YYYY-MM-DD`; `evaluation_date` is ISO timestamptz
 *     (dogs-evaluations.md :135).
 */
export interface DogWire {
  id: string;
  name: string;
  breed: string;
  age_months: number;
  profile_image_path: string;
  vaccines: VaccineWire[];
  medications: MedicationWire[];
  feeding: FeedingWire;
  special_notes: string;
  evaluation_status: EvaluationStatus;
  boarding_enabled: boolean;
  /** Stored — the dog reached all 5 day-school curriculum completions. */
  is_alumni: boolean;
  evaluation_date?: string;
  /** Omit-on-EMPTY (not just null): an empty completion list omits the key
   *  entirely (`lib/dogWire.ts:114`). */
  completed_class_keys?: GroupClassKey[];
  vet?: VetWire;
  /** Shanthi 2026-07-14 (omit-on-null = unanswered): a PROFILE question. The
   *  owner's answer is stored, and no booking path reads it until the
   *  spay/neuter refusal lands in a later group (S11, LG2b). */
  spayed_neutered?: boolean;
  /** `YYYY-MM-DD` (omit-on-null): the owner's stated spay/neuter date — a
   *  reminder to update the profile fires that morning. */
  spay_neuter_planned_on?: string;
  /** `YYYY-MM-DD` (omit-on-null): `dogs.last_seen_on` (M2.16), the last day the
   *  school saw this dog. New 3.0.0. From 6.0.0-lg5.1 a board `check-in` moves it
   *  to the later of its value and the session's date, and the `undo` of that
   *  check-in moves it back; a turn-away never does (design §2.3:2398-2405,
   *  :2530-2531). The verdict and the import stamp it when they land. No gate,
   *  clock or client acts on it in v1 yet: its reader is S14's, dated (design
   *  §1.1:806, M2.16). */
  last_seen_on?: string;
}

/**
 * The waiver/policy catalog with this owner's signature state —
 * `GET /agreements` (owner-scoped). **Staff principals receive `[]`**
 * (`routes/agreements.ts:56-58`): the catalog is owner-facing because signing
 * is an owner action. Promoted 1.13.0 from `routes/agreements.ts:39` (digest
 * dogs-profile/S).
 *
 * Business rules carried with the shape (BUSINESS-LOGIC/auth-accounts.md R16 @
 * :41): the gate is satisfied ONLY by a signature at the document's CURRENT
 * version — an older signature exists on disk but surfaces here as
 * `signed_version: null`. Signatures are OWNER-level (no dog axis): signing
 * once covers every dog. `applies_to: []` means the document applies to ALL
 * service categories (auth-accounts.md :17), not to none.
 *
 * **Explicit non-omit exception:** `signed_version` and `signed_at` are
 * `| null` and always present — "not signed" is an explicit null here, not an
 * absent key (`routes/agreements.ts:78-79`).
 *
 * Known gap, not fixed here: `POST /agreements/:key/sign` is documented but
 * unimplemented (DISCREPANCIES BUG-16), so nothing can move `signed_version`
 * off null today.
 */
export interface AgreementWire {
  key: string;
  label: string;
  current_version: number;
  required: boolean;
  applies_to: ServiceCategory[];
  signed_version: number | null;
  signed_at: string | null;
}

/**
 * The gating-vaccine catalog — `GET /required-vaccines` (auth, unscoped: the
 * catalog is shared across owners; retired requirements are soft-expired out).
 * Promoted 1.13.0 from `routes/requiredVaccines.ts:24` (digest dogs-profile/S).
 * Table `required_vaccines` (`schema.sql:407`).
 */
export interface RequiredVaccineWire {
  key: string;
  label: string;
  /** The service categories this vaccine is mandatory for
   *  (BUSINESS-LOGIC/dogs-evaluations.md :15). */
  gates_categories: ServiceCategory[];
  /** NEW in 1.13.0 (digest dogs-profile/S asked for it; the column has existed
   *  since Shanthi's 2026-07-14 ruling — `schema.sql:414`). Group-class
   *  bookings whose cohort's `class_key` appears here SKIP this vaccine —
   *  puppy classes don't require rabies (BUSINESS-LOGIC/dogs-evaluations.md R13
   *  @ :62; group-classes-enrollments.md R15 @ :47). Only consulted when the
   *  booking category is `group-class`. ALWAYS present — the column is NOT NULL
   *  DEFAULT `'{}'`, so "no exemptions" is `[]`, never an absent key.
   *  Prior to 1.13.0 the column was deliberately not on the wire
   *  (BUSINESS-LOGIC/dogs-evaluations.md :195 recorded the omission). */
  exempt_class_keys: GroupClassKey[];
}

/**
 * A dog's completed-curriculum record — the §J.3 staff surface. Emitted by all
 * three verbs: `GET /staff/dogs/:dogId/completed-programs`,
 * `POST …/completed-programs` (201) and `DELETE …/completed-programs/:program`
 * (200). Staff-only.
 * Promoted 1.13.0 from `routes/staffAlumni.ts:47` (digest dogs-profile/S).
 *
 * `is_alumni` is `dogs.is_alumni`, STORED from 5.0.0-lg4.2 (M4.11; ALUM-U02):
 * recording the 5th program is the became-alumni moment (R21 @ :76) and sets it,
 * and the `DELETE` does not clear it. It touches no credit lot: from 5.0.0-lg4.1
 * an alumni lot takes the ordinary expiry (ALUM-U16).
 *
 * `completed_programs[].program` is typed `CurriculumProgram` — the DB CHECK
 * (`schema.sql:475-476`) constrains the column to exactly those five, and the
 * repository row type already says so (`dogProgramsRepository.ts:22-25`); the
 * route's `string` was the lossy end of the transcription, not the truth.
 * Sanctioned as a promotion-time narrowing with a runtime pin (see the patch's
 * "Narrowings claimed"). The item shape stays INLINE, byte-for-byte as the
 * route declares it — minting a `CompletedProgramWire` name would be a new
 * symbol the digest did not ask for.
 */
export interface CompletedProgramsWire {
  dog_id: string;
  is_alumni: boolean;
  completed_programs: { program: CurriculumProgram; completed_at: string }[];
}

/**
 * The pre-login welcome-screen gallery — `GET /welcome-dogs` (**PUBLIC**, no
 * auth hook: the screen is shown to logged-out users, so it cannot use the
 * auth-scoped `GET /dogs`). Minimal-PII by construction: only these three keys
 * ever leave — no owner identity, no breed, no medical. Live owner-owned dogs
 * whose owner has not opted out (`owners.show_dogs_on_welcome`, default true);
 * staff-owned demo dogs (`owner_id IS NULL`) excluded; shuffled and capped at
 * 60 (`routes/welcomeDogs.ts:11,42-53`). Promoted 1.13.0 from
 * `routes/welcomeDogs.ts:13` (§6: "public, tiny, and mobile mirrors it").
 */
export interface WelcomeDogWire {
  id: string;
  name: string;
  /** Signed URL (uploaded photo) or a bundled asset path; `''` when none. */
  photo: string;
}

/** Dog directory for the cross-owner staff verbs (which reference dogs by UUID
 *  and carry no names). Resolves dog_id → name + owner for display.
 *  `owner_name` is the family's name, or its `email` when the name is empty
 *  (3.0.0-lg2.1: `owners.name` is nullable from M2.01; design §2.2:2244,
 *  "readers that print a name fall back to the email"), so it is never
 *  `null` and never `''`. */
export interface StaffDogWire {
  id: string;
  name: string;
  breed: string;
  owner_id: string;
  owner_name: string;
  profile_image_path?: string;
}

// ---- (c) request bodies + query shapes -------------------------------------

/**
 * `POST /dogs` body (owner create). Promoted 1.13.0 from
 * `routes/dogs.ts:138-159 postDogBodySchema`; pinned there with
 * `Expect<Equal<z.input<…>, PostDogsRequest>>` (§5.1.3).
 *
 * Cross-field rules, stated here because the type cannot (§4.6):
 *   - **One of `birthdate` or `age_months_override` is REQUIRED** — the schema
 *     `.refine`s it so the failure is a clean `bad_request` instead of a raw
 *     Postgres check_violation (`dogs.ts:156-159`, DB CHECK at `schema.sql:346`).
 *   - **`spay_neuter_planned_on` requires `spayed_neutered: false` in the SAME
 *     body** — else 422 `invalid_payload` (`assertSpayFieldsCoherent`,
 *     `dogs.ts:186-197`), mirroring the dogs CHECK.
 *   - The body is `.strict()`: unknown keys are rejected.
 *   - `primary_vet_id` must reference a LIVE vet at commit time (`FOR SHARE`
 *     re-check inside the txn) — else 422 `invalid_payload` (`dogs.ts:325-336`).
 *   - Server defaults applied post-parse (so they are NOT part of what a client
 *     must send): `evaluation_status` → `'not-evaluated'`, `special_notes`
 *     null/blank → `''` (`dogs.ts:309-310`).
 *   - `Idempotency-Key` header is REQUIRED on this and every dogs mutation.
 *
 * **Transcribed embarrassment (§14.1):** `evaluation_status` — including
 * `'passed'` — is accepted from the OWNER here, and no staff verb sets it, so
 * an owner can clear the evaluation booking gate (DISCREPANCIES BUG-11;
 * BUSINESS-LOGIC/dogs-evaluations.md D2 @ :204). Documented, deliberately NOT
 * tightened in this bump; the fix is phase 3 / Adjudication 5.
 */
export interface PostDogsRequest {
  name: string;
  breed: string;
  /** `YYYY-MM-DD`. Required unless `age_months_override` is sent. */
  birthdate?: string;
  /** Positive integer. Required unless `birthdate` is sent. */
  age_months_override?: number;
  primary_vet_id?: string | null;
  special_notes?: string | null;
  evaluation_status?: EvaluationStatus;
  /** ISO datetime WITH offset (`z.string().datetime({ offset: true })`). */
  evaluation_date?: string | null;
  spayed_neutered?: boolean | null;
  /** `YYYY-MM-DD`. Requires `spayed_neutered: false` in the same body. */
  spay_neuter_planned_on?: string | null;
}

/**
 * `PATCH /dogs/:id` body (owner edit). Promoted 1.13.0 from
 * `routes/dogs.ts:161-177 patchDogBodySchema` (`.strict().partial()`); pinned
 * in that file.
 *
 * Notes, transcribed:
 *   - **Every key optional, but an EMPTY body is `bad_request`** ("no updatable
 *     fields in request body", `dogs.ts:396-398`).
 *   - **`birthdate` and `age_months_override` are deliberately absent** — the
 *     DB CHECK requires at least one non-null, so a safe edit needs a
 *     paired-clear guard that is still deferred (`dogs.ts:55-59`).
 *   - `profile_image_path` takes a `media_assets` UUID from a `dog-profile`
 *     upload, or `''` to clear; the txn asserts the media is the owner's own
 *     dog-profile asset (`dogs.ts:414-416`).
 *   - Answering `spayed_neutered` anything but `false` clears a stale
 *     `spay_neuter_planned_on` in the same write (`dogs.ts:384-391`).
 *   - Same `assertSpayFieldsCoherent` rule and same owner-writable
 *     `evaluation_status` caveat as `PostDogsRequest`.
 */
export interface PatchDogsRequest {
  name?: string;
  breed?: string;
  primary_vet_id?: string | null;
  special_notes?: string | null;
  evaluation_status?: EvaluationStatus;
  evaluation_date?: string | null;
  profile_image_path?: string;
  spayed_neutered?: boolean | null;
  spay_neuter_planned_on?: string | null;
}

/**
 * `POST /dogs/:id/vaccines` body (owner). Promoted 1.13.0 from
 * `routes/dogs.ts:199-205 postVaccineBodySchema`; pinned there.
 * `requirement_key`, when a non-blank string, must match a LIVE
 * `required_vaccines.key` — else 422 `invalid_payload` (`dogs.ts:510-517`);
 * `null`/blank/absent means "display-only record, never gates"
 * (BUSINESS-LOGIC/dogs-evaluations.md :15).
 */
export interface PostDogsVaccinesRequest {
  name: string;
  /** `YYYY-MM-DD`. */
  expires_at: string;
  requirement_key?: string | null;
}

/**
 * `PATCH /dogs/:id/vaccines/:vid` body (owner). Promoted 1.13.0 from
 * `routes/dogs.ts:207-214 patchVaccineBodySchema`; pinned there. All keys
 * optional; an empty body is `bad_request` (`dogs.ts:550-552`). Same live-key
 * rule as `PostDogsVaccinesRequest`.
 */
export interface PatchDogsVaccinesRequest {
  name?: string;
  expires_at?: string;
  requirement_key?: string | null;
}

/**
 * `POST /dogs/:id/medications` body (owner). Promoted 1.13.0 from
 * `routes/dogs.ts:216-222 postMedicationBodySchema`; pinned there. Medications
 * carry no gating catalog — there is no `requirement_key` counterpart.
 */
export interface PostDogsMedicationsRequest {
  name: string;
  dose: string;
  frequency: string;
}

/**
 * `PATCH /dogs/:id/medications/:mid` body (owner). Promoted 1.13.0 from
 * `routes/dogs.ts:224 patchMedicationBodySchema` (the POST schema
 * `.partial()`); pinned there. Empty body → `bad_request`.
 */
export interface PatchDogsMedicationsRequest {
  name?: string;
  dose?: string;
  frequency?: string;
}

/**
 * `PUT /dogs/:id/feeding` body (owner). Promoted 1.13.0 from
 * `routes/dogs.ts:226-233 feedingBodySchema`; pinned there. PUT semantics: a
 * 1:1 upsert that RELINKs (resurrects) a soft-expired feeding row in the same
 * statement, preserving its `created_at` and audit chain (`dogs.ts:78-84`).
 * There is no DELETE — "clear feeding" is not a supported verb. `notes`
 * null/blank normalizes to `null` server-side.
 */
export interface PutDogsFeedingRequest {
  brand: string;
  amount: string;
  frequency: string;
  notes?: string | null;
}

/**
 * `GET /vets` query. Promoted 1.13.0 from `routes/vets.ts:43-45
 * searchQuerySchema`; pinned there. `q` absent = unfiltered catalog page; the
 * server caps results at 50 (`vets.ts:41`) — there is no pagination cursor.
 */
export interface GetVetsQuery {
  q?: string;
}

/**
 * `POST /vets` body. Promoted 1.13.0 from `routes/vets.ts:56-64
 * postBodySchema`; pinned there. Open to owners AND staff — the create-dog flow
 * searches first so owners pick an existing clinic, but **there is no unique
 * constraint**: de-duplication is deliberately a create-flow concern, never a
 * DB one (`vets.ts:23-25`). Blank/whitespace optional fields normalize to
 * `null` server-side; `source` is always `'app'` on this path and is not on the
 * wire.
 */
export interface PostVetsRequest {
  name: string;
  phone?: string | null;
  email?: string | null;
  address?: string | null;
  notes?: string | null;
}

/**
 * `PATCH /vets/:id` body. Promoted 1.13.0 from `routes/vets.ts:66-75
 * patchBodySchema`; pinned there. **Staff-only** — a vet row is shared across
 * many owners, so one owner must not be able to rename it (`vets.ts:27-29`).
 * All keys optional; empty body → `bad_request`.
 */
export interface PatchVetsRequest {
  name?: string;
  phone?: string | null;
  email?: string | null;
  address?: string | null;
  notes?: string | null;
}

/**
 * `POST /staff/dogs/:dogId/completed-programs` body (staff). Promoted 1.13.0
 * from `routes/staffAlumni.ts:45 recordBodySchema`; pinned there. Idempotent at
 * two levels: the `Idempotency-Key` replay AND the partial-unique no-op —
 * re-recording an already-live `(dog, program)` succeeds without a second row
 * (`schema.sql:483-484`). Recording the FIFTH distinct program is the
 * became-alumni moment (R21 @ :76).
 */
export interface PostStaffDogsCompletedProgramsRequest {
  program: CurriculumProgram;
}

// ---- (d) per-endpoint 422 detail aliases -----------------------------------
//
// NONE — deliberately, not by omission. No dogs-profile endpoint constructs an
// `ApiErrorDetailWire` arm: every throw on this surface is a bare
// `bad_request` / `invalid_payload` / `not_found` / `conflict` with a message
// and no `details` (routes/dogs.ts, vets.ts, agreements.ts,
// requiredVaccines.ts, staffAlumni.ts, welcomeDogs.ts — verified by the
// construction-site sweep in the patch's Evidence §E4). The booking-gate
// family that READS this domain's data (`EvaluationGap`, `VaccineGap`,
// `EligibilityGap`, …) is emitted by the bookings and enrollments surfaces and
// is contracted in §1.

// <<< domain:dogs-profile =====================================================

// >>> domain:enrollments ======================================================

// ---- (a) domain-local enums ------------------------------------------------

/** `group_classes.enrollment_type` — `'open'` = rolling enrollment (Puppy,
 *  "join any Saturday"); `'cohort'` = fixed start dates (Manners 1/2, Public
 *  Pups). Promoted 1.13.0 from `lib/groupClassWire.ts:32`, where it was typed
 *  `string` with this union only in a trailing comment (digest enrollments/L
 *  "Promote the group-class / enrollment shape family"; DRIFT-26 @
 *  BUSINESS-LOGIC/DISCREPANCIES.md:399).
 *
 *  **§14.2 class-B narrowing** (`string` → this union). NOT a pgEnum: the
 *  guarantee is the table CHECK `enrollment_type IN ('open','cohort')`
 *  (`.claude/backend/schema.sql:497`), so no `conformance.ts` DB pin is
 *  possible — the runtime pin is the contract test named in the patch.
 *  BUSINESS-LOGIC/group-classes-enrollments.md:10.
 *
 *  Documented, not fixed: `'open'` has NO distinct behavior in the enroll
 *  transaction today — every cohort is materialized as a fixed W-week run from
 *  `start_date` (BUSINESS-LOGIC/group-classes-enrollments.md:174;
 *  DISCREPANCIES.md:1011). The field states the catalog's intent, not a server
 *  behavior a client may rely on. */
export type GroupClassEnrollmentType = 'open' | 'cohort';

/** Per-enrollment money state on `GET /enrollments`: `'paid'` (a succeeded
 *  charge belonging to THIS enrollment), `'pay-later'` (a card-backed open
 *  invoice, due 24h before the first session, which the owner pays through
 *  `POST /invoices/:id/pay`; nothing bills it automatically from 5.0.0-lg4.1),
 *  or `'pending'` (an async/3DS charge not yet settled — rare). Promoted 1.13.0
 *  from `db/repositories/enrollmentsRepository.ts:30` under its existing
 *  exported name (§4.4); that file now re-exports it from here — the
 *  `ChargeStatus` / `chargesRepository.ts:111` precedent. Digest
 *  enrollments/L.
 *
 *  "Belonging to this enrollment" is load-bearing (ADDENDUM 3 §A3.17,
 *  2026-08-22): a (cohort, dog) pair is not an enrollment — withdraw plus
 *  re-enroll mints a second one under the same pair, and the earlier predicate
 *  showed `'paid'` off the PREVIOUS enrollment's money.
 *  {@link EnrollmentDogResultWire.payment_state} carries the same three values
 *  for one dog inside a partial-success envelope.
 *
 *  No pgEnum backs it — the value is computed by the read query's `CASE`
 *  (`enrollmentsRepository.ts:78-117`), so no `conformance.ts` pin is possible;
 *  the runtime pin is the repointed `GET /enrollments` contract test. */
export type EnrollmentPaymentStatus = 'paid' | 'pay-later' | 'pending';

/** Why one dog of a multi-dog enrollment did not enroll. Per-dog counterpart of
 *  the whole-request 422 codes; anti-enumeration preserved: 'not_found' answers
 *  identically for "not yours" and "doesn't exist". */
export type EnrollmentDogFailureReason =
  | 'not_found'
  | 'already_enrolled'
  | 'eligibility_missing'
  | 'vaccine_missing'
  | 'seat_shortfall'
  | 'charge_failed'
  | 'charge_unverified';

/** One missing required vaccine, inside a per-dog result (no dog_id — the
 *  parent row carries it). Same fields as the 422 detail arm. */
export interface EnrollmentVaccineGapWire {
  requirement_key: string;
  label: string;
}

export interface EnrollmentDogResultWire {
  dog_id: string;
  enrolled: boolean;
  /** Present iff !enrolled. */
  reason?: EnrollmentDogFailureReason;
  /** reason === 'eligibility_missing': the OR-alternatives (class keys). */
  missing_prereq_alternatives?: string[];
  /** reason === 'vaccine_missing': this dog's complete gap list. */
  missing_vaccines?: EnrollmentVaccineGapWire[];
  /** reason === 'seat_shortfall': seats remaining at decision time (never
   *  auto-assigned). */
  seats_remaining?: number;
  /** reason === 'charge_failed': the 1.8.0 blocker taxonomy — declined /
   *  authentication_required. Never 'processing' (see charge_unverified). */
  charge_blocker?: ChargeBlocker;
  /** Present iff enrolled: 'paid' (captured), 'pay-later' (open invoice),
   *  'pending' (enrolled, capture completing — treat as the processing copy
   *  family, never a decline, never a green check on money). */
  payment_state?: 'paid' | 'pay-later' | 'pending';
  /** Present iff enrolled: this dog's server-authoritative price. */
  amount_cents?: number;
  /** Present iff reason === 'charge_unverified' — the only refusal that
   *  leaves a LIVE, non-terminal intent for this dog. The client
   *  Idempotency-Key under which that live attempt EXECUTED: this request's
   *  own key when the mint happened now, or the carried `retry_of` when a
   *  re-verify found it still processing. Auto-retry clients echo it back as
   *  `retry_of` on the next attempt and omit `retry_of` when absent — the
   *  rule that keeps at most one live hold per dog (ADDENDUM 3 §A3.14). */
  verify_key?: string;
}

/** POST /enrollments response when the request sent `allow_partial: true`.
 *  201 when >=1 dog enrolled; 200 when 0 enrolled. Requests WITHOUT
 *  allow_partial keep the existing 201 BookingWire[] and all-or-nothing
 *  semantics unchanged. */
export interface EnrollmentResultWire {
  cohort_id: string;
  /** Request order (the order the owner picked dogs) — presentational
   *  contract. */
  results: EnrollmentDogResultWire[];
  /** Enrolled dogs only; ASC scheduled_at then dog_id (unchanged rule, R16). */
  bookings: BookingWire[];
  /** Money truth for the confirmation line: sum actually CAPTURED in this
   *  request. 0 for pay-later and for every failure. 'pending' dogs are
   *  excluded until captured — the sheet must never announce money that has
   *  not moved. */
  total_captured_cents: number;
  payment: 'now' | 'later';
}

/** What happened to the owner's money on a withdraw — the definite answer
 *  Allison's 2026-08-21 ruling requires ("no uncertains"). Exactly one per
 *  withdraw. 'release_pending' is still definite about the OUTCOME (the owner
 *  pays nothing) while the mechanism completes asynchronously. */
export type WithdrawMoneyOutcome =
  | 'refunded' // a captured charge is being returned; refunded_cents > 0
  | 'released' // an uncaptured authorization was cancelled — never charged
  | 'release_pending' // payment was still settling; automatic release-or-full-refund committed
  // refund_manual: a refund is owed and will be made BY HAND — no automatic
  // machinery exists for this charge (predates Stripe wiring).
  | 'refund_manual'
  | 'voided' // the open pay-later invoice was voided — never charged
  | 'none'; // no live money is attached to this enrollment

/** No pgEnum (wire-only domain union) — member order mirrors the
 *  `WithdrawMoneyOutcome` union declaration order; §16 pins set equality. New
 *  1.13.0 — deletes mobile's hand mirror (`withdrawResult.ts:15
 *  KNOWN_OUTCOMES`, which re-derives from this). */
export const WITHDRAW_MONEY_OUTCOMES = [
  'refunded',
  'released',
  'release_pending',
  'refund_manual',
  'voided',
  'none',
] as const satisfies readonly [WithdrawMoneyOutcome, ...WithdrawMoneyOutcome[]];

export interface EnrollmentWithdrawResultWire {
  withdrawn: true;
  /** Unchanged semantics (R30): cents on their way back to the card. 0 for
   *  every non-'refunded' outcome. */
  refunded_cents: number;
  money_outcome: WithdrawMoneyOutcome;
  /** Present iff money_outcome is 'released' or 'release_pending': the
   *  authorized cents whose hold is being released — what the owner sees
   *  disappearing from their statement. */
  released_cents?: number;
  /** Present iff money_outcome is 'refund_manual': the refundable remainder
   *  (amount − non-failed refunds, the R9 computation) — recorded at withdraw
   *  time as a terminal 'unroutable' refunds row (money-residue 1.2); the
   *  manual step owns only the SEND. refunded_cents stays 0 here, preserving
   *  its invariant. */
  owed_cents?: number;
}

// ---- (b) response wires (continued) ----------------------------------------

/** `GET /group-classes` · `GET /group-classes/:key` — one catalog entry.
 *  Promoted 1.13.0 from `lib/groupClassWire.ts:24` (digest enrollments/L;
 *  DRIFT-26 @ DISCREPANCIES.md:399). DATA-CONTRACT §B (Δ 2026-05-20, Day 6a).
 *
 *  - `price_per_dog_cents` is cents-on-wire (financial-amount convention).
 *  - `age_range?` is optional-omit — omitted when the column is NULL **or the
 *    empty string** (`groupClassWire.ts:63`); the one field in this domain that
 *    omits on `''` as well as on null.
 *  - `capacity` is the class-level DEFAULT cap. The authoritative per-cohort
 *    number is {@link CohortWire.capacity} (R11 @
 *    BUSINESS-LOGIC/group-classes-enrollments.md:43). Mobile reads this one for
 *    seat maths today — a CLIENT bug, not a wire one (DRIFT-25 @
 *    DISCREPANCIES.md:393).
 *  - The wire deliberately does NOT carry prereqs: they depend on the dog, not
 *    the class, and are served by `GET /dogs/:id/group-eligibility` (R2 @
 *    BUSINESS-LOGIC/group-classes-enrollments.md:28).
 *
 *  Catalog reads are shared and unscoped — owner and staff see identical data,
 *  ordered enum-naturally by `key`, Redis-cached 10 minutes (R1/R3 @
 *  BUSINESS-LOGIC/group-classes-enrollments.md:27,29). */
export interface GroupClassWire {
  key: GroupClassKey;
  name: string;
  weeks: number;
  price_per_dog_cents: number;
  capacity: number;
  age_range?: string;
  description: string;
  /** §14.2-B narrowing of `lib/groupClassWire.ts:32`'s `string`. */
  enrollment_type: GroupClassEnrollmentType;
}

/** `GET /group-classes/:key/cohorts` · `GET /cohorts/:id` — one scheduled run
 *  of a class. Promoted 1.13.0 from `lib/groupClassWire.ts:35` (digest
 *  enrollments/L). Ordered by `start_date` ASC (R1).
 *
 *  - `capacity` is additive (Day-6a) and is the SERVER OF RECORD per cohort — a
 *    cohort may run at a custom cap. `filled + requested <= capacity` is the
 *    enroll check, `CHECK (filled <= capacity)` the unbypassable DB floor (R11
 *    @ BUSINESS-LOGIC/group-classes-enrollments.md:43).
 *  - `end_date?` is optional-omit: open-enrollment cohorts have no end.
 *  - `weekly_time` is a DISPLAY LABEL ("6:00 PM"), not a parseable time
 *    (`schema.sql:551`).
 *  - `class_key`/`location` were ALREADY these unions in the lib file
 *    (`groupClassWire.ts:37-38`): transcription, NOT a §14.2 narrowing. */
export interface CohortWire {
  id: string;
  class_key: GroupClassKey;
  location: LocationKey;
  start_date: string;
  end_date?: string;
  weekly_time: string;
  weeks: number;
  capacity: number;
  filled: number;
}

/** `GET /dogs/:id/group-eligibility?class=` — the server-derived prereq answer.
 *  Promoted 1.13.0 from `lib/groupClassWire.ts:47` (digest enrollments/L).
 *
 *  A dog is eligible iff the class has zero live `class_prereq_options` rows OR
 *  the dog has completed AT LEAST ONE of them (OR semantics, R4 @
 *  BUSINESS-LOGIC/group-classes-enrollments.md:33). `eligible: true` omits
 *  `missing_prereq_options` (Day-4a convention); `eligible: false` emits the
 *  full OR-alternative list, enum-natural ordered.
 *
 *  Owner-only, and an unknown dog / not-your-dog / staff principal all answer
 *  404 identically (anti-enumeration, R5 @ …:34). Eligibility is re-checked
 *  authoritatively inside the enroll transaction (R6 @ …:35), so this endpoint
 *  is ADVISORY — a client must never treat it as the gate. */
export interface GroupEligibilityWire {
  class_key: GroupClassKey;
  eligible: boolean;
  missing_prereq_options?: GroupClassKey[];
}

/** `GET /enrollments` — the owner's "Currently enrolled" rows, one per live
 *  (cohort, dog). Promoted 1.13.0 from `routes/enrollments.ts:1131` (digest
 *  enrollments/L; DRIFT-26 @ DISCREPANCIES.md:399). Owner-only (R21 @
 *  BUSINESS-LOGIC/group-classes-enrollments.md:56).
 *
 *  - `first_session_at` is the MIN live `scheduled_at` for the (cohort, dog).
 *  - `can_withdraw` is `first_session_at > now`, computed at read time; the
 *    withdraw verb re-checks it authoritatively under the cohort lock (R22 @
 *    …:57), so a client must treat it as advisory.
 *  - `weekly_time` is nullable HERE while {@link CohortWire.weekly_time} is
 *    not. The column is NOT NULL (`schema.sql:551`); this read's row parser
 *    declares it nullable anyway (`enrollmentsRepository.ts:52`). The wire
 *    transcribes the looser truth rather than tightening it (§14.1); mobile
 *    already models it nullable (`types/enrollment.ts:22`).
 *
 *  Documented, not fixed: there is no "current" filter. Stored booking status
 *  never flips past `'upcoming'`, so finished cohorts persist forever with
 *  `can_withdraw: false` (NOTE-19 @ DISCREPANCIES.md:753;
 *  BUSINESS-LOGIC/group-classes-enrollments.md:165). */
export interface EnrollmentWire {
  cohort_id: string;
  dog_id: string;
  /** §14.2-B narrowing of `routes/enrollments.ts:1134`'s `string`. Source is
   *  `cohorts.class_key`, the `group_class_key` pgEnum (`schema.sql:547`). */
  class_key: GroupClassKey;
  class_name: string;
  /** §14.2-B narrowing of `routes/enrollments.ts:1136`'s `string`. Source is
   *  `cohorts.location`, FK → `locations.slug` (`schema.sql:548`) — the SAME
   *  column {@link CohortWire.location} already types as `LocationKey`. */
  location: LocationKey;
  start_date: string;
  weekly_time: string | null;
  weeks: number;
  first_session_at: string;
  payment_status: EnrollmentPaymentStatus;
  can_withdraw: boolean;
}

// ---- (c) request bodies + query shapes -------------------------------------

/** `POST /enrollments` request body — group-class cohort enrollment.
 *  Owner-only (staff get 403); `Idempotency-Key` header REQUIRED (R8 @
 *  BUSINESS-LOGIC/group-classes-enrollments.md:40). Promoted 1.13.0 from
 *  `routes/enrollments.ts` — the first time `allow_partial` and
 *  `retry_of` are TYPED anywhere: both shipped as CHANGELOG prose only
 *  (`[1.11.0]`, `[1.12.0]`). Digest enrollments/L; DRIFT-26.
 *
 *  Group-class enrollment NEVER goes through `POST /bookings` (R8).
 *
 *  Cross-field rules the type cannot state (§4.6):
 *  - `dog_ids` must contain DISTINCT values — enforced after Zod, in
 *    `validateEnrollmentBody` (`routes/enrollments.ts`), and it is
 *    the one body rule answering **422 `invalid_payload`**. Everything Zod
 *    rejects — an unknown key (the schema is `.strict()`), a bad uuid, wrong
 *    arity — answers **400 `bad_request`** via `parseOrThrow`
 *    (`lib/zodIssues.ts:38-43`). Two statuses for "bad body"; both are
 *    pre-1.13.0 behavior and neither changes here.
 *  - Price is never sent: the per-dog amount is the class's
 *    `price_per_dog_cents`, resolved server-side from the cohort (R24 @ …:62).
 *  - The cohort's first session (`cohorts.start_date`) must not be later than
 *    the horizon, reckoned as on `PostBookingsRequest`, else **422
 *    `beyond_booking_horizon`**, no `details` (4.0.0-lg3.1; DAY-U10, DAY-09).
 *    The cohort is refused, not a dog, so this answers 422 with or without
 *    `allow_partial`, before any Stripe call.
 *
 *  The RESPONSE shape depends on `allow_partial`, not on the version — see
 *  that field. */
export interface PostEnrollmentsRequest {
  cohort_id: string;
  /** 1..5 distinct dog uuids. The cap is `MAX_DOGS_PER_REQUEST`
   *  (`MAX_DOGS_PER_REQUEST`, `routes/enrollments.ts`) — a hostile body bounded BEFORE the DB is
   *  touched; five covers every plausible household. */
  dog_ids: string[];
  payment_method_id: string;
  /** Default `false` = pay-now: one Stripe PaymentIntent per dog, AUTHORIZED
   *  before the enroll transaction and captured after it commits (R25/R26 @
   *  BUSINESS-LOGIC/group-classes-enrollments.md:63-64). `true` = one
   *  card-backed open invoice per dog with `due_at = cohort.start_date − 24h`,
   *  which the owner pays through `POST /invoices/:id/pay`. From 5.0.0-lg4.1
   *  nothing bills it automatically: the auto-charge worker is gone and this
   *  arm stays until 8.0.0 removes it (PAY-U10). Withdrawing voids an open one,
   *  so a pay-later that is withdrawn unpaid is never charged (R27 @ …:65). */
  pay_later?: boolean;
  /**
   * Wire 1.11.0 — per-dog partial success. Named for the SEMANTICS it changes,
   * not the shape: with it, the route enrolls every dog that passes its checks
   * and reports every dog that doesn't, per dog, with the exact reason
   * (Allison 2026-08-12: "not transactional where we fail the entire ting").
   * The response is then {@link EnrollmentResultWire} — 201 when >=1 dog
   * enrolled, 200 when 0. WITHOUT it the route keeps all-or-nothing semantics
   * and the 201 `BookingWire[]` response byte-for-byte.
   *
   * **The field is the degrade boundary, not the version.** An old app does
   * `raw.map(toBooking)` on this response; handed an envelope it would
   * TypeError into its submit catch and render "something went wrong" while
   * dogs were actually enrolled and charged — the worst degrade available. Old
   * clients never send this field, so they are never handed one.
   *
   * Omitting it hashes identically to a pre-1.11.0 body (`db/mutation.ts`
   * canonical-JSON hash), so no in-flight Idempotency-Key changes meaning.
   */
  allow_partial?: boolean;
  /**
   * Wire 1.12.0 — the client `Idempotency-Key` under which this dog's latest
   * EXECUTED payment attempt ran, sent by mobile on an AUTOMATIC retry
   * (`designs/partial-success-enrollment.md` ADDENDUM 3 §A3.13, as repaired by
   * §A3.14; Allison's Q-D ruling: "retry 3 times before settling for yes or
   * no").
   *
   * It exists because the server keeps NO record of a refused dog's intent —
   * no charge row is minted for a dog that never enrolled — so the live attempt
   * is reachable only through its derived Stripe key. With it, the authorize
   * step RE-VERIFIES that attempt before it may mint a new one, which is what
   * stops a `charge_unverified` retry from putting a second hold on a card
   * whose first one is still verifying.
   *
   * **Not "the original request's key"** (§A3.14 supersedes §A3.13 here). The
   * client does not infer which key that is: the server names it per dog as
   * {@link EnrollmentDogResultWire.verify_key}, and the client echoes THAT
   * value here, omitting the field when it is absent. A chain that always named
   * the FIRST attempt would re-verify a dead intent and mint a third hold
   * beside the live second — the double-hold the rule exists to prevent.
   *
   * Length-bounded for the same reason the header is: `${retry_of}:dog:${dogId}`
   * goes to Stripe, which caps keys at 255. The bound is DERIVED from the
   * longest suffix this API appends (`db/mutation.ts:70`
   * `IDEMPOTENCY_KEY_MAX_LEN` — 206 at 1.13.0) and is stated once in the §0
   * conventions block. A body-supplied key that skipped it would mint an
   * unsendable derived key on a money path.
   *
   * Omitting it hashes identically to a pre-1.12.0 body; a body that CARRIES it
   * is a new logical mutation under its own fresh key.
   */
  retry_of?: string;
}

/** `POST /enrollments/:cohortId/withdraw` request body. Owner-only, per-dog,
 *  `Idempotency-Key` REQUIRED, `.strict()` (`routes/enrollments.ts:262`).
 *  Promoted 1.13.0 (digest enrollments/L); the RESPONSE half landed 1.12.0 as
 *  {@link EnrollmentWithdrawResultWire}.
 *
 *  One dog per call — there is no bulk withdraw. Under the cohort lock the verb
 *  answers 409 `conflict` when the dog has no live bookings in the cohort, and
 *  409 `conflict` once `now >= first session` ("this class has already started
 *  — contact us to withdraw"). NEITHER 409 carries `details`, which is why this
 *  endpoint has no §3.5 alias (R22 @
 *  BUSINESS-LOGIC/group-classes-enrollments.md:57).
 *
 *  Documented, not fixed: once that window closes, NO code path can unenroll or
 *  refund a dog — the guard's "staff can still cancel via the portal" is not
 *  true today, and per-booking cancel rejects `category='group-class'` in both
 *  the owner and the staff route (R23 @ …:58; DISCREPANCIES.md:68-73). */
export interface PostEnrollmentsWithdrawRequest {
  dog_id: string;
}

/** `GET /dogs/:id/group-eligibility` query string. Promoted 1.13.0 from
 *  `routes/groupClasses.ts:52-54`. An unknown class key answers **400
 *  `bad_request`** at Zod parse time, not 404 — which is why that route's 404
 *  comment says the key was already rejected before the handler ran.
 *
 *  Beyond the §7 "Fills" column for this lane, landed deliberately: the
 *  RESPONSE half ({@link GroupEligibilityWire}) is in this fence, and a
 *  half-contracted endpoint is exactly the gap this bump exists to close. */
export interface GetDogsGroupEligibilityQuery {
  class: GroupClassKey;
}

// ---- (d) per-endpoint 422 union alias (§3.5) -------------------------------

/** Every `details` arm `POST /enrollments` can emit. 422 unless noted
 *  (statuses per `API_ERROR_STATUS`, §1).
 *
 *  Gate arms fire in priority order payment → vaccine → agreement against
 *  category `'group-class'`; the first failing gate aborts with that gate's
 *  COMPLETE detail (R14 @ BUSINESS-LOGIC/group-classes-enrollments.md:46).
 *
 *  Three arms are deliberately ABSENT, and each absence is a rule:
 *  - {@link EvaluationRequiredDetails} — group-class is not eval-gated; it uses
 *    the prereq system instead, in BOTH the pre-check
 *    (`lib/bookingGatePreCheck.ts:33-37`) and the DB trigger
 *    (`schema.sql:2041-2043`). `gateTriggerErrorToApiError` can build one, but
 *    the trigger that would raise it cannot fire for this category.
 *  - {@link InsufficientCapacityDetails} — this endpoint's capacity refusal is
 *    `cohort_full` (R11 @ …:43), a FLAT-spread arm, not the nested one.
 *  - {@link InsufficientCreditsDetails} — group-class is money-paid, never
 *    credit-paid; there is no credit-ledger interaction on this path at all
 *    (R28 @ …:66).
 *
 *  Degraded emissions are legal on this alias: the trigger-floor mapping reuses
 *  `vaccine_missing` / `agreement_unsigned` with `missing: []` when the
 *  pre-check-to-INSERT race fires (`lib/bookingErrors.ts:409-450`). */
export type PostEnrollmentsErrorDetails =
  | PaymentRequiredDetails
  | VaccineMissingDetails
  | AgreementUnsignedDetails
  | EligibilityMissingDetails
  | AlreadyEnrolledDetails
  | CohortFullDetails_
  /** 402, NOT 422 — a card that refused is not a body that failed validation
   *  (wire 1.9.0). `charge_blocker` is OMITTED, never defaulted, when no dog
   *  produced one: a hold someone else released is a refusal with no cause we
   *  know, and `'declined'` would render "Your card was declined" for a card
   *  that was never asked (ADDENDUM 1 R5; `routes/enrollments.ts:1320-1338`). */
  | PaymentFailedDetails;

// (e) domain-owned pure helpers: NONE. `computeEligibility`
// (`lib/groupClassWire.ts:93`) is pure and would fit §2.1(e) mechanically, but
// R4 makes eligibility SERVER-derived — shipping the derivation to clients
// invites exactly the client-side gating R4 forbids, and it needs
// `class_prereq_options` rows no client can see. It stays in the lib file.

// <<< domain:enrollments ======================================================

// >>> domain:events ===========================================================
//
// The owner-facing events catalog + RSVP surface, all of `routes/events.ts`:
//   GET    /events            [auth]         → EventWire[]
//   GET    /events/rsvps      [auth]         → EventRsvpWire[]  (staff → [])
//   GET    /events/:id        [auth]         → EventWire
//   POST   /events/:id/rsvp   [auth, owner]  → EventRsvpWire
//   DELETE /events/:id/rsvp   [auth, owner]  → DeleteEventsRsvpResponse
// Promoted 1.13.0 from `lib/eventWire.ts` + `routes/events.ts` (digest events/M
// "Promote Event / EventRsvp into wire.ts" + events/S "Contract the RSVP request
// body, the DELETE envelope, and event_full"). Rules R35-R41 @
// BUSINESS-LOGIC/notifications-events.md:97-103. Event RSVPs touch NO money:
// no charge, no credits, anywhere on this surface (notifications-events.md:159).

/**
 * An event's location, exactly as emitted: free text plus a coordinate pair,
 * denormalized from the four flat `events.loc_*` columns (`schema.sql:1640-1643`
 * — `loc_latitude`/`loc_longitude` are `double precision`, so both arrive as
 * JSON numbers, never strings). Promoted 1.13.0 from `lib/eventWire.ts:29-34`
 * (digest events/M).
 *
 * DOCUMENTED AS-IS, deliberately not aligned: every other `location` on this
 * wire is a `LocationKey` scalar naming a campus. An event's location is a
 * nested free-text PLACE — a yard, a patio, a park — and flattening it to
 * `LocationKey` would be a breaking retype of a shipped shape, so the
 * divergence is pinned here instead of fixed (design §6, events row).
 */
export interface EventLocationWire {
  label: string;
  address: string;
  latitude: number;
  longitude: number;
}

/**
 * One event occurrence, as `GET /events` and `GET /events/:id` emit it.
 * Promoted 1.13.0 from `lib/eventWire.ts:36-46` (digest events/M); that module
 * now re-exports this type and keeps only its row → wire mappers.
 *
 * Two wire renames the shape keeps on purpose (R36 @
 * BUSINESS-LOGIC/notifications-events.md:98):
 *   - `events.starts_at` → the wire key `date`. The column keeps the more
 *     accurate name at the DB layer, where range and duration math live.
 *   - the four flat `loc_*` columns → the nested `location` object above.
 * `events.series_id` is deliberately NOT emitted (the series convention is an
 * open design item, not a contracted field).
 *
 * `date` is an ISO-8601 UTC instant ("2026-05-23T19:00:00.000Z"), like every
 * timestamp on this wire.
 *
 * `GET /events` returns EVERY live event — past ones included — oldest start
 * first; "this week" vs "last week" is client-side filtering, not an API
 * concern (R35 @ :97). The catalog is shared and unscoped: an owner principal
 * and a staff principal get byte-identical lists. Only RSVPs are owner-scoped.
 *
 * `spots_filled` is the live count of RSVP'd DOGS (not RSVPs) for the event —
 * a batched count of live `event_rsvp_dogs` across its live `event_rsvps`,
 * resolved by the route and passed into the mapper. `capacity` is the SOFT cap
 * (see `PostEventsRsvpErrorDetails`); omitted entirely when NULL, which means
 * uncapped, not zero.
 */
export interface EventWire {
  id: string;
  name: string;
  date: string;
  duration_minutes: number;
  location: EventLocationWire;
  description?: string;
  is_recurring: boolean;
  capacity?: number; // soft cap; omitted when NULL (uncapped)
  spots_filled: number; // live RSVP'd dog count
}

/**
 * One owner's live RSVP to one event, with the dogs denormalized back in from
 * `event_rsvp_dogs`. Emitted by `GET /events/rsvps` (array) and by
 * `POST /events/:id/rsvp` (single, the saved row). Promoted 1.13.0 from
 * `lib/eventWire.ts:48-53` (digest events/M).
 *
 * OWNER-ONLY by design: a staff principal gets `[]` from `GET /events/rsvps`
 * and 403 from both writes — "they organize, not RSVP" (R37 @
 * BUSINESS-LOGIC/notifications-events.md:99). There is no owner id on the wire
 * because there is no cross-owner read: every row a caller sees is their own.
 *
 * At most ONE live RSVP exists per (event, owner) — a partial unique index —
 * so `POST` REPLACES the dog set rather than appending, and un-RSVP then
 * re-RSVP works (R38/R40 @ :100,:102). `rsvpd_at` is an ISO-8601 UTC instant;
 * on a replacing upsert it is the CURRENT RSVP's stamp, not the original one.
 */
export interface EventRsvpWire {
  id: string;
  event_id: string;
  dog_ids: string[];
  rsvpd_at: string;
}

/**
 * `DELETE /events/:id/rsvp` response body — the literal, whole emission
 * (`routes/events.ts:180`). Promoted 1.13.0 (digest events/S, "the DELETE
 * envelope"); named per §4 rule 1 from what the route actually sends.
 *
 * The verb soft-expires the owner's live RSVP and its dog rows. It is an
 * idempotent 200 no-op when they have no live RSVP, and `{ ok: true }` is the
 * ENTIRE body on both the first call and an `Idempotency-Key` replay — nothing
 * about the deleted RSVP comes back, so a client wanting the new
 * `spots_filled` re-reads the event.
 *
 * It 404s when the EVENT is not live (`events.ts:175-178`) — which is the
 * known orphan bug (digest events/S fix, phase 3.1): an ops-cancelled event
 * leaves the owner's RSVP live and permanently un-cancellable. Stated here so
 * the contract does not imply a cleanliness the runtime lacks.
 */
export interface DeleteEventsRsvpResponse {
  ok: true;
}

/**
 * `POST /events/:id/rsvp` request body — what a client may SEND. Promoted
 * 1.13.0 from the Zod schema at `routes/events.ts:45-47` (digest events/S) and
 * pinned to it by `PostEventsRsvpBodyConformance` beside that schema (§5.1.3).
 *
 * Semantics, enforced in the route rather than by the type (R38 @
 * BUSINESS-LOGIC/notifications-events.md:100):
 *   - `dog_ids` REPLACES the owner's dog set for this event — an upsert, not
 *     an append. The empty array is rejected, so "no dogs" is `DELETE`, never
 *     `POST []`.
 *   - 1 to `MAX_RSVP_DOGS = 5` entries (`routes/events.ts:44`) — a body cap
 *     that bounds a hostile payload before the DB reaches it, mirroring
 *     POST /enrollments and POST /bookings. Over the cap → 400 `bad_request`.
 *   - every id must be a UUID and must belong to the caller. A dog that is not
 *     theirs and a dog that does not exist BOTH 404, deliberately — dog ids
 *     must not enumerate across owners.
 *   - duplicates inside one body → 400 `bad_request` (`events.ts:199-204`).
 *   - an `Idempotency-Key` header is required, as on every mutation (R41 @
 *     :103); the replay hash covers (event id, dog ids), not the raw body.
 *
 * HISTORICALLY NON-STRICT — documented, NOT tightened (§14.1; confirmed at
 * dispatch per §16-6): this schema's `z.object` carries no `.strict()`, so an
 * unknown extra key is accepted and silently stripped, where its neighbours
 * 400 on one (`enrollments.ts:262`, `paymentMethods.ts:67,69`,
 * `staffAlumni.ts:45` all `.strict()`). Production accepts those payloads today
 * and a promotion may not change that; the desire to add `.strict()` is FILED
 * to phase 3, not enacted.
 * The "still accepts an unknown extra body key" contract test pins the laxity
 * so a future tightening has to be a deliberate, visible decision.
 */
export interface PostEventsRsvpRequest {
  dog_ids: string[];
}

/**
 * Every `details` arm `POST /events/:id/rsvp` can 422 with — there are NONE.
 * `never` is the truthful alias here (§3.5), not a placeholder: the endpoint's
 * only domain 422 is `event_full` (`routes/events.ts:139-141`), thrown with a
 * message and no `details` payload at all, so the serializer emits the two-key
 * envelope `{ error: { code, message } }` (`auth/plugin.ts:196-198`) — details
 * is ABSENT, not null and not `{}`. Clients must not write a narrowing switch
 * here: the code IS the whole signal. "This event is full" needs no per-dog
 * breakdown the way a vaccine, credit or eligibility gate does.
 *
 * Promoted 1.13.0 (digest events/S, "and event_full"). The `event_full` code
 * and its 422 status live in §1 (skeleton); the capacity rule behind it (R39 @
 * BUSINESS-LOGIC/notifications-events.md:101) is a SOFT cap, checked under a
 * per-event row lock as `liveDogs − ownerCurrentDogs + requested > capacity`
 * — the owner-subtract term is why re-RSVPing the same dogs never self-blocks.
 * Deliberately NOT a DB CHECK (contrast `cohorts.filled <= capacity`, the hard
 * cap) so a staff/portal surface may exceed it; `capacity` NULL = uncapped and
 * never 422s.
 *
 * The endpoint's other failures carry no `details` either: 400 `bad_request`
 * (bad uuid, duplicate `dog_ids`, missing/oversized `Idempotency-Key`), 403
 * `forbidden` (staff principal), 404 `not_found` (event not live, or a dog not
 * owned/not existing), 409 `idempotency_inflight`, 422 `idempotency_mismatch`.
 * Pinned by the "422 event_full carries NO details key" contract test.
 */
export type PostEventsRsvpErrorDetails = never;

// <<< domain:events ===========================================================

// >>> domain:messaging ========================================================

export interface ThreadParticipantWire {
  id: string;
  name: string;
  role: StaffRole;
  image_path?: string;
}

export interface ThreadWire {
  id: string;
  category: ThreadCategory;
  title: string;
  sub_text: string;
  participant: ThreadParticipantWire;
  related_dog_ids: string[];
  last_message: string;
  last_message_at: string;
  unread_count: number;
}

/** One photo/video attachment on a message. `url` is a short-lived signed GET
 *  (5-min TTL); width/height/blurhash let the FE lay out without a round-trip;
 *  `duration_ms` is video-only. */
export interface MessageAttachmentWire {
  media_id: string;
  kind: MediaKind;
  url: string;
  width: number | null;
  height: number | null;
  blurhash: string | null;
  duration_ms: number | null;
}

export interface MessageWire {
  id: string;
  thread_id: string;
  sender_id: string;
  sender_name?: string;
  text: string;
  /** Photo/video attachments, ordered as sent. Omitted when the message has none. */
  attachments?: MessageAttachmentWire[];
  sent_at: string;
  is_read: boolean;
}

// ---- (c) request bodies ----------------------------------------------------

/** `POST /threads/:id/messages` request body — the **owner** send grammar.
 *  Promoted 1.13.0 from `routes/threads.ts:48–59` (`messageBodySchema`);
 *  digest messaging/S "contract the two messaging request bodies".
 *
 *  **Cross-field rule (stated, not typed — §4 rule 6): a message must carry
 *  non-empty `text` OR at least one `attachment_media_ids` entry.** Both keys
 *  are individually optional, which is the schema's real key-level truth; the
 *  one-required rule is enforced by the `.refine` at `routes/threads.ts:54–59`
 *  and a body failing it is **400 `bad_request`** (`routes/threads.ts:252`).
 *  `{}` is therefore a legal shape of this type and an illegal request.
 *
 *  Caps, enforced by the schema: `text` ≤ 4000 chars *after trim*
 *  (`MAX_MESSAGE_LEN`, `routes/threads.ts:44`); at most 10 attachment ids
 *  (`MAX_ATTACHMENTS_PER_MESSAGE`, `:45`). Order in `attachment_media_ids` is
 *  meaningful: it is the emitted order of `MessageWire.attachments` and it
 *  picks the thread-preview line for an attachment-only send
 *  (`routes/threads.ts:212–232`, `:239–245`).
 *
 *  Each id must be a live `media_assets` row owned by the sender with
 *  `purpose: 'message-attachment'`. Missing or cross-owner ⇒ **404
 *  `not_found`** (existence never leaks); wrong purpose ⇒ **422
 *  `invalid_payload`** (`routes/threads.ts:223–228`).
 *
 *  The object is `.strict()`: an unknown key is rejected, not ignored.
 *  Server-side normalization is NOT part of what a client sends — `text` is
 *  trimmed and an attachment-only message is stored as `text: ''`
 *  (`routes/threads.ts:256–259`), which is why `MessageWire.text` is a
 *  required `string` while this key is optional.
 *
 *  This grammar is **deliberately different** from the staff reply grammar
 *  below; both are transcribed as they run (§14.1). See
 *  `BUSINESS-LOGIC/DISCREPANCIES.md:814` (NOTE-29). */
export interface PostThreadsMessagesRequest {
  text?: string;
  attachment_media_ids?: string[];
}

/** `POST /staff/threads/:id/messages` request body — the **staff** reply
 *  grammar. Promoted 1.13.0 from `routes/staffThreads.ts:33–35`
 *  (`messageBodySchema`); digest messaging/S, same item.
 *
 *  **Deliberately NOT the owner grammar above.** `text` is required and
 *  non-empty after trim (`.min(1)`), and a staff reply carries **no
 *  attachments**: the object is `.strict()`, so `attachment_media_ids` on this
 *  body is rejected. Staff attachments are approved-but-unbuilt (digest
 *  messaging design/L; `BUSINESS-LOGIC/DISCREPANCIES.md:814` NOTE-29) and this
 *  type pins the absence rather than pre-declaring the feature.
 *
 *  Cap: ≤ 4000 chars after trim (`MAX_MESSAGE_LEN`,
 *  `routes/staffThreads.ts:30`) — the same bound the owner send uses. Mobile's
 *  composer caps its input at 2000 (ledger NOTE-27, `DISCREPANCIES.md:800`);
 *  that is a client choice, not this contract.
 *
 *  **Status asymmetry — pinned, not repaired.** A body that fails THIS schema
 *  is **422 `invalid_payload`** (`routes/staffThreads.ts:158`), while the same
 *  class of failure on the owner send is **400 `bad_request`**. Both are
 *  test-pinned on the identical payload `{ text: '   ' }`
 *  (`test/contracts/staff-threads.test.ts:228` → 422;
 *  `test/contracts/threads.test.ts:244` → 400).
 *  `BUSINESS-LOGIC/api-conventions.md` R6 @ `:43` says request validation is
 *  400 `bad_request` and reserves `invalid_payload` for semantically-unusable
 *  payloads, so the staff route diverges from the documented convention.
 *  Changing the status is a behavior change wearing a doc change's clothes
 *  (§14.1) — recorded here and filed as STOP-1. */
export interface PostStaffThreadsMessagesRequest {
  text: string;
}

// <<< domain:messaging ========================================================

// >>> domain:notifications ====================================================

// --- (a) domain-local enums -------------------------------------------------

/**
 * Announcement categories — the home-screen card taxonomy. Promoted 1.13.0 from
 * `lib/announcementWire.ts:24` (digest notifications/M: "promote the announcements shapes
 * into wire.ts"). A hand-maintained mirror of the `announcement_category` pgEnum
 * (`schema.sql:150`; `db/schema/schema.ts:5`), pinned by `conformance.ts`.
 *
 * The pin is not decoration here: at its old home this type was DERIVED from
 * `announcementCategory.enumValues` and so could not drift. wire.ts is dependency-free, so
 * promotion trades that derivation for a literal mirror — the `Equal<…>` assert is what
 * replaces it. Member order mirrors the pgEnum declaration order.
 *
 * `urgent` is load-bearing on the owner app: those rows float to the top of the list and
 * tapping one opens the closure modal instead of the detail screen
 * (BUSINESS-LOGIC/notifications-events.md:93 R34).
 */
export type AnnouncementCategory = 'urgent' | 'team' | 'class' | 'event' | 'promo' | 'report';

/**
 * The CTA target discriminator on an announcement card. Promoted 1.13.0 from
 * `lib/announcementWire.ts:27` (digest notifications/M).
 *
 * NO pgEnum backs this one: `announcements.cta_kind` is a `text` column guarded by the
 * `announcements_cta_kind_check` CHECK (`schema.sql:1758`; `db/schema/schema.ts:1448,1461`),
 * so `conformance.ts` has nothing to pin it to (§5.1.1) and §5.2 mints no value tuple for it
 * (nothing iterates it). This union and that CHECK are hand-kept in step — a kind added to
 * the DDL is invisible to `tsc`. Filed, not fixed: converting the column to a pgEnum is DDL,
 * out of scope for this phase (§14.3).
 *
 * The owner app re-validates every arm at its wire boundary (`enroll` target must be a known
 * group-class key, `route` target must be on a one-entry allowlist, `external` must be
 * `https://`) and renders the card WITHOUT a button when that fails — an unknown or off-list
 * target degrades, it never dispatches (BUSINESS-LOGIC/notifications-events.md:92 R33).
 */
export type AnnouncementCtaKind = 'enroll' | 'route' | 'external';

/**
 * The device families that can hold an Expo push token. Promoted 1.13.0 out of the local
 * `DeviceTokenWire` at `routes/device-tokens.ts:41,45` (digest notifications/S).
 *
 * No pgEnum here either: `device_tokens.platform` is `text NOT NULL CHECK (platform IN
 * ('ios','android'))` (`schema.sql:1774`; `db/schema/schema.ts:1470,1481`) — no conformance
 * pin is possible. Two other hand-kept copies exist and this promotion deliberately
 * collapses neither: the request validator `z.enum(['ios', 'android'])`
 * (`routes/device-tokens.ts:52`) and the row-side `DevicePlatform`
 * (`db/repositories/deviceTokensRepository.ts:26`), which §6 leaves in place as a DB-side
 * type — the same "private redeclarations are left alone" call §5.3 made for `BookingMode`.
 * Convergence needs DDL or a tuple §5.2 does not mint; filed as phase-3 debt.
 */
export type DevicePlatform = 'ios' | 'android';

// --- (b) response wires -----------------------------------------------------

/**
 * A row in the owner notifications inbox (`GET /notifications`). snake_case keys
 * are the literal JSON on the wire. `is_read` is DERIVED from the DB's
 * `read_at IS NOT NULL` — the wire carries the boolean, not the timestamp. The
 * optional `?` keys (`deep_link_path`, `dog_ids`, `sender_staff_id`) are OMITTED
 * when null/empty, never emitted as null.
 */
export interface NotificationWire {
  id: string;
  type: NotificationType;
  title: string;
  body: string;
  received_at: string;
  is_read: boolean;
  deep_link_path?: string;
  dog_ids?: string[];
  sender_staff_id?: string;
}

/** `GET /notifications` response. `next_cursor` (a base64url keyset envelope) is
 *  omitted on the last page. */
export interface NotificationListResponse {
  items: NotificationWire[];
  next_cursor?: string;
}

/** `GET /notifications/unread-count` response. */
export interface UnreadCountResponse {
  unread_count: number;
}

/**
 * The `data` payload on an Expo push for a notification. snake_case is pinned
 * HERE so the push key can never drift from the wire the FE reads on tap.
 * `deep_link_path` is omitted when the notification has no target.
 */
export interface NotificationPushData {
  type: NotificationType;
  deep_link_path?: string;
  notification_id: string;
}

/**
 * A structured deep-link reference a producer stamps on a notification instead
 * of hand-writing a path. `deepLinkToPath` is the single grammar that turns it
 * into the owner-app route; `params` carries kind-specific extras (e.g. `report`
 * needs `dogId`). `credits` alone has no `id` (5.0.0-lg4.2).
 */
export type NotificationDeepLink =
  | {
      kind: Exclude<NotificationDeepLinkKind, 'credits'>;
      id: string;
      params?: Record<string, string>;
    }
  | { kind: 'credits'; params?: Record<string, string> };

/**
 * The optional call-to-action on an announcement card. Promoted 1.13.0 from
 * `lib/announcementWire.ts:29` (digest notifications/M).
 *
 * The three fields travel as a unit because the DB enforces all-or-none
 * (`announcements_cta_all_or_none` CHECK, `schema.sql:1760-1762`) and the shaper emits the
 * nested object only when every column is present — a partial CTA is not a legal emission
 * (BUSINESS-LOGIC/notifications-events.md:91 R32; `lib/announcementWire.ts:77-80`).
 *
 * `target` is UNVALIDATED on the wire: its meaning depends on `kind` (a group-class key, an
 * in-app route, or an https URL) and the client is the trust boundary that checks it (R33 @
 * BUSINESS-LOGIC/notifications-events.md:92).
 */
export interface AnnouncementCtaWire {
  label: string;
  kind: AnnouncementCtaKind;
  target: string;
}

/**
 * A `GET /announcements` row — the school-wide (optionally city-targeted) home-screen card.
 * Promoted 1.13.0 from `lib/announcementWire.ts:35` (digest notifications/M). The endpoint
 * returns a bare `AnnouncementWire[]`, not an envelope.
 *
 * Not owner-scoped: owners and staff receive the identical list — live rows only
 * (`expired_at IS NULL`), ordered `is_pinned DESC, published_at DESC, id ASC`
 * (BUSINESS-LOGIC/notifications-events.md:89 R30). Reads are cached 300 s and the documented
 * invalidator does not exist (there is no announcement write route anywhere in the backend),
 * so content can be up to five minutes stale (R31 @ :90).
 *
 * Omit-on-null: `body`, `deep_link_path`, and `cta` are OMITTED when absent or empty, never
 * emitted as `null`. (Mobile's mock JSON carries explicit `null` for `deep_link_path` where
 * the API omits — that divergence is the client's to absorb, per §10's `NullableWire`.)
 *
 * Deliberately NOT emitted, transcribed from the source's own note: `target_location` (it
 * drives the `?location=` filter server-side), `is_pinned` (it drives the sort; clients
 * render in returned order) and `created_at`/`expired_at` (lifecycle metadata).
 */
export interface AnnouncementWire {
  id: string;
  category: AnnouncementCategory;
  title: string;
  body?: string;
  published_at: string;
  deep_link_path?: string;
  cta?: AnnouncementCtaWire;
}

/**
 * `POST /device-tokens` 201 response — the owner's registered Expo push token. Promoted
 * 1.13.0 from `routes/device-tokens.ts:41` (digest notifications/S).
 *
 * Two deliberate column→wire renames ride this shape: `token` ↔ column `expo_push_token`,
 * and `registered_at` ↔ column `created_at` (`routes/device-tokens.ts:137-145`).
 * `registered_at` is the ORIGINAL registration instant — re-registering a live token upserts
 * the existing row and does NOT move it (pinned by `test/contracts/device-tokens.test.ts:99`,
 * "re-register (different key, same token) upserts to ONE live row").
 *
 * Owner-only surface: staff principals get 403 on both verbs and no staff device-token
 * surface exists (BUSINESS-LOGIC/notifications-events.md:77 R24). DELETE soft-expires; a
 * revoked token can be re-registered without a UNIQUE collision because the index is partial
 * on `expired_at IS NULL` (R25 @ :78). Nothing sweeps orphaned tokens today — a signed-out
 * device can keep receiving the prior owner's pushes (DISCREPANCIES.md NOTE-38 @ :867).
 */
export interface DeviceTokenWire {
  id: string;
  owner_id: string;
  token: string;
  platform: DevicePlatform;
  registered_at: string;
}

// --- (c) request bodies + query shapes --------------------------------------

/**
 * `GET /notifications` query string — the request half of the inbox feed (digest
 * notifications/S: "contract the notification list request half"). Transcribed from
 * `routes/notifications.ts:43-46`.
 *
 * `cursor` is OPAQUE. It is a base64url-encoded JSON keyset envelope
 * (`{"r":<received_at ISO>,"i":<id UUID>}`) minted by the server
 * (`routes/notifications.ts:223-226`), and a client's only correct use is to echo
 * `NotificationListResponse.next_cursor` back VERBATIM — never to construct, parse, or
 * mutate one. A malformed cursor is a hard `400 bad_request`, deliberately not a silent
 * page-1 fallback, because a silent fallback would mask client bugs as ghost pagination
 * (BUSINESS-LOGIC/notifications-events.md:47 R3; `routes/notifications.ts:228-253`).
 *
 * `limit` defaults to 50, minimum 1, maximum 200; out-of-range values are `400 bad_request`,
 * NOT clamped. It is typed `number` because that is what a caller means, but the validator is
 * `z.coerce.number()` — over HTTP the value arrives as a string, and `?limit=3` is what every
 * contract test actually sends (`test/contracts/notifications.test.ts:47`). Both forms parse;
 * nothing here narrows that.
 *
 * Feed ordering is `received_at DESC, id DESC` and the page is fetched as `limit + 1` to
 * detect the next page without a COUNT (`routes/notifications.ts:84-100`).
 */
export interface GetNotificationsQuery {
  cursor?: string;
  limit?: number;
}

/**
 * `POST /device-tokens` request body (digest notifications/S). Transcribed from
 * `routes/device-tokens.ts:49-54` and pinned to that Zod schema by
 * `PostDeviceTokensBodyConformance` in the route file (§5.1.3).
 *
 * The schema is `.strict()`: an unknown key is `400 bad_request`, not ignored. `token` is
 * 1–512 characters — an Expo token is ~40-50 (`ExponentPushToken[…]`), so the cap is a
 * hostile-input guard and NOT a format check; no `ExponentPushToken[` prefix is enforced
 * server-side, and this type does not pretend otherwise. Registration is an UPSERT by
 * `(owner_id, expo_push_token)` and additionally replay-guarded by the required
 * `Idempotency-Key` header (BUSINESS-LOGIC/notifications-events.md:77 R24).
 */
export interface PostDeviceTokensRequest {
  token: string;
  platform: DevicePlatform;
}

// --- (d) per-endpoint 422 aliases -------------------------------------------
//
// NONE — and that is an executed finding, not an assumption. No route, lib or repository in
// this domain constructs an `ApiError` with a `details` payload: the whole surface fails with
// bare envelopes — `bad_request` (invalid query, invalid cursor, invalid body, missing
// Idempotency-Key), `not_found` (notification / device token; missing and not-yours collapse
// for enumeration defense) and `forbidden` (staff on the device-token verbs). Verified by
// running `grep -n details` across the domain's five source files plus its three
// repositories: zero matches (command and output quoted in the lane patch's Evidence).
// §3.5's alias set — POST /bookings, /requests, /enrollments, /events/:id/rsvp — contains no
// notifications endpoint.

// --- (e) domain-owned pure helpers ------------------------------------------

/**
 * THE deep-link path grammar. Producers call this at emit time so the persisted
 * `deep_link_path` and the FE route table can never disagree. `report` requires
 * `params.dogId`; a missing one throws HERE — failing loud at emit time rather
 * than persisting a broken path. The inline `never` guard makes adding a kind to
 * `NotificationDeepLinkKind` without a case a compile error (this file is
 * dependency-free, so it can't import the shared `assertNever`).
 */
export function deepLinkToPath(link: NotificationDeepLink): string {
  switch (link.kind) {
    case 'booking':
      return `/bookings/${link.id}`;
    case 'report': {
      const dogId = link.params?.dogId;
      if (dogId === undefined || dogId === '') {
        throw new Error('deepLinkToPath: report link requires params.dogId');
      }
      return `/report-card/${dogId}?reportId=${link.id}`;
    }
    case 'thread':
      return `/chat/${link.id}`;
    case 'invoice': {
      // The SPECIFIC invoice (Allison 2026-07-27, decision 1): the owner app
      // opens it as a pop-up modal, so a paid invoice reads confirmed/paid — never
      // "Outstanding". `link.id` is the invoice id (producers pass it since Phase
      // 2), so it's load-bearing now, not a fixed route. Historical rows persist
      // the old query-less `/account/invoices`; the clients' parser keeps
      // accepting those (backward-compat rule) — only NEW emissions carry the id.
      //
      // Since 1.9.0 a payment notification also carries the FRAMING it promised
      // (`params.reason`), because the sheet it opens had no way to know which
      // push sent the owner there — Allison's 2026-07-31 payment-failed and
      // payment-due copy existed but no production host ever passed a reason, so
      // it rendered only under test. Invalid values throw at emit rather than
      // silently shipping a link the client will drop, matching the `report`
      // arm's fail-loud rule above. Omitted → byte-identical to the pre-1.9.0
      // path, so every historical row and every non-payment producer is untouched.
      const reason = link.params?.reason;
      if (reason === undefined) {
        return `/account/invoices?invoiceId=${link.id}`;
      }
      // Widen the tuple rather than narrowing `reason` — asserting it is a valid
      // member is exactly what this line exists to find out.
      if (!(INVOICE_DEEP_LINK_REASONS as readonly string[]).includes(reason)) {
        throw new Error(
          `deepLinkToPath: invoice link reason must be one of ${INVOICE_DEEP_LINK_REASONS.join(' | ')}, got ${reason}`,
        );
      }
      return `/account/invoices?invoiceId=${link.id}&reason=${reason}`;
    }
    case 'dog-profile':
      return `/dog-profile/${link.id}`;
    case 'dog-manage':
      return `/dog-manage/${link.id}`;
    // The owner's credits screen: credits are hers, not a dog's, so the arm has no
    // id (5.0.0-lg4.2; CRED-U10). A path stored before that keeps its dog-profile
    // route and its `?highlight=credits`; the clients' parser accepts both.
    case 'credits':
      return '/account/credits';
    case 'announcement':
      return `/announcement/${link.id}`;
    // The expiring card, flashed in the wallet list (`link.id` is the
    // payment_method id) — same "point at the row, not the page" rule as invoice
    // (Allison 2026-07-29).
    case 'payment-method':
      return `/payment-methods?highlight=${link.id}`;
    // A waitlist OFFER (`link.id` is the waitlist_entries id). Deliberately not
    // a booking link: when `waitlist-spot-open` fires nothing is booked yet —
    // the owner still has to accept, and payment happens on accept (Allison
    // 2026-07-30). Pointing at a booking that doesn't exist would 404.
    case 'waitlist':
      return `/waitlist/${link.id}`;
    default: {
      const unreachable: never = link;
      throw new Error(
        `deepLinkToPath: unhandled kind ${String((unreachable as NotificationDeepLink).kind)}`,
      );
    }
  }
}

// <<< domain:notifications ====================================================

// >>> domain:payments-invoices ================================================

// ---- (a) domain-local enums ------------------------------------------------

/**
 * `invoices.status`. Mirrors the `invoice_status` pgEnum (pinned in
 * `conformance.ts` since 1.13.0). Promoted 1.13.0 from
 * `db/repositories/invoicesRepository.ts:31` (digest payments-invoices/M, "move
 * the money surface into wire.ts … + pin the money enums"); it reaches the wire
 * through `StaffInvoiceWire.status`.
 *
 * Three members, and the two that are ABSENT are the contractful part: there is
 * no 'overdue' and no 'refunded' invoice state. An unpaid invoice stays 'open',
 * and a refund is a `charges`-side fact that never changes an invoice's status.
 * The staff portal's hand vocabulary (`Open|Paid|Overdue|Refunded|Void`)
 * disagrees on both; that is KNOWN drift, not news
 * (BUSINESS-LOGIC/DISCREPANCIES.md DRIFT-17, DRIFT-59), it resolves in the
 * portal wave, and this union is the runtime truth it resolves toward.
 *
 * `InvoicePayWire.invoice_status` below spells the same three members inline.
 * The duplication is deliberate this bump: that inline union is a 1.12.0
 * declaration and §2.2 freezes existing declaration text byte-identical, so it
 * is NOT re-aliased here. Same set, two spellings, one of them frozen.
 */
export type InvoiceStatus = 'open' | 'paid' | 'void';

/**
 * What a `charges` / `invoices` row is FOR. Mirrors the `charge_purpose` pgEnum
 * (pinned in `conformance.ts` since 1.13.0). Promoted 1.13.0 from
 * `db/repositories/chargesRepository.ts:106` (digest payments-invoices/M); it
 * reaches the wire through `StaffInvoiceWire.purpose`.
 *
 * Only set equality is contractual — the conformance pin is a bidirectional
 * `Equal`, not an order check.
 *
 * Not to be confused with `LedgerEntryWire.kind`, the OWNER-facing collapse of
 * this same vocabulary: `package → 'credit-pack'`, and BOTH `board-train` and
 * `group-class` → `'session'` (`db/repositories/ledgerRepository.ts:86-98`). Staff
 * read purposes; owners read kinds. The two are not interchangeable and the
 * mapping is lossy in that one direction.
 *
 * 5.0.0-lg4.1 (M4.02; CRED-U29, DECISIONS 151(h)): `'membership'` and `'payg'`
 * left with the rebuild, so no row carries either.
 */
export type ChargePurpose = 'package' | 'board-train' | 'group-class';

// ---- (b) response wires ----------------------------------------------------

/**
 * `POST /invoices/:id/pay` response. Declared here since 1.7.0; it previously
 * lived in `routes/invoices.ts`, which left the money endpoint entirely outside
 * the versioned contract with nothing for the clients' `check:contracts` to
 * guard. Shape unchanged by the move.
 */
export interface InvoicePayWire {
  charge_id: string;
  charge_status: ChargeStatus;
  stripe_payment_intent_id: string;
  /**
   * Stripe's client secret for the PaymentIntent. **Do not treat this as a
   * completable intent.** No client-side 3DS completion flow exists anywhere in
   * this system, so there is nothing a client can do with it; it is returned
   * for logging and support lookup only.
   *
   * Since 4.0.0-lg3.2 this route rides the order engine, and 1.7.1's rule
   * (cancel a non-succeeded intent before returning) no longer applies to it.
   * The one non-succeeded 201 is a charge Stripe still reports `processing`:
   * that intent is LIVE and the webhook or the sweeper settles it. A final
   * decline is 402 `payment_failed`, which carries no secret; the sweeper then
   * cancels its intent on a later tick. A route not on the engine keeps the rule.
   *
   * When a 3DS-completion design lands it must revisit the cancel rule for
   * on-session routes -- completion needs a LIVE intent -- and re-document this
   * field in the same change.
   */
  client_secret: string | null;
  invoice_status: 'open' | 'paid' | 'void';
  /**
   * True when this charge succeeded at Stripe but LOST the settle race against
   * another settle of the same invoice -- the invoice is already
   * `paid` by that path, so this duplicate charge is being refunded post-commit
   * (a 'pending' refund row was written in-tx; Stripe + webhook reconcile it).
   * The owner's card nets exactly one charge. Honest signal so the client
   * never renders "payment complete" for money that's on its way back. False
   * on the clean win and on the 3DS / requires_action path.
   */
  charge_refunded: boolean;
  /**
   * Why this confirm stopped short of `succeeded`, at the domain level.
   * Present IFF the response reports a non-succeeded confirm; omitted on every
   * settled arm, and absent on stored idempotency replays of pre-1.8.0
   * responses -- derive pessimistically when missing.
   *
   * The 1.8.0 gloss pinned presence to `charge_status: 'requires_payment'`,
   * which was false: a `canceled` raw status maps to `charge_status: 'failed'`
   * (`stripe.ts` status collapse) and still carries a blocker. Corrected in
   * 1.9.0 -- branch on the blocker's presence, never on a status pairing.
   *
   * Since 1.9.0 this is the taxonomy for BOTH Stripe behaviors, not one of
   * them. A card error THROWN by an off-session confirm is normalized at the
   * Stripe seam into the same non-succeeded result the returning fork
   * produces, so whichever way Stripe reports a decline, the owner reads the
   * same specific sentence. That is what makes `[1.8.0]`'s "one taxonomy
   * across both channels" true rather than aspirational.
   *
   * Since 4.0.0-lg3.2 only `'processing'` reaches this field. Every other
   * blocker arrives on the 402's `PaymentFailedDetails.charge_blocker`, the
   * same vocabulary.
   *
   * This is NOT an invitation to complete authentication: a card that needs it
   * cannot pay off-session (question 61). The field exists for (a) honest,
   * specific copy today and (b) the future 3DS-completion design, which needs
   * this signal on a LIVE intent -- the field survives that change unmodified.
   */
  charge_blocker?: ChargeBlocker;
}

/**
 * `POST /credit-packages/:key/purchase` 201 response. Declared here since 1.8.0;
 * it previously lived in `routes/creditPackages.ts`, which left a second money
 * endpoint outside the versioned contract with nothing for the clients'
 * `check:contracts` to guard -- the same condition that let the invoice card
 * picker drift in the first place.
 *
 * Since 5.0.0-lg4.2 the route rides the order engine (design §1.1:1008-1011,
 * §2.4:3008-3011; CRED-U10) and a 201 has two arms. `charge_status: 'succeeded'`
 * with the credits granted, or a purchase Stripe still reports `processing` after
 * the tries: `charge_status: 'requires_payment'`, `credits_granted: 0` and
 * `charge_blocker: 'processing'`, the field the app branches on ("Payment
 * processing. Your credits are added when it clears."). The intent is LIVE and
 * the webhook or the sweeper settles it. A decline is no longer a 201: it is 402
 * `payment_failed` (`PostCreditPackagesPurchaseRequest`).
 */
export interface CreditPurchaseWire {
  charge_id: string;
  charge_status: ChargeStatus;
  stripe_payment_intent_id: string;
  /** Same caveat as `InvoicePayWire.client_secret`: for logging and support
   *  lookup only, never a completable intent. */
  client_secret: string | null;
  /** `credits × count` on `'succeeded'`. Zero on the processing arm -- the grant
   *  is gated on `succeeded`. */
  credits_granted: number;
  /** `'processing'` on the processing arm, omitted on `'succeeded'`, and absent
   *  on stored idempotency replays of older responses. See
   *  `InvoicePayWire.charge_blocker`. Same union, same pessimistic-when-absent
   *  rule. */
  charge_blocker?: ChargeBlocker;
}

/**
 * `GET /invoices` response row — the owner's billing ledger. Promoted 1.13.0
 * from `lib/ledgerWire.ts:16-68` (digest payments-invoices/M "move the money
 * surface into wire.ts"); DATA-CONTRACT §A Amendment 2026-05-30. `ledgerWire.ts`
 * keeps `toLedgerEntryWire` and re-exports this type, so no consumer moves.
 *
 * One entry per completed/refunded charge PLUS one per open invoice, newest
 * first. R32 (BUSINESS-LOGIC/payments-invoices.md:106): only `succeeded` and
 * `refunded` charges appear — `requires_payment` and `failed` charges are
 * hidden — and a credit-funded session is NOT a line, because the money event
 * was the package purchase that funded it.
 *
 * **Omit-on-null throughout**: every optional field below is ABSENT when
 * inapplicable, never `null`. Only sessions carry a category; only credit-packs
 * carry a mode.
 */
export interface LedgerEntryWire {
  id: string;
  /**
   * The owner-facing collapse of `ChargePurpose` (see that type): `package`
   * becomes 'credit-pack', `board-train` and `group-class` both become
   * 'session'. Lossy by design — owners read money by what it bought, staff by
   * what it was booked against.
   */
  kind: 'session' | 'credit-pack';
  /**
   * Ledger-entry state, which is NOT `InvoiceStatus` and must not be unified
   * with it. Three members, and the divergence is real in both directions:
   * 'refunded' exists here (it is a charge-side fact this surface reports) and
   * does not exist as an invoice status; 'void' exists as an invoice status and
   * never appears here (a voided invoice is not a money event, so it is not a
   * ledger line). Only 'paid' and 'open' are common to both.
   *
   * Mobile carries a third vocabulary of its own; that reconciles in mobile's
   * domain layer, not on the wire (design §7, payments row).
   */
  status: 'paid' | 'open' | 'refunded';
  amount_cents: number;
  date: string;
  dog_id?: string;
  category?: ServiceCategory;
  /**
   * Credit-pack entries only. Re-aliased 1.13.0 from the inline
   * `'school' | 'daycare'` to the shared `BookingMode` (`wire.ts` §2, skeleton
   * §5.3): IDENTICAL member set, so this is a rename of the spelling and not a
   * retype — nothing widens, nothing narrows. Proof: `BookingMode` is pinned
   * `Equal` to the `booking_mode` pgEnum `['school','daycare']` at
   * `conformance.ts:82`, and the promoted-from declaration spelled exactly
   * those two members (`lib/ledgerWire.ts:24`).
   */
  mode?: BookingMode;
  /**
   * The invoice a paid entry settled (charge-sourced entries only). Payment
   * notifications deep-link by invoice id — the client matches a ledger row
   * on `id` OR this.
   */
  invoice_id?: string;
  /**
   * Open invoices only: how the owner said they'll settle it. 'in-person'
   * rows render non-payable in the app (card-paying a flagged invoice would
   * double-bill the drop-off).
   */
  payment_expected?: 'card' | 'in-person';
  /**
   * Paid entries only: how the entry settled. 'card' for every settled charge
   * today; 'cash'/'check' reserved for a future staff mark-paid flow (never
   * emitted yet). Omitted on open/refunded entries.
   */
  settled_method?: 'card' | 'cash' | 'check';
  /**
   * Paid entries only: the settling card — present ONLY when the paid charge
   * settled an invoice with a live payment_method. A pack's settle writes the
   * card it charged onto its paid invoice (§2.7:3875; 5.0.0-lg4.2), so a pack
   * line carries it. Omitted on non-paid entries.
   */
  settled_card?: { brand: string; last4: string };
  /**
   * Paid entries only: the precise settle timestamp (full ISO, with time).
   * Omitted on open/refunded entries.
   */
  settled_at?: string;
  /**
   * Group-class entries only: the class name off the row's own cohort
   * ("Manners 1"). Added 2026-08-24 (Q16,
   * `designs/enrollment-followup-copy-flow.md` §3.3) together with `dog_id`
   * finally being emitted for these rows — the two facts the client composes
   * "Manners 1 — Waffles · $120" from. Omitted for every other kind, and for a
   * legacy group-class row carrying no cohort, which therefore keeps rendering
   * the generic label a pre-Q16 client renders.
   *
   * Deliberately a FACT, not a display string: every ledger line in this
   * system is composed client-side, and keeping it that way is what lets the
   * copy change without a backend deploy.
   */
  group_class_name?: string;
  /**
   * The order this entry's charge belongs to (4.0.0-lg3.2, M3.02; PAY-U04).
   * Charge-sourced entries only, and only a charge an order made: omitted on an
   * open invoice and on a charge from before the engine.
   */
  order_id?: string;
}

/**
 * `GET /payment-methods` response row (also the body of `POST
 * /payment-methods/confirm` and `PATCH /payment-methods/:id`, both of which
 * return the owner's FULL card list so the client replaces its cache with
 * canonical post-mutation state in one round-trip). Promoted 1.13.0 from
 * `routes/paymentMethods.ts:41-49` (digest payments-invoices/M "cards"). The
 * file's own comment deferred promotion until "a third call site appears" — the
 * portal is that third site (design §6).
 *
 * Owner-scoped through `payment_methods.owner_id`. A STAFF principal gets `[]`
 * rather than a 403 (BUSINESS-LOGIC/payments-invoices.md:170) — staff have no
 * cards-of-record on this surface, and the mutations are owner-only (403).
 * Staff read a family's cards through `GET /staff/owners/:id/payment-methods`
 * instead (2.0.0, STAFF-U13): the same row, the same live set, owner and
 * manager only — see `GetStaffOwnersPaymentMethodsResponse`.
 *
 * Cards are SOFT-expired on delete, and this list is the live set only.
 * `brand` and `last4` are Stripe's display strings, never client-supplied:
 * they come from `paymentMethods.retrieve` at materialization time (R20,
 * BUSINESS-LOGIC/payments-invoices.md:82). `brand` is deliberately a `string`
 * and not a union — Stripe may add a brand at any time and this surface must
 * not start rejecting one.
 */
export interface PaymentMethodWire {
  id: string;
  brand: string;
  last4: string;
  exp_month: number;
  exp_year: number;
  cardholder_name: string;
  /** Exactly one live card per owner may be true (partial unique
   *  `payment_methods_one_default`); the first card added becomes the default
   *  automatically (R20). */
  is_default: boolean;
}

/**
 * `POST /payment-methods/setup-intent` response (201). Named + promoted 1.13.0
 * per §4.1 from the file-private `SetupIntentResponseBody`
 * (`routes/paymentMethods.ts:60-63`, digest payments-invoices/M "cards …
 * setup-intent shapes").
 *
 * The owner's Stripe customer is lazily provisioned on the first call. The
 * client confirms this SetupIntent with the Stripe SDK and then POSTs its id to
 * `/payment-methods/confirm`; the `setup_intent.succeeded` webhook is the async
 * backstop and both converge on the same idempotent materialization, so a
 * confirm racing a webhook collapses to one card (R20).
 *
 * Unlike `InvoicePayWire.client_secret`, THIS `client_secret` is live and is
 * meant to be completed client-side — the 1.7.1 cancel rule is about
 * PaymentIntents, not SetupIntents.
 */
export interface PostPaymentMethodsSetupIntentResponse {
  setup_intent_id: string;
  client_secret: string;
}

// ---- (b) response wires (continued): staff billing reads (2.0.0) ----------
//
// New 2.0.0 (plan unit P03, slice S03, LG1 step 3 of 3; design §1.1:710-717,
// §2.10:4682-4697). Four `[staff]` reads of one family's billing, split by
// role (04- item 128, `04-money-124-167.md:9`: "Trainers CAN open invoices.
// Trainers may NOT see payment history or cards on file"):
//   GET /staff/owners/:id/invoices         → GetStaffOwnersInvoicesResponse   any role
//   GET /staff/invoices/:id                → StaffInvoiceWire                 any role
//   GET /staff/owners/:id/payments         → GetStaffOwnersPaymentsResponse   owner, manager
//   GET /staff/owners/:id/payment-methods  → GetStaffOwnersPaymentMethodsResponse  owner, manager
// Every one: an owner (family) principal is 403 `forbidden`; a malformed
// `:id` is 400 `bad_request`; an `:id` naming no row is 404 `not_found`. On
// the two owner-and-manager routes a trainer is 403 `forbidden` (no
// `details`) from the role guard, before `:id` is parsed or looked up, so the
// 403 says nothing about the family. An owner `:id`
// names any `owners` row, an expired one included: invoices, charges and
// refunds are retained financial records.

/**
 * One payment toward an invoice, as the *Refund* action needs it — an entry of
 * `StaffInvoiceWire.payments`, and the base of `StaffPaymentWire`. A payment is
 * a `charges` row that took money: status `'succeeded'` or `'refunded'`.
 */
export interface StaffInvoicePaymentWire {
  /** `charges.id` — the id design 6.0.0's `POST /staff/refunds {payment_id}`
   *  will take. */
  payment_id: string;
  /** What the charge took: its `amount_cents`. Never reduced by a refund. */
  paid_cents: number;
  /**
   * The refund cap. ONE definition, the money page's (design §2.10:4688-4693,
   * §1.1:713-716): `paid_cents` minus every refund on this charge whose money
   * left or is leaving — status `pending`, `succeeded` or `unroutable`, or
   * `resolved-external` with outcome `returned` — never a `failed` refund and
   * never a hand-back closed `withdrawn`, which moved no money. Nothing is
   * subtracted for days still booked: no charge pays for a day (R1). Floored
   * at 0. A client never recomputes it.
   *
   * On today's schema: `withdrawn` and the outcome `returned` have no column
   * yet — they are values of `refunds.resolved_outcome`, which design 6.0.0's
   * M5.10 adds — and `refund_status` carries neither. Until then every
   * `resolved-external` row means the money WAS returned outside our Stripe
   * machinery, attested by a named human (`schema.sql:209-221`). So today the
   * cap is `paid_cents` minus every refund whose status is not `failed`: the
   * arithmetic of `refundsRepository.sumNonFailedForCharge`. When M5.10 lands,
   * a `withdrawn` row stops counting too; this field's meaning and shape do
   * not change.
   */
  refundable_cents: number;
}

/**
 * `GET /staff/owners/:id/invoices` row and `GET /staff/invoices/:id` body — an
 * invoice as staff read it, on TODAY's invoice shape (STAFF-U13, severed from
 * PAY-U20: "staff read today's invoice shape", design.md:4493-4494). New 2.0.0.
 *
 * Any staff role reads it. Every role gets the invoice's own facts; only a
 * caller holding `capabilities.refund_money` gets `payments` (see the field).
 * Never a card's brand or last4, never the card the invoice is bound to
 * (`invoices.payment_method_id`), never a charge method and never refund rows
 * (STAFF-13; §1.1:716, §2.10:4687).
 *
 * **No `number` and no `lines`.** §1.1:711 names both, but they are PAY-U20's
 * multi-line invoice, which v1 does not build (design.md:6944: "v1 raises
 * one-line invoices only"), and no step of design §4 gives an invoice a
 * number column. Today's invoice IS its one line: `purpose`, `dog_id` and
 * `amount_cents` say what was billed, and `id` is its reference (a client may
 * shorten it for display). Design 6.1.0 adds the custom invoice's `kind?`,
 * `description?` and `raised_by?` here, additively; a stored number or lines
 * would arrive the same way, with a design that stores them.
 *
 * `GET /staff/owners/:id/invoices`: every invoice of that owner, any status,
 * newest first (`issued_at` DESC, then `id`); `[]` for none. Omit-on-null
 * throughout (the file-wide rule) except `payments`, whose rule is its own.
 */
export interface StaffInvoiceWire {
  id: string;
  owner_id: string;
  /** `invoices.status`. A refund never changes it (see `InvoiceStatus`). */
  status: InvoiceStatus;
  /** What the invoice bills (`invoices.purpose`). Staff read purposes; owners
   *  read `LedgerEntryWire.kind`. */
  purpose: ChargePurpose;
  /** The amount billed. */
  amount_cents: number;
  /** The amount paid: `amount_cents` once `status` is `'paid'` (an invoice is
   *  settled whole today), else 0. Never reduced by a refund: what came back
   *  is a family's refund history, which a trainer may not see
   *  (§2.10:4684-4687). */
  paid_cents: number;
  /** `invoices.dog_id`, the dog billed for; omitted when none. */
  dog_id?: string;
  /** ISO-8601: when the invoice was raised (`invoices.issued_at`). */
  issued_at: string;
  /** ISO-8601: when it falls due (`invoices.due_at`). */
  due_at: string;
  /** ISO-8601: `invoices.paid_at`; set on every `'paid'` invoice (the table's
   *  CHECK), omitted when null. */
  paid_at?: string;
  /**
   * The payments toward this invoice: today the one charge that settled it
   * (`invoices.paid_charge_id`), so at most one entry, and `[]` when no charge
   * settled it (an open or a void invoice). `charges` has no invoice column,
   * so no other charge is attributed to an invoice.
   *
   * NON-OMIT EXCEPTION, decided by the caller: PRESENT (`[]` included) exactly
   * when the caller holds `capabilities.refund_money`, computed on each call
   * by the same rule as `GET /me`; ABSENT otherwise. The field exists for the
   * *Refund* action, and paid minus refundable is a family's refund history,
   * which Allison withheld from trainers (§1.1:711-713, §2.10:4683-4687). So
   * the seeded trainer's read carries no `payments` and no
   * `refundable_cents`, and the seeded manager's carries `payments`. Read
   * absence as "not yours to see", never as "no payments".
   */
  payments?: StaffInvoicePaymentWire[];
}

/**
 * One refund on a payment — an entry of `StaffPaymentWire.refunds`. New 2.0.0
 * (STAFF-U13). Not design 6.0.0's `RefundWire` (the refund verbs' row, with
 * its issuer, instrument and resolution), which is a later, wider shape.
 */
export interface StaffPaymentRefundWire {
  id: string;
  amount_cents: number;
  /** The row's state. Whether it counts against the payment's
   *  `refundable_cents` is that field's rule, never the client's. */
  status: RefundStatus;
  /** `refunds.reason`, as stored; omitted when null. */
  reason?: string;
  /** ISO-8601: when the refund row was written. */
  created_at: string;
}

/**
 * `GET /staff/owners/:id/payments` row — one payment of a family's payment
 * history, with the refunds made on it (STAFF-U13; §1.1:716-717). New 2.0.0.
 * Owner and manager only (`requireStaffRole('owner', 'manager')`, the rule
 * `capabilities.open_payment_history` mirrors); a trainer is 403 `forbidden`.
 *
 * The rows are the owner's charges that took money — status `'succeeded'` or
 * `'refunded'`, the set the owner's own ledger shows (R32). A charge that
 * failed, or is still `requires_payment`, moved no money and is not listed.
 * Newest first (`created_at` DESC, then `id`); `[]` for none. No brand or
 * last4: the card is `/payment-methods`' (STAFF-13). Design 6.0.0 adds
 * `stripe_payment_intent_id?` and 6.1.0 adds `method`, `recorded_by?` and
 * `note?` to this row, additively (design.md:1119-1121, :1165-1167).
 */
export interface StaffPaymentWire extends StaffInvoicePaymentWire {
  status: Extract<ChargeStatus, 'succeeded' | 'refunded'>;
  purpose: ChargePurpose;
  /** ISO-8601: when the charge row was written. */
  created_at: string;
  /** `charges.dog_id`; omitted when none. */
  dog_id?: string;
  /** The invoice this charge settled (the invoice whose `paid_charge_id` is
   *  this charge); omitted for a charge that settled none (a pack bought
   *  outright, a class paid at enrolment). */
  invoice_id?: string;
  /** Every refund on this charge, any status, oldest first (`created_at`
   *  ASC, then `id`); `[]` for none. */
  refunds: StaffPaymentRefundWire[];
}

/** `GET /staff/owners/:id/invoices` response (200), any staff role. */
export type GetStaffOwnersInvoicesResponse = StaffInvoiceWire[];

// `GET /staff/invoices/:id` (200) returns one `StaffInvoiceWire` and has no
// alias: the rulebook's name for it, `GetStaffInvoicesResponse`, is the name
// of the list design 6.1.0 builds at `/staff/invoices` (7.1.0 here). No route
// answers that path from 5.0.0-lg4.1 until then: `?parked` is gone.

/** `GET /staff/owners/:id/payments` response (200), owner and manager. */
export type GetStaffOwnersPaymentsResponse = StaffPaymentWire[];

/** `GET /staff/owners/:id/payment-methods` response (200), owner and manager —
 *  the family's cards on file: `PaymentMethodWire` exactly as the owner's own
 *  `GET /payment-methods` serves it (brand, last4, expiry, cardholder name,
 *  default flag), the live set only, in the same order (the default card
 *  first, then oldest first). */
export type GetStaffOwnersPaymentMethodsResponse = PaymentMethodWire[];

// ---- (b) response wires (continued): the order engine (4.0.0-lg3.2) --------
//
// New 4.0.0-lg3.2 (plan unit P15, slice S20; design §1.1:857-899, §2.7:3811-4030;
// PAY-U04, PAY-U05, PAY-U07). An order is one Confirm: one `orders` row (M3.02)
// holding at most one `charges` row. Automatic capture, two transactions with
// Stripe between them: no capture-related shape exists. `POST /invoices/:id/pay`,
// the top-up inside `POST /bookings` and the pack purchase are its callers at
// 5.0.0-lg4.2. `POST /staff/invoices/:id/charge` joins at 7.1.0 and
// `POST /enrollments` at 8.0.0.
//   GET  /staff/payments/pending   → GetStaffPaymentsPendingResponse   any role
//   POST /staff/orders/:id/cancel  → PostStaffOrdersCancelResponse     any role
// On both an owner (family) principal is 403 `forbidden`, and a malformed
// `:id` is 400 `bad_request`.

/**
 * One order, as the Confirm that made it answers: `PostBookingsResponse.order`
 * (design §1.1:857-863; PAY-U04, DAY-U16). `orders` stores no status: the two
 * charge fields are read from the order's one `charges` row.
 */
export interface OrderWire {
  id: string;
  owner_id: string;
  created_at: string;
  /**
   * Not `ChargeStatus`: `'none'` is an order with no charge. `'succeeded'`: the
   * charge was paid and the sessions are `'upcoming'`. `'requires_payment'`:
   * Stripe still reports `processing` and the sessions are `'payment-pending'`,
   * the word `CreditPurchaseWire.charge_status` already uses. A confirm answers
   * one of those three. `'failed'` is a read-side value: a confirm that fails
   * answers 402 `payment_failed`, never a 201.
   */
  charge_status: 'none' | 'succeeded' | 'requires_payment' | 'failed';
  /** Why the charge stopped short of `succeeded`, in `ChargeBlocker`'s words:
   *  `'processing'` on `'requires_payment'`. Omitted on `'none'` and
   *  `'succeeded'`. */
  client_action?: ChargeBlocker;
}

/**
 * How one confirm's card tries ended (design §1.1:877-879; PAY-U05). `attempts`
 * counts the confirms sent, at most `pay.card_attempts_max_count`: only a
 * transient processing or network error spends another, and any other decline
 * stops at the first (question 55). `'pending'` is the state
 * `OrderWire.charge_status` calls `'requires_payment'`. `blocker` is omitted on
 * `'succeeded'`.
 *
 * No response carries it at this step. `POST /staff/invoices/:id/charge`, at
 * 7.1.0, is the first.
 */
export interface ChargeAttemptOutcomeWire {
  attempts: number;
  outcome: 'succeeded' | 'pending' | 'failed';
  blocker?: ChargeBlocker;
}

/**
 * One order still pending past `pay.processing_hold_max_minutes`: its one
 * charge is `requires_payment`, and it keeps its seats and is flagged, never
 * swept (PAY-82; design §1.1:887-891, §2.7:3999-4011). Only Stripe's outcome or
 * a person moves it, staff through `POST /staff/orders/:id/cancel`.
 *
 * `kind`: `'booking'` is a Confirm with a top-up, `'package'` a pack or
 * single-day purchase, `'class'` a class order. `'class'` is not listed until
 * 8.0.0, when a class order can stay processing.
 *
 * `owner.name` is the family's name, or its `email` when the name is empty, as
 * on `StaffDogWire.owner_name`, so it is never `null`. `amount_cents` is the
 * charge's. `created_at` is the order's, and `minutes_pending` the whole minutes
 * since it. `sessions` is the order's rows, ascending, omitted on an order with
 * none.
 */
export interface PendingPaymentWire {
  order_id: string;
  owner: { id: string; name: string };
  kind: 'booking' | 'package' | 'class';
  /** The label of the pack or single-day row bought, on a `'package'` row, read
   *  from `charges.package_id` (design §2.7:3841; 5.0.0-lg4.2). Omitted on the
   *  other kinds. */
  package_label?: string;
  amount_cents: number;
  created_at: string;
  minutes_pending: number;
  sessions?: BookingWire[];
}

/** `GET /staff/payments/pending` response: every `PendingPaymentWire`, oldest
 *  first, every campus. */
export type GetStaffPaymentsPendingResponse = PendingPaymentWire[];

/**
 * `POST /staff/orders/:id/cancel` 200 response: staff *Cancel order*, also for a
 * pending purchase with no rows (design §1.1:890-898, §2.7:4010-4030; PAY-U07).
 * Bodyless; `Idempotency-Key` required. It reads what won before it cancels
 * anything, asking Stripe with no transaction open:
 *   - `'settled'` — the charge had succeeded on a purchase or a class order. It
 *     is settled and nothing is cancelled: the lot or the seat stands.
 *   - `'settled_then_cancelled'` — a top-up's charge had succeeded. It is settled,
 *     then its rows are cancelled as credits, each back to its lot. Never
 *     returned for a class order.
 *   - `'cancelled'` — the order is cancelled, with its rows, its debits returned,
 *     its charge `failed` and its claim completed with the 402. That includes a
 *     charge Stripe still reports `processing` and will not cancel: a success
 *     landing later grants nothing and is refunded in full once, automatically.
 * An order paying an invoice takes the same arms, and the invoice stays open
 * unless the charge had succeeded. A class order still `requires_payment` makes
 * no Stripe call, and its enrolments go `payment-failed` (8.0.0; follow-up 4).
 *
 * 404 `not_found` for an id naming no order. 409 `conflict` for an order with
 * nothing pending: no charge, or a charge already `failed` or `refunded`; or
 * when the order changed under the cancel, an intent id landing after its read.
 * Either way nothing is written, and a person may look again.
 *
 * 6.0.0-lg5.1 (P20): on a top-up whose charge had succeeded, the cancel first
 * applies the day cancels' own rule to every day row it would cancel, earliest
 * date first, and refuses the whole order at the first that refuses: 409
 * `session_checked_in` (no `details`) for a day the desk recorded (checked in,
 * turned away, or marked as not coming), 409
 * `session_ended {kind, date}` for a day already over. Nothing is written; the
 * other days stay booked, and the family can cancel them in the app
 * (`designs/p20-event-ledger-link.md` §M2).
 */
export interface PostStaffOrdersCancelResponse {
  order_id: string;
  outcome: 'cancelled' | 'settled' | 'settled_then_cancelled';
}

// ---- (c) request bodies + query shapes -------------------------------------

/**
 * `POST /invoices/:id/pay` request body. Bodyless is still valid — every field
 * is optional and omitting the whole body is the pre-1.7.0 behaviour.
 *
 * `payment_method_id` is the card the owner picked at settle time. Before 1.7.0
 * the endpoint took no body at all and always charged the invoice's BOUND card,
 * so the mobile pay sheet's card picker was decorative: an owner could select
 * "Mastercard ••8203" and be charged their Visa. Naming the card here is what
 * makes that picker true.
 *
 * Optional rather than required, deliberately:
 *   - a client that omits it keeps the old behaviour (charge the bound card),
 *     so this is a minor bump and no client has to move in lockstep;
 *   - the idempotency request hash is canonical JSON, which DROPS
 *     `undefined`-valued keys, so an omitted card hashes byte-identically to the
 *     pre-1.7.0 `{ id }` body and no in-flight Idempotency-Key breaks;
 *   - two calls naming DIFFERENT cards now hash differently, which closes a real
 *     hazard: under the old `hashRequestBody({ id })` they collided, so the
 *     second call replayed the first's stored response and the owner was told a
 *     card had been charged that never was.
 *
 * The server verifies the card is a LIVE card of the calling owner and 404s
 * otherwise (tenancy misses collapse to 404 rather than 403 to avoid probing),
 * then repoints `invoices.payment_method_id` at it inside the settle
 * transaction so the receipt names the card actually charged.
 *
 * The route rides the order engine since 4.0.0-lg3.2 (design §2.7:3824-3830;
 * PAY-U05, PAY-U07). Its failure policy leaves the invoice open:
 *   - 201 `InvoicePayWire` with `invoice_status: 'paid'`: settled.
 *   - 201 with `charge_status: 'requires_payment'`, `charge_blocker: 'processing'`
 *     and `invoice_status: 'open'`: Stripe has not answered, so do not retry.
 *     The webhook or the sweeper settles it.
 *   - 402 `payment_failed` (`PaymentFailedDetails`): the order ended unpaid; a
 *     decline was a 201 until now. The invoice stays open with only the failed
 *     charge recorded. A replay returns the same 402, so the next try takes a
 *     fresh key, with this card or another.
 *   - 409 `idempotency_inflight`: no answer exists yet, because the last confirm
 *     went unanswered or the engine stopped. Re-send under the same key; the
 *     final answer replays once the order has settled. Nothing more is charged.
 *   - 409 `invoice_payment_in_flight`, no `details`: another order on this
 *     invoice holds a `requires_payment` charge inside its lease (several orders
 *     may try one invoice, one at a time). Nothing is charged.
 */
export interface InvoicePayRequest {
  payment_method_id?: string;
}

/**
 * `POST /payment-methods/confirm` request body. Promoted 1.13.0 from the
 * file-private `confirmBodySchema` (`routes/paymentMethods.ts:69`, digest
 * payments-invoices/M "cards … confirm shapes"); §4.2 naming. Pinned to that
 * schema by `PostPaymentMethodsConfirmBodyConformance` in the route file.
 *
 * The client supplies a SetupIntent id and NEVER a payment-method id — that is
 * the trust model, not a convenience. The server retrieves the intent from
 * Stripe and verifies (a) `status === 'succeeded'` and (b) that its customer
 * maps to THIS owner; a tenancy miss is a 404, not a 403, so a probe cannot
 * confirm someone else's SetupIntent exists. Card display bits come from
 * Stripe, never from the client (R20,
 * BUSINESS-LOGIC/payments-invoices.md:82).
 *
 * `.strict()`: an unknown key is a 400, not a silent ignore. An
 * `Idempotency-Key` header is required (400 without one).
 */
export interface PostPaymentMethodsConfirmRequest {
  setup_intent_id: string;
}

/**
 * `PATCH /payment-methods/:id` request body. Promoted 1.13.0 from the
 * file-private `patchBodySchema` (`routes/paymentMethods.ts:67`, digest
 * payments-invoices/M "cards"); §4.2 naming. Pinned to that schema by
 * `PatchPaymentMethodsBodyConformance` in the route file.
 *
 * The literal `true` is the schema's truth, transcribed, not a tightening:
 * `is_default: false` is a 400 today and there is no un-default verb — a
 * default is cleared only by making another card the default, or by deleting
 * the card. An empty body is likewise a 400 (`.strict()`, and the key is
 * required).
 *
 * Responds with the owner's full card list, not the single mutated card.
 */
export interface PatchPaymentMethodsRequest {
  is_default: true;
}

// ---- (d) per-endpoint 422 union aliases ------------------------------------
//
// None this pass. §3.5 ships the typed-422 aliases for POST /bookings, POST
// /requests, POST /enrollments and POST /events/:id/rsvp — the digest-named
// gate surfaces. No endpoint in this domain 422s with a `details` payload:
// `POST /invoices/:id/pay` fails with bare `not_found` / `conflict` /
// `invalid_payload` / `invoice_payment_in_flight`, and a charge still processing
// rides `InvoicePayWire.charge_blocker` in a 201 body. The one `details`-carrying
// money arm, `payment_failed` / `PaymentFailedDetails`, is a 402 and not a 422,
// so it is no alias here either: `InvoicePayRequest` documents it for this route,
// and enrollments, requestConfirmPayment, the pack purchase and the top-up emit it
// too (wire.ts §1, design §3.3).

// ---- (e) domain helpers ----------------------------------------------------
//
// None. This domain owns no pure wire helper (`deepLinkToPath` belongs to
// notifications; `isSessionProgram` to reports).

// <<< domain:payments-invoices ================================================

// >>> domain:rates-availability ===============================================

/**
 * `GET /rates` response — the one effective-dated price-catalog row for a
 * (category, location) track at today-in-Chicago. Promoted 1.13.0 from
 * `lib/ratesWire.ts:23` (digest rates-availability/M); the mapper
 * `toRateWire` (`ratesWire.ts:32`) stays server-side and that file now
 * re-exports this type, so no consumer moves this pass.
 *
 * Two §B conventions travel with the shape (`ratesWire.ts:15-21`,
 * DATA-CONTRACT §B Rate Δ 2026-05-20):
 *   • `location` is an explicit **non-omit exception** to the file-wide
 *     omit-on-null rule: it emits as `null`, never omitted, when the matched
 *     row has `service_rates.location IS NULL`, because null here is
 *     meaningful DATA ("this price applies to all locations"), not absence.
 *     Pinned by `GET /rates` falling back to a null-location row in
 *     `test/contracts/rates.test.ts`.
 *   • `note?` follows the default rule and is omitted when the column is
 *     NULL **or the empty string** (`ratesWire.ts:40`) — note the staff view
 *     below reports the same column as `note: string | null`, always present.
 *     Two views of one column, transcribed as the two truths they are.
 *
 * Selection: a location-specific row beats a null-location row; no row
 * active at today ⇒ 404 `not_found` (`routes/rates.ts:54-60`). Reference
 * data — owner and staff principals get identical bytes
 * (BUSINESS-LOGIC/payments-invoices.md:172). From 4.0.0 no day-program booking
 * reads this catalog: a day is paid in credits (R1). From 5.0.0-lg4.2 it holds
 * only each campus's evaluation row (DAY-U23), so every other category is that
 * 404. A single day's price is a `CreditPackageWire` row, never a rate.
 */
export interface RateWire {
  category: ServiceCategory;
  location: LocationKey | null;
  amount_cents: number;
  unit: RateUnit;
  effective_from: string;
  note?: string;
}

/** Staff-config view of the effective-dated price catalog. Rows are addressable
 *  (`id`) for void/edit; `effective_to`/`created_by_staff_id`/`note`/`location`
 *  always present (vs the owner-facing read).
 *
 *  Also the response of `POST /staff/rates/:id/void` (no body;
 *  `Idempotency-Key` required; `staffRates.ts:223`). From 2.0.0-lg1.2 that
 *  verb is owner and manager only, like `POST /staff/rates`
 *  (`requireStaffRole('owner', 'manager')`, STAFF-U07; design §1.1:706-709,
 *  §2.1:2080-2084): a trainer is 403 `forbidden`, no `details`. The two
 *  reads, `GET /staff/rates` and `GET /staff/rates/history`, stay any staff
 *  role.
 *
 *  4.0.0 (design §2.7:4058-4059; PAY-U41): voiding a row whose `effective_from`
 *  is before today in America/Chicago, when it has a predecessor, is 409
 *  `conflict`: it would reopen the predecessor over dates already past. */
export interface StaffRateWire {
  id: string;
  category: ServiceCategory;
  location: LocationKey | null;
  amount_cents: number;
  unit: RateUnit;
  effective_from: string;
  effective_to: string | null;
  note: string | null;
  created_by_staff_id: string | null;
}

export interface StaffRateHistoryWire extends StaffRateWire {
  created_at: string;
  voided_at: string | null;
  voided_by_staff_id: string | null;
}

/**
 * One element of `GET /availability` — day-program capacity for one
 * (location, date) — and the 200 body of `PUT` and
 * `DELETE /staff/day-capacity/:location/:date`. Promoted 1.13.0 from the
 * route-local declaration at `routes/availability.ts:61` (digest
 * rates-availability/M), which is what
 * DISCREPANCIES NOTE-1 (@ :645) flagged: the shape lived in a route file and
 * was hand-mirrored in mobile (`availabilityRepository.ts:20 RawCapacity`),
 * so a change bypassed the version bump entirely.
 *
 * **One cap per (location, date), combined across day school and daycare**
 * (4.0.0-lg3.1; DAY-U05, DAY-10). `capacity_dogs` is the date's CONFIGURED
 * cap: `day.daily_capacity_dogs` when the date's weekday is in
 * `day.open_weekdays_list`, otherwise 0, and a live `day_capacity` row for
 * (location, date) overrides either (DAY-11). Both settings are per campus
 * (`DayProgramCampusSettingsWire`). Nothing is subtracted from it for dogs
 * already booked. It says how many seats a date has, never which programs run
 * there: whether a campus offers daycare is `offerings` (§ settings).
 *
 * `remaining_dogs` is that cap minus every live client booking dog on that
 * date at that campus, day school and daycare together, floored at 0. A live
 * dog is one whose session is not cancelled and whose own `booking_dogs` row
 * is live; a staff-owned dog is not counted. An evaluation does not count yet
 * (P10 and P11 carry that arm). The field began as the 1.13.0 fix round's
 * `*_remaining` pair: Allison's §6-batch decision #3, option C, APPROVED
 * 2026-08-24 (designs/decision-batch-2026-08.md item 3).
 *
 * ADVISORY, not authoritative: it is computed outside any booking lock, so a
 * concurrent booking can stale it between read and POST — the authoritative
 * arithmetic still runs inside the booking transaction
 * (`dayCapacityRepository.assertCapacityWithinLock`) and the 422
 * `insufficient_capacity` remains the source of truth at write time. Mobile's
 * calendar reads it, so a fully-booked day renders as full instead of the
 * owner learning at the 422.
 */
export interface DayCapacityWire {
  location: LocationKey;
  date: string;
  /** The date's combined seat cap. Nothing booked is subtracted (see doc). */
  capacity_dogs: number;
  /** `capacity_dogs` minus live client booking dogs, floored at 0 — advisory (see doc). */
  remaining_dogs: number;
}

/**
 * `POST /staff/rates` body — set the evaluation rate of one campus,
 * effective-dated. Promoted 1.13.0 from `routes/staffRates.ts:63-79`
 * (digest rates-availability/M) and pinned to that schema in the route file
 * by `PostStaffRatesBodyConformance` (§5.1.3, `z.input`). Since 5.0.0-lg4.2 it
 * keeps only that row (design §1.1:929-935, §3.2:5729; DAY-U23), moved from design
 * 4.0.0 by §1.3.
 *
 * Staff-only; `Idempotency-Key` required (`staffRates.ts:159`). The schema is
 * `.strict()` — unknown keys are rejected, not stripped.
 *   • `amount_cents` — in v1 only the seed, 0: any other integer is 422
 *     `invalid_payload`. No evaluation charge path is designed, and question 27
 *     holds every price at its seed.
 *   • `effective_from` — `YYYY-MM-DD`; omitted means today-in-Chicago. The
 *     route (not the schema) rejects any date before today with 422
 *     `invalid_payload`: back-dating would corrupt as-charged history
 *     (`staffRates.ts:163-168`).
 *   • `note` — max 500 chars.
 *
 * `location` is non-nullable here while `RateWire.location` is
 * `LocationKey | null`. That asymmetry is transcribed, not fixed: no route
 * can create a null-location ("all locations") row, because the sole INSERT
 * into `service_rates` (`serviceRatesRepository.ts:246`, inside
 * `supersedeRate`, whose args type demands a `LocationKey` at `:197-207`) is
 * reachable only from this body. Consequence: voiding a null-location track
 * is one-way, contradicting the "there is no way to trap a track" guarantee
 * at `staffRates.ts:207-208`. Filed as the digest's rates-availability
 * fix/S item (phase 3.1) — §14.1 forbids changing behavior here.
 *
 * Owner and manager only from 2.0.0-lg1.2: the route is
 * `requireStaffRole('owner', 'manager')` whole (STAFF-U07; design
 * §1.1:706-709, §2.1:2080-2094), so a trainer is 403 `forbidden`, no
 * `details`; an owner principal is 403 as before. The guard is the role, not
 * `StaffCapabilitiesWire.edit_prices`: that flag is false for every role in
 * v1, and this route's one accepted amount is the seed (§2.1:2087-2091). The
 * (category, campus) track has no trainer axis; a trainer's own lesson price
 * is STAFF-U23's, later.
 */
export interface PostStaffRatesRequest {
  category: 'evaluation';
  location: LocationKey;
  amount_cents: number;
  unit: RateUnit;
  effective_from?: string;
  note?: string;
}

/**
 * `GET /rates` query string. Both params are REQUIRED
 * (`routes/rates.ts:31-34`); a missing or non-member value is 400
 * `bad_request`, not 422 (`rates.ts:65-71`). Promoted 1.13.0 (digest
 * rates-availability/M).
 */
export interface GetRatesQuery {
  category: ServiceCategory;
  location: LocationKey;
}

/**
 * `GET /availability` query string — all three params REQUIRED
 * (`querySchema`, `routes/availability.ts`). Promoted 1.13.0 (digest
 * rates-availability/M). `mode` left at 4.0.0-lg3.1: one cap per (location,
 * date) has no mode to ask about. The schema is not `.strict()`, so a stale
 * client still sending `mode=` is not refused and the key is dropped.
 *
 *   • `from` / `to` — `YYYY-MM-DD`, inclusive range. The regex alone accepts
 *     `2026-02-31`; the `.refine(isValidCalendarDate)` is what rejects it,
 *     and field-level failures are 400 `bad_request`.
 *   • Range errors are 422 `invalid_payload`, NOT 400 — `to` before `from`,
 *     or a window over the date cap — because both are user-fixable mistakes
 *     that already passed field validation (`resolveRange`).
 *   • The date cap (`availabilityMaxDates`, `lib/availability.ts`) follows
 *     `day.booking_horizon_months` (design §2.3:2353): at least as many dates
 *     as that many calendar months can hold, so a window from today through
 *     the horizon's last date always fits. The refusal's message names the
 *     live number; read it rather than hard-coding one.
 */
export interface GetAvailabilityQuery {
  from: string;
  to: string;
  location: LocationKey;
}

/**
 * `PUT /staff/day-capacity/:location/:date` body `[staff]` — one campus's cap
 * on one date (the store of `day.capacity_override_dogs`). New 4.0.0-lg3.1
 * (DAY-U07, DAY-11, DAY-67; design §1.1:921-924, §2.3:2334-2352).
 *
 *   PUT    /staff/day-capacity/:location/:date  → 200 `DayCapacityWire`
 *   DELETE /staff/day-capacity/:location/:date  → 200 `DayCapacityWire`, no body
 *
 * `PUT` is an upsert: it sets the date's cap, opens a date the default rule
 * closes (a weekend included) and re-opens a withdrawn date. `DELETE` withdraws
 * the override, so the date falls back to the default rule (`DayCapacityWire`):
 * 0 on a closed weekday. A `DELETE` that finds no live override changes nothing
 * and is still 200, so PUT, DELETE, PUT on one date is 200 three times. Both
 * answer the date's resulting `DayCapacityWire`, read in the write's
 * transaction; a replay of a completed `Idempotency-Key` returns the original
 * body.
 *
 * Any staff role, at either campus: a staffer's `home_locations` is descriptive
 * and refuses nothing (STAFF-71, STAFF-73). An owner principal is 403
 * `forbidden`.
 *
 * `Idempotency-Key` REQUIRED on both (§0 conventions), a fresh key per edit.
 * The `requestHash` covers `{location, date, ...body}`, so one key sent to a
 * second date is 422 `idempotency_mismatch`.
 *
 * Refused, in this order; a refused edit writes nothing:
 *   1. 400 `bad_request` — a `:location` outside `LOCATIONS`, a `:date` that is
 *      not a real `YYYY-MM-DD` calendar date, or a `PUT` body the strict parse
 *      refuses: an unknown key, or `capacity_dogs` not a whole number in
 *      0..2147483647 (`parseOrThrow`, the `/staff/cancel-window/:category`
 *      precedent).
 *   2. 422 `capacity_below_booked` + `CapacityBelowBookedDetails` — a booked
 *      date within the horizon would fall below its count, checked under the
 *      date's `(location, date)` lock. A `DELETE` can answer this too, when
 *      the default rule gives the date fewer seats than are booked on it.
 */
export interface PutStaffDayCapacityRequest {
  /** Dogs, day school and daycare together; 0 closes the date. */
  capacity_dogs: number;
}

/**
 * `GET /staff/rates/history` query string — both params REQUIRED
 * (`routes/staffRates.ts:81-84`), together identifying ONE (category,
 * location) track; the response is every row for that track including
 * expired and voided ones, newest first, because the append-only rows ARE
 * the history. Staff-only. Promoted 1.13.0 (digest rates-availability/M).
 *
 * Structurally identical to `GetRatesQuery` and deliberately NOT aliased to
 * it: different endpoints whose params may diverge, and a shared alias would
 * let one endpoint's change silently retype the other.
 */
export interface GetStaffRatesHistoryQuery {
  category: ServiceCategory;
  location: LocationKey;
}

