// ---- (a) domain-local enums ------------------------------------------------

/**
 * Lifecycle of one `refunds` row. Mirrors the `refund_status` pgEnum
 * (`schema.sql:188`, column `refunds.status` at `:1406`; `db/schema/schema.ts:27`)
 * and is pinned against it in `conformance.ts`. Promoted 1.13.0 from
 * `db/repositories/refundsRepository.ts:57` (digest refunds/S, "Pin
 * refund_status once refunds reach the wire"); that file now re-exports this
 * type instead of redeclaring it, so the DB status and the wire status cannot
 * drift into two definitions — the `ChargeStatus`/`chargesRepository`
 * precedent.
 *
 * **No 1.13.0 wire shape carries a field of this type, and that is the honest
 * state, not an oversight.** The refunds domain has no owner-facing READ
 * surface: nothing outside `refundsRepository` SELECTs the table, and the only
 * refund facts an owner ever receives are cents and booleans elsewhere —
 * `EnrollmentWithdrawResultWire.refunded_cents` / `.owed_cents`,
 * `InvoicePayWire.charge_refunded`, and the ledger entry's own `'refunded'`
 * status. The union is contracted anyway
 * for two reasons: it is the vocabulary the portal wave's staff refund surface
 * (POST /staff/refunds + `RefundWire`, Adjudication 8 — design deferred,
 * `designs/wire-contract-completion.md` §17) must be built against, and a
 * contracted union is what earns the DB conformance pin that stops `schema.sql`
 * from moving underneath it. Documented, not fixed.
 *
 * 2.0.0 gives it its first field: `StaffPaymentRefundWire.status`, on the
 * staff payment history (`GET /staff/owners/:id/payments`, owner and manager;
 * STAFF-U13, § payments-invoices). Still no owner-facing read.
 *
 * The complete state machine (`refundsRepository.ts:36-56`) — nothing else is
 * reachable, and every arm below is written by exactly one verb:
 *
 *   pending → succeeded | failed             (Stripe `charge.refund.updated`)
 *   pending → unroutable                     (born terminal, or the sweep's flip)
 *   failed | unroutable → resolved-external  (STAFF, note required)
 *   resolved-external → ∅                    (terminal; webhook events no-op)
 *
 * `'unroutable'` (2026-08-19, `designs/client-keyed-refund-recovery.md` §4;
 * extended 2026-08-24 by `designs/money-residue.md` §3 to the group-class
 * withdraw's `refund_manual` arm) means money is owed on a charge that carries
 * no `stripe_payment_intent_id`, so no automatic path will ever send it — the
 * money returns when a human returns it. `'resolved-external'`
 * (`money-residue.md` §4) is the exit `'failed'` and `'unroutable'` never had:
 * the money behind the row was returned OUTSIDE our Stripe machinery, attested
 * by a named human.
 *
 * Member order mirrors the pgEnum declaration order; only set equality is
 * pinned.
 */
export type RefundStatus = 'pending' | 'succeeded' | 'failed' | 'unroutable' | 'resolved-external';

// Deliberately NO `REFUND_STATUSES` value tuple. §5.2 mints one only where a
// consumer iterates or validates the members, or a digest item names one, and
// neither is true today: the only iteration in this domain is server-side over
// refund ROWS, never over the vocabulary, and no client mirrors it. A tuple now
// would be a §16 pin guarding a constant nothing reads. It becomes correct the
// moment the portal wave's staff refund filter needs one — filed there, not
// minted here.

