export interface SkillResult {
  status: 'pass' | 'learning' | 'pending';
  score?: string;
  meta?: { label: string; value: string }[];
}

export interface PracticeItem {
  text: string;
}

/**
 * One section of a private-lesson handout topic. Discriminated on `kind`.
 *
 * Promoted 1.13.0 (digest reports/M — "type the four `*_content` session
 * blobs"). Transcribed from the emission the contract snapshot pins
 * (`test/contracts/snapshots/report-private-lesson.json` — `steps` + `note`)
 * and from mobile's `PrivateLessonSection` (`types/report.ts:63-71`), which is
 * the CLIENT's live reading of this same blob and the source of the `list` and
 * `videos` arms.
 *
 * `list` and `videos` are NOT provoked by any backend contract test today —
 * they are attested only by mobile's mock corpus. Named phase-3 test debt
 * (design §14.5: "promoted types match emissions on arms no contract test
 * provokes"), NOT a reason to drop the arms: dropping them would narrow what a
 * client may legally receive, which is the tightening §14.1 forbids.
 *
 * `label` is the section eyebrow ("When", "How", "Video examples"); absent
 * label = no eyebrow. Optionality of `label` is proven by emission — the
 * snapshot's `steps` section omits it.
 */
export type PrivateLessonSectionWire =
  | { kind: 'steps'; label?: string; items: string[] }
  | { kind: 'list'; label?: string; items: string[] }
  | { kind: 'note'; text: string }
  | { kind: 'videos'; label?: string; items: { title: string; subtitle?: string }[] };

/** One protocol topic on a private-lesson handout (Leash, Up-Down, …).
 *  Promoted 1.13.0 from the `private_lesson_content` emission
 *  (`test/contracts/snapshots/report-private-lesson.json`; digest reports/M). */
export interface PrivateLessonTopicWire {
  id: string;
  title: string;
  sections: PrivateLessonSectionWire[];
}

/**
 * `ReportWire.private_lesson_content` — the trainer-handout doc a
 * `private-lesson` report carries. Promoted 1.13.0 (digest reports/M).
 *
 * Source of truth is the stored `reports.content` JSONB, emitted verbatim by
 * `lib/reportWire.ts:attachVariantContent`. The server does NOT validate this
 * doc on write (`routes/staffReports.ts:75` — `z.record(z.unknown())`), so
 * this type transcribes what is EMITTED, and is not enforced at the write
 * boundary. That gap is DISCREPANCIES BUG-13, filed not enacted (§14.1).
 */
export interface PrivateLessonContentWire {
  session_focus: string;
  topics: PrivateLessonTopicWire[];
}

/**
 * One day of a multi-night stay journal.
 * Promoted 1.13.0 from the `boarding_session_content` /
 * `board_train_session_content` emissions (digest reports/M).
 *
 * `date` is an ISO-8601 instant, like every other wire timestamp.
 * `photo_count` is how many of the dog's photos the client slots into this
 * day's strip — a COUNT, never a media id or URL. Owner-side media-by-report
 * is a separate, unbuilt read (DRIFT-36 / R26, §17 portal wave).
 *
 * `meals_note`, `trainer_note` and `photo_count` are optional by EMISSION —
 * `snapshots/report-boarding.json`'s day entry omits all three. `sleep_note`
 * is optional by the mock corpus (11 of 14 board-train days omit it).
 */
export interface BoardingDayEntryWire {
  date: string;
  label: string;
  activities: string[];
  sleep_note?: string;
  meals_note?: string;
  trainer_note?: string;
  photo_count?: number;
}

/**
 * `ReportWire.boarding_session_content` — the per-day journal a
 * `boarding-session` report carries. Promoted 1.13.0 (digest reports/M).
 *
 * `summary?` is optional on mobile's live reading of this blob
 * (`repositories/reportRepository.ts:56`); both emissions on record DO carry
 * it, so its absence is unproven — keeping it optional is the non-tightening
 * direction (§14.1). Same write-side caveat as `PrivateLessonContentWire`.
 */
export interface BoardingSessionContentWire {
  check_in_date: string;
  check_out_date: string;
  nights: number;
  summary?: string;
  days: BoardingDayEntryWire[];
}

/**
 * `ReportWire.board_train_session_content` — a board-&-train residential
 * journal. Promoted 1.13.0 (digest reports/M).
 *
 * Deliberately an ALIAS, not a copy: the two docs are structurally identical
 * in every emission on record (`snapshots/report-board-train.json` carries
 * exactly the boarding key set), and mobile already models them as one type
 * (`types/report.ts:121` `BoardTrainSessionContent = BoardingSessionContent`;
 * `reportRepository.ts:93` types the raw blob as the boarding shape). The
 * difference is intent — training residential vs care during an absence — not
 * structure. Minting a second identical interface would invent a distinction
 * the runtime does not make, which is not transcription.
 */
export type BoardTrainSessionContentWire = BoardingSessionContentWire;

/**
 * One skill/concept bullet on a group-class weekly handout.
 * Promoted 1.13.0 from the `group_class_session_content` emission
 * (`test/contracts/snapshots/report-group-class.json`; digest reports/M).
 *
 * `isLinked` is camelCase inside an otherwise snake_case document. That is
 * the emitted key (snapshot: `{ "label": "Engagement", "isLinked": true }`)
 * and the key mobile's renderer consumes — it is passed through untouched
 * (`reportRepository.ts:117`). DOCUMENTED, NOT RENAMED: renaming a runtime key
 * is a behavior change wearing a doc change's clothes (§14.1), and it would
 * silently blank the "linked topic" underline in the owner app. Same class of
 * pinned embarrassment as the `media-upload-missing` kebab kind (§3.2).
 * Both keys are optional by emission — the snapshot's two topics omit one each.
 */
export interface GroupClassTopicWire {
  label: string;
  description?: string;
  isLinked?: boolean;
}

/**
 * One weekly meeting recap in a group-class cohort handout.
 * Promoted 1.13.0 (digest reports/M).
 *
 * `highlight` and `concepts` are optional by EMISSION (the snapshot's week 1
 * omits both). `location`, `intro`, `practice_items` and `closing_note` are
 * optional on mobile's live reading (`reportRepository.ts:60-71`); every
 * emission on record carries them, so their absence is unproven — optional is
 * the non-tightening direction (§14.1).
 */
export interface GroupClassWeekEntryWire {
  week_number: number;
  date: string;
  title: string;
  location?: string;
  intro?: string;
  highlight?: string;
  topics: GroupClassTopicWire[];
  practice_items?: string[];
  concepts?: string[];
  closing_note?: string;
}

/**
 * `ReportWire.group_class_session_content` — the multi-week cohort handout a
 * `group-class-session` report carries. Promoted 1.13.0 (digest reports/M).
 * One doc per cohort run; the weekly bookings all point at the same report via
 * `session_report_id` (`routes/staffReports.ts:37-40`). Same write-side caveat
 * as `PrivateLessonContentWire`.
 */
export interface GroupClassSessionContentWire {
  class_name: string;
  cohort_label?: string;
  week_count: number;
  weeks: GroupClassWeekEntryWire[];
}

export interface ReportWire {
  id: string;
  dog_id: string;
  date: string;
  trainer?: string;
  category: ServiceCategory;
  program: ReportProgram;
  excerpt: string;
  full_text: string;
  visit_count?: number;
  verdict_headline?: string;
  results?: Record<string, SkillResult>;
  practice_at_home?: PracticeItem[];
  friends_today?: string[];
  additional_skills_completed?: string[];
  // 1.13.0 §14.2 CLASS A — these four were `unknown` through 1.12.0. Exactly
  // one is present, keyed by `program` (`lib/reportWire.ts:134-159`); a
  // curriculum program carries none. Readers of `unknown` had to narrow and
  // still compile. Runtime pins: `test/contracts/report-content-types.test.ts`.
  private_lesson_content?: PrivateLessonContentWire;
  boarding_session_content?: BoardingSessionContentWire;
  board_train_session_content?: BoardTrainSessionContentWire;
  group_class_session_content?: GroupClassSessionContentWire;
}

/**
 * `GET /staff/reports` response — the cross-owner staff report list.
 *
 * NET-NEW in 1.13.0, contract-first: the shape lands here, the route is built
 * in 2.3b (design §9; digest reports/M). A bare array with no envelope and no
 * pagination is the house shape for every staff list endpoint that exists
 * today — `GET /staff/dogs` (`staffDogs.ts:45`), `GET /staff/threads`
 * (`staffThreads.ts:54`), `GET /staff/bookings` (`staffBookings.ts:95`).
 *
 * Rows are live reports only (`reports.expired_at IS NULL` — `schema.sql:589`,
 * the `live()` predicate `reportsRepository` already applies to every read).
 */
export type GetStaffReportsResponse = ReportWire[];

/**
 * `GET /staff/reports` query. `dog_id` is REQUIRED — an unscoped cross-owner
 * report list 400s (Allison ruling
 * 2026-08-25, wire-contract-completion WC-A5: staff name a dog to list its
 * reports; widening to an optional scope later is additive, narrowing would
 * be breaking). `program`/`category` are optional filters; all three are
 * served by `reports_dog_date_idx`. Contracted here BEFORE the 2.3b build
 * (contract-first, ORCHESTRATOR §6.2) — the route lands in 2.3b.
 */
export interface GetStaffReportsQuery {
  dog_id: string;
  program?: ReportProgram;
  category?: ServiceCategory;
}

/**
 * `DELETE /staff/reports/:id` response — 204 No Content, empty body.
 *
 * NET-NEW in 1.13.0, contract-first; route built in 2.3b (design §9). The
 * semantics §14.3 requires be fixed before the build:
 *   - SOFT delete. Sets `reports.expired_at` (`schema.sql:589` — "NULL = live
 *     (soft-delete)"); the row is retained. No DDL: the column exists.
 *   - The report drops out of every owner read immediately, because all four
 *     owner reads already filter on `live(reports)`
 *     (`reportsRepository.findLiveForOwnedDog` / `findByIdForOwner` /
 *     `findLatestForOwnedDog`).
 *   - Staff-only, idempotency-keyed, inside `withMutation` — the established
 *     soft-expire shape (`dogs.ts:457`, `notifications.ts:168`, both
 *     `withMutation<null>` returning `{ status: 204, body: null }`).
 *   - 404 when there is no LIVE report with that id, so a second DELETE 404s
 *     rather than reporting success on an already-expired row.
 *   - NO re-notification and NO un-publish verb: the drafts/publish model is a
 *     separate portal-wave design (Adjudication 6, §17).
 */
export type DeleteStaffReportsResponse = null;

// (c) request bodies + query shapes -------------------------------------------

/**
 * The curriculum envelope a staff author may send, stored verbatim in the
 * `reports.results` JSONB column and spread to four sibling keys on read
 * (`lib/reportWire.ts:107-126`). Promoted 1.13.0 from
 * `routes/staffReports.ts:65-72` (digest reports/M — "bring reports/media
 * REQUEST shapes into wire.ts").
 *
 * The schema is `.strict()`: an unknown key is a 422, not a silent drop.
 * Note the read/write asymmetry, which is contract truth, not an oversight:
 * on WRITE these four keys are nested under `results`; on READ they are
 * spread flat onto `ReportWire`, and an empty array/object is OMITTED rather
 * than echoed back (`reportWire.ts:111-125`).
 * Pinned to the schema by `StaffReportResultsEnvelopeConformance`
 * (`routes/staffReports.ts`).
 */
export interface ReportResultsEnvelopeWire {
  results?: Record<string, SkillResult>;
  practice_at_home?: PracticeItem[];
  friends_today?: string[];
  additional_skills_completed?: string[];
}

/**
 * `POST /staff/reports` request body. Staff-only, `Idempotency-Key` required.
 * Promoted 1.13.0 from `routes/staffReports.ts:77-92` (digest reports/M).
 * Pinned by `PostStaffReportsBodyConformance`.
 *
 * Cross-field rules, enforced in the route rather than in the type (§4.6):
 *   - `content` is REQUIRED for a SESSION program and FORBIDDEN for a
 *     CURRICULUM one — 422 either way (`staffReports.ts:277-288`,
 *     `assertContentByProgram`, discriminating via `isSessionProgram`). The DB
 *     `reports_check` CHECK (`schema.sql:591-596`) is the backstop.
 *   - `date` must carry an offset (`z.string().datetime({ offset: true })`).
 *     A bare `YYYY-MM-DD` 422s — the exact trap DISCREPANCIES DRIFT-37 records
 *     for the portal, whose report dates are ISO dates.
 *   - `link_booking_id` must be a LIVE booking whose lead dog is `dog_id`, else
 *     422 `invalid_payload`. For a group-class booking the back-link fans out
 *     to every weekly booking of that (cohort, dog).
 *   - `trainer_staff_id` defaults to the authoring staff principal when omitted.
 *
 * `content` is `Record<string, unknown>` and NOT one of the four
 * `*ContentWire` types, because the schema accepts any record
 * (`staffReports.ts:75` — `z.record(z.unknown())`). Typing it narrower here
 * would start REJECTING payloads production accepts — the §14.1 tightening —
 * and was proven to break this body's §5.1.3 pin (Evidence E4).
 * Closing that hole is write-side validation: DISCREPANCIES BUG-13, filed.
 */
export interface PostStaffReportsRequest {
  dog_id: string;
  date: string;
  category: ServiceCategory;
  program: ReportProgram;
  excerpt: string;
  full_text: string;
  trainer_staff_id?: string;
  visit_count?: number;
  verdict_headline?: string;
  results?: ReportResultsEnvelopeWire;
  content?: Record<string, unknown>;
  link_booking_id?: string;
}

/**
 * `PATCH /staff/reports/:id` request body. Staff-only, `Idempotency-Key`
 * required. Promoted 1.13.0 from `routes/staffReports.ts:96-105` (digest
 * reports/M). Pinned by `PatchStaffReportsBodyConformance`.
 *
 * Identity columns (`dog_id`, `category`, `program`) are absent by design —
 * they are locked, and a re-author POSTs a new report
 * (`staffReports.ts:193-195`). No re-notification fires: an edit is a
 * correction, not a publish.
 *
 * The four nullable keys distinguish three states, which is why they are
 * `?: T | null` and not `?: T`: key ABSENT = leave unchanged; key `null` =
 * CLEAR the column; key with a value = replace. Re-validated against the
 * STORED program: a curriculum report cannot grow a `content` doc and a
 * session report cannot have one cleared — 422 either way
 * (`staffReports.ts:221-235`). `excerpt` and `full_text` are NOT nullable —
 * they are `NOT NULL` columns (`schema.sql:579-580`).
 */
export interface PatchStaffReportsRequest {
  excerpt?: string;
  full_text?: string;
  visit_count?: number | null;
  verdict_headline?: string | null;
  results?: ReportResultsEnvelopeWire | null;
  content?: Record<string, unknown> | null;
}

// (d) per-endpoint 422 union aliases — NONE. §3.5 ships aliases for POST
//     /bookings, POST /requests, POST /enrollments and POST /events/:id/rsvp
//     only. Every reports 422 rides bare `invalid_payload` with NO `details`
//     member (`staffReports.ts:224,231,280,284,293,301`), so an alias here
//     would name an empty union.

// (e) domain-owned pure helpers -----------------------------------------------

export function isSessionProgram(program: ReportProgram): boolean {
  // `as` only widens the narrow `as const` tuple to the general union so
  // `.includes` accepts any ReportProgram — a provably-safe widening, never a
  // narrowing, so no runtime risk.
  return (SESSION_PROGRAMS as readonly ReportProgram[]).includes(program);
}

// <<< domain:reports ==========================================================

// >>> domain:settings =========================================================
//
// New at 2.0.0-lg1.1 — plan unit P01, slice S01, ledger SET-U01; LG1 step 1 of
// 3 toward 2.0.0. Contract-first: no route serves these shapes until P01's
// phase B builds `routes/settings.ts` and `routes/staffSettings.ts`.
// 2.0.0-lg1.2 (plan unit P02, slice S02, LG1 step 2 of 3) appends the `staff`
// domain (`StaffSettingsWire`, design §1.1:685-694, M1.21); no route serves it
// until P02's backend lands M1.21. 2.0.0 (plan unit P03, slice S03, LG1 step 3
// of 3; build DECISIONS 85, J27) adds the settings MANIFEST,
// `GET /staff/settings/manifest` (`StaffSettingsManifestWire`), and caps the
// length of an offering's `name` and `description` (`ServiceOfferingWire`).
//
// Sources, by authority: design §1.1 2.0.0 (design.md:608-684) for every
// shape; §3 (design.md:5677-6054) for every key's seed; §4 M1.01–M1.16
// (design.md:6137-6149) for the columns — a staff wire field MIRRORS a column
// of its domain's settings table. Where §4 names no column it either defers to
// the ledger unit its row cites (M1.08 "as DOG-U02 wrote it", and the
// positional seeds of M1.11, M1.12, M1.15, M1.16, which only read against
// MSG-U02's, NOTIF-U02's, RPT-U02's and VAX-U08's column lists in
// `units/P01/ledger-units.json`), or names nothing at all (M1.07), where the
// column is the §3 key without its domain prefix. A §3 key whose column is
// spelled differently is noted on the field; the registry maps one to the
// other.
//
// FOURTEEN domains from 2.0.0-lg1.2, §1.1's fourteen: the thirteen of
// 2.0.0-lg1.1 (acct alum cash cred day dog eval mig msg notif pay rpt vax) and
// `staff` (M1.21, `StaffSettingsWire`), appended at 2.0.0-lg1.2 by P02, which
// owns the rebuilt `staff_role` enum it needs (DECISIONS 47;
// design.md:6153). FIFTEEN from 6.0.0-lg5.2: `cxl` (CXL-U02, P21), appended
// over M5.07's two tables, the one domain on two (§1.1:631-632, "fifteen
// domains on sixteen tables"; `CancellationSettingsWire`). It replaces
// `GET /staff/cancel-window` and `PATCH /staff/cancel-window/:category`. Every
// `cxl` key is stored only but `per_dog_cancel_enabled`, which the owner's
// one-dog cancel has read since 6.0.0-lg5.1 (P20, where the tables landed).
// `brd`, `bt`, `pl` have no table in v1 (§3.18-3.20), and
// `cls` is no settings domain: its keys are `group_classes` columns
// (§1.1:633-635).
//
// Section-wide rules:
//   · NON-OMIT, every field. A settings wire emits every column, always. A
//     column a design line leaves NOT SEEDED is stored NULL and emitted
//     `null`, and no reader may default it (§1.1:649-650; §2.1:1777-1778).
//     Each `| null` field says on its own doc comment why it can be null.
//   · `*_time` fields are wall-clock `HH:MM` (24-hour, America/Chicago) — the
//     `time` column without seconds. `*_fraction` fields are JSON numbers in
//     [0, 1]. Counts, minutes, hours, days, months and cents are integers.
//   · Which role may edit a key (class `ops` | `money` | `price` | `roles`)
//     and which keys are inert are the server registry's
//     (`src/lib/settingsRegistry.ts`, §2.1:1779-1821), not this file's. From
//     2.0.0 the manifest SERVES both as data, key by key, with whether the
//     caller may edit each (design §2.10:4944-4947: the manifest "is read from
//     §2.1's registry … one rule with the server's"). This file types the
//     manifest's shape, never its contents. So un-inerting a key (P06, P07,
//     P09) or a change to who edits a class changes the manifest's DATA and no
//     byte here, and the portal follows with no rebuild. Doc comments below
//     give seeds, not classes — except `StaffSettingsWire`, whose keys are all
//     `roles` (owner only) and whose class §1.1:687-688 states with the shape.
//   · Two tiers for `day` and `eval` (one table each, a global row with
//     `location IS NULL` plus one row per campus; M1.07, M1.09). The staff
//     routes address one row each: `/staff/settings/day` and
//     `/staff/settings/eval` the global row, `/staff/settings/day/:location`
//     and `/staff/settings/eval/:location` that campus's row — the ledger's
//     `[/:location]` (DAY-U02) on §1.1:636-637's "`day` and `eval` take
//     `/:location`". The row wire is a union discriminated on `location`
//     (`null` = the global row's KEY), and each tier's PATCH takes only that
//     tier's columns.
//
// The staff routes (§1.1:628-649; §2.1:1850-1869), any staff role, owner
// principals 403 `forbidden`:
//   GET   /staff/settings/:domain[/:location]  → GetStaffSettingsResponse<D>
//   PATCH /staff/settings/:domain[/:location]  → PatchStaffSettingsResponse<D>
//         body PatchStaffSettingsRequest<D>, `Idempotency-Key` REQUIRED
// A `:domain` outside `SETTINGS_DOMAINS`, a `:location` on a domain other than
// `day`/`eval`, or a `:location` outside `LOCATIONS` is 400 `bad_request` —
// the path parse.
//   GET   /staff/settings/manifest  → GetStaffSettingsManifestResponse (2.0.0)
// `manifest` is a static path segment, which the router matches before
// `:domain` whatever the registration order, so it can never be a domain
// (§16 pins that). `PATCH /staff/settings/manifest` reaches the `:domain`
// route and is 400 `bad_request`, like any other unknown domain.
// The owner route (§1.1:608-627; §2.1:1870-1887):
//   GET   /settings → GetSettingsResponse (= OwnerSettingsWire)

// ---- (a) domain-local enums + tuples ---------------------------------------

/**
 * The settings domains `GET/PATCH /staff/settings/:domain` serves, by their
 * registry prefix (§1.1:628-631). Thirteen at 2.0.0-lg1.1 (DECISIONS 47);
 * `'staff'` APPENDED at 2.0.0-lg1.2 (P02), fourteen; `'cxl'` APPENDED at
 * 6.0.0-lg5.2 (P21; CXL-U02), fifteen, v1's last — new members go at the end
 * of the tuple (§1.1:590-591), so the order is alphabetical through `'vax'`
 * and append order after it. No pgEnum: the domain is a route segment, not a
 * column.
 */
export type SettingsDomain =
  | 'acct'
  | 'alum'
  | 'cash'
  | 'cred'
  | 'day'
  | 'dog'
  | 'eval'
  | 'mig'
  | 'msg'
  | 'notif'
  | 'pay'
  | 'rpt'
  | 'vax'
  | 'staff'
  | 'cxl';

/** No pgEnum (a route segment) — member order mirrors `SettingsDomain`; §16
 *  pins set equality, and pins `SettingsWireByDomain` / `SettingsPatchByDomain`
 *  to it, so a domain added here without its shapes fails `tsc`. The staff
 *  route's `:domain` parse is `z.enum(SETTINGS_DOMAINS)`. New 2.0.0-lg1.1. */
export const SETTINGS_DOMAINS = [
  'acct',
  'alum',
  'cash',
  'cred',
  'day',
  'dog',
  'eval',
  'mig',
  'msg',
  'notif',
  'pay',
  'rpt',
  'vax',
  'staff',
  'cxl',
] as const satisfies readonly [SettingsDomain, ...SettingsDomain[]];

/** `acct.locked_account_view_mode`'s value set — ACCT-U02's wire note (ledger
 *  SET-U01; design §3.15:5971 gives none). The key is NOT SEEDED. */
export type AccountLockedViewMode = 'lock_screen' | 'actions_refused';

/** The sign-up fields `acct.signup_field_requirement_map` covers — ACCT-U02's
 *  `field_key` set; `location` is §3.15:5974's "home campus". From
 *  3.0.0-lg2.1 it also types `ProfileIncompleteDetails.field_keys` and
 *  `MeWire.missing_mandatory_fields` (design §1.1:761-762 calls it
 *  `SignupFieldKey`; the existing name is kept). */
export type SignupField = 'name' | 'phone' | 'email' | 'location' | 'emergency_contact' | 'address';

/** `SignupField` in its one order: the order `field_keys` and
 *  `missing_mandatory_fields` list fields in (the map is jsonb, which keeps no
 *  key order). New 3.0.0-lg2.1; pinned in §16. */
export const SIGNUP_FIELDS = [
  'name',
  'phone',
  'email',
  'location',
  'emergency_contact',
  'address',
] as const satisfies readonly [SignupField, ...SignupField[]];

/** How one sign-up field is asked — ACCT-U02's `mode` set. */
export type SignupFieldMode = 'off' | 'asked' | 'mandatory';

/** The services `cash.due_event` keys (M1.05, design.md:6139; §3.9:5883). Not
 *  `ServiceCategory`: walk-in and event are not service categories. NO
 *  `'package'`: its one rule was `'purchase'`, which §1.1 never builds
 *  (§1.1:672, :729-730) — see `CashSettingsWire.due_event_by_service`. */
export type CashDueService =
  | 'day-school'
  | 'day-care'
  | 'group-class'
  | 'walk-in'
  | 'event'
  | 'private-lesson'
  | 'board-and-train'
  | 'boarding';

/** When an unpaid cash/check charge falls due (M1.05; §3.9:5883). No
 *  `'purchase'` (§1.1:672, :729-730). */
export type CashDueEvent =
  | 'drop-off'
  | 'first-meeting-start'
  | 'front-desk-or-pickup'
  | 'event-start'
  | 'close-out';

/** `cash.pack_partial_payment_destination`'s value set — CASH-U07's wire note
 *  (ledger SET-U01); §3.9:5885 seeds `'account-credit'`. */
export type CashPackPartialPaymentDestination = 'account-credit' | 'cash-refund';

/** How a staff reply is signed (§1.1:680-681; M1.11's CHECK,
 *  design.md:6145). */
export type ReplySignatureMode = 'staffer_first_name' | 'school_name';

/** How a notice reaches a family: push only, or push to a live device and
 *  email to a family without one (§1.1:677-678; §3.12:5920, :5925). */
export type NotificationChannelMode = 'push_only' | 'push_then_email';

/** The programs `notif.reminder_channel_by_program` keys (§1.1:677). */
export type ReminderProgram = 'day-school' | 'day-care' | 'group-class' | 'evaluation';

/** What `notif.quiet_hours_bypass_types` may list — NOTIF-U02's
 *  `QuietHoursClass` (ledger SET-U01): a notification type, or one of the two
 *  classes with no type of their own. */
export type QuietHoursClass = NotificationType | 'closure' | 'staff-reply';

/** Who a broadcast may address — NOTIF-U02's `BroadcastAudienceKind`
 *  (ledger SET-U01; §3.12:5914). */
export type BroadcastAudienceKind = 'everyone' | 'campus' | 'class' | 'day-school-families';

/** When a service is charged — `pay.charge_timing_mode`'s value set
 *  (§3.7:5833). Stored only: every v1 purchase is charged at Confirm. */
export type PaymentChargeTimingMode = 'at_confirm' | 'at_close_out';

/** Whether a service's cancel has a window — `cancellation_policy_settings
 *  .window_state` (M5.07's CHECK; design §1.1:1053, §3.8:5871): `'none'`, no
 *  window; `'hours'`, a window of `window_hours`; `'unset'`, NOT SEEDED. Stored
 *  only. New 6.0.0-lg5.2. */
export type CancellationWindowState = 'unset' | 'none' | 'hours';

/** `cxl.no_show_declare_mode`'s value set (M5.07's CHECK; §3.8:5864). Stored
 *  only. New 6.0.0-lg5.2. */
export type CancellationNoShowDeclareMode = 'staff_only' | 'auto_after_hours';

/**
 * A settings key's role class — the registry's four (design §2.1:1779-1798),
 * served on `SettingsManifestEntryWire.class`. New 2.0.0. What each class
 * means for a role, in v1: `ops` any role (STAFF-73); `money` owner and
 * manager (STAFF-77); `price` NO role, the owner included (question 27 → (a):
 * every price is its seed); `roles` the owner only. That mapping is the
 * server's (`settingsRegistry.mayEditClass`), never a client's: a client reads
 * `SettingsManifestEntryWire.editable` and never derives it from a class. No
 * pgEnum (a registry label, not a column) and no value tuple: nothing
 * iterates it. The registry's own `SettingClass` re-exports this one.
 */
export type SettingClass = 'ops' | 'money' | 'price' | 'roles';

/**
 * The catalog a *read-only here* key's value lives in — another route, a seed
 * step or a later unit edits it, never the settings PATCH (design
 * §2.10:4951-4957). The registry's `CatalogTable`, transcribed (no pgEnum:
 * these are table names). New 2.0.0, for `SettingEditorWire`'s `elsewhere`
 * arm; a client may key a link to its own screen on it.
 */
export type SettingCatalog =
  | 'credit_packages'
  | 'service_rates'
  | 'required_vaccines'
  | 'dog_descriptors'
  | 'intake_field_settings'
  | 'day_capacity';

// ---- (b) response wires ----------------------------------------------------

/**
 * The audit pair every settings row carries (§1.1:636; §2.1:1743-1744 —
 * `updated_at`, `updated_by_staff_id uuid REFERENCES staff(id) ON DELETE SET
 * NULL`). Server-stamped on every PATCH, never accepted in a body.
 */
export interface SettingsAuditWire {
  /** ISO-8601 (`pgTimestampToIso`): the row's last write; its seed time until
   *  the first edit. */
  updated_at: string;
  /** NON-OMIT: `null` while the row is still its seed, or after the editing
   *  staffer's row is deleted (`ON DELETE SET NULL`). */
  updated_by_staff_id: string | null;
}

/**
 * `GET/PATCH /staff/settings/acct` — the `account_settings` singleton (M1.01,
 * design.md:6137; keys §3.15:5968-5974). Never on the owner document
 * (§2.1:1871-1873).
 */
export interface AccountSettingsWire extends SettingsAuditWire {
  /** Days; seed 7 (§3.15:5970). */
  email_verification_grace_days: number;
  /** Seed true (§3.15:5969). */
  close_blocked_by_pending_refund_enabled: boolean;
  /** Fraction; seed 0 (§3.15:5968). */
  close_auto_refund_fraction: number;
  /** Seed false (§3.15:5973). */
  reactivation_restores_expired_value_enabled: boolean;
  /** NON-OMIT: NOT SEEDED (§3.15:5971; M1.01 `locked_account_view_mode
   *  NULL`), so `null` until staff set it, and no reader may default it. */
  locked_account_view_mode: AccountLockedViewMode | null;
  /** jsonb (M1.01). Seed `refund` for both (§3.15:5972); keys and values are
   *  ACCT-U02's. A PATCH replaces the whole object. */
  pause_reserved_service_return_mode: {
    'group-class': 'refund' | 'none';
    boarding: 'refund' | 'none';
  };
  /** jsonb, the field → mode map (M1.01); registry key
   *  `acct.signup_field_requirement_map` (§3.15:5974). Seed: `mandatory` for
   *  name, phone, email, location, emergency_contact; `asked` for address. A
   *  PATCH replaces the whole map. `email` is fixed at `mandatory` — it is the
   *  login identity (design §2.2:2244: "email is fixed in the map, not
   *  switchable") — so a PATCH that sets it to anything else is 422
   *  `invalid_payload` (3.0.0-lg2.1). Read by `PATCH /me` and
   *  `MeWire.missing_mandatory_fields` from 3.0.0-lg2.1, and by the booking
   *  pre-check when it lands (ACCT-U11). */
  signup_fields: Record<SignupField, SignupFieldMode>;
}

/**
 * `GET/PATCH /staff/settings/alum` — the `alumni_settings` singleton (M1.02,
 * design.md:6138; keys §3.11:5906-5907). Never on the owner document.
 */
export interface AlumniSettingsWire extends SettingsAuditWire {
  /** Months; seed 6 (§3.11:5906). */
  recheck_after_months_unseen: number;
  /** Seed true (§3.11:5907). */
  recheck_due_mirrors_reeval_due_enabled: boolean;
}

/**
 * `GET/PATCH /staff/settings/cash` — the `cash_settings` singleton (M1.05,
 * design.md:6139; keys §3.9:5881-5886). Every column stored only (R2). Never
 * on the owner document. No `cash_due_event_settings` table exists.
 */
export interface CashSettingsWire extends SettingsAuditWire {
  /** Seed true (§3.9:5886). */
  unpaid_checkout_block_enabled: boolean;
  /** Seed false (§3.9:5884). */
  pack_grant_on_promise_enabled: boolean;
  /** Hours; seed 24 (§3.9:5882). */
  did_not_pay_undo_window_hours: number;
  /** Seed `'account-credit'` (§3.9:5885). */
  pack_partial_payment_destination: CashPackPartialPaymentDestination;
  /** Cents; seed 0 (§3.9:5881). */
  bounced_check_fee_cents: number;
  /**
   * jsonb, one typed record (§1.1:672; M1.05); registry key `cash.due_event`
   * (§3.9:5883). Seed: day-school and day-care `'drop-off'`, group-class
   * `'first-meeting-start'`, walk-in `'front-desk-or-pickup'`, event
   * `'event-start'`, private-lesson and board-and-train `'close-out'`.
   * NON-OMIT inside the record: `boarding` is `null`, NOT SEEDED. NO
   * `package` key and no `'purchase'` event: §1.1:672 and :729-730 never
   * build that rule, although §3.9:5883 and M1.05 still seed "package
   * purchase" — an open disagreement, P01-contract notes item D1. A PATCH
   * replaces the whole record and is refused as one key (no per-row refusal).
   */
  due_event_by_service: Record<CashDueService, CashDueEvent | null>;
}

/**
 * `GET/PATCH /staff/settings/cred` — the `credit_settings` singleton (M1.06,
 * design.md:6140), exactly §1.1:663-667's ten keys in its order; no clawback
 * column, no hand-grant cap (R3, A11). The owner document carries four of
 * them (`OwnerCreditSettingsWire`).
 */
export interface CreditSettingsWire extends SettingsAuditWire {
  /** Seed TRUE: credits expire in the pilot (§3.5:5790; answer 3). */
  expiry_enforced_enabled: boolean;
  /** Days before a lot's expiry, one notice per lead; seed `[7]`
   *  (§3.5:5791). This table is its one store (q35 → (b)). Never empty and
   *  no repeats: a PATCH of `[]` or `[7, 7]` is 422 `invalid_payload`
   *  (DECISIONS 61; an empty list would silently warn no family). Each lead
   *  at most 365 (5.0.0-lg4.2). */
  expiry_warning_lead_days: number[];
  /** Months, 1 to 120; seed 1 (§3.5:5793; the bounds, 5.0.0-lg4.2). */
  manual_grant_expiry_months: number;
  /** Months of fresh expiry for a returned credit whose lot can pay no later
   *  date, 0 to 120; seed 1; 0 = every return goes into its old lot (§3.5:5804;
   *  the bounds, 5.0.0-lg4.2). */
  returned_credit_expiry_months: number;
  /** Seed false (§3.5:5788). */
  booking_outlives_lot_expiry_enabled: boolean;
  /** The `count` a single-day purchase may carry, 1 to 100; seed 30 (§3.5:5805;
   *  the bounds, 5.0.0-lg4.2). It binds
   *  `POST /credit-packages/:key/purchase` and the desk sale, not a booking's
   *  `top_up`. */
  single_day_purchase_max_count: number;
  /** Seed true (§3.5:5787). */
  account_deletion_expires_credits_enabled: boolean;
  /** Seed false (§3.5:5789). */
  dispute_auto_reversal_enabled: boolean;
  /** Days; seed 1 (§3.5:5803). */
  pause_daily_expiry_extension_days: number;
  /** Seed false (§3.5:5806). */
  unpaid_payment_auto_reversal_enabled: boolean;
}

/**
 * One service's offering at one campus — an entry of the campus day row's
 * `offerings jsonb` (M1.07, design.md:6141; E03, §2.6:3719-3721). Shared by
 * the staff `DayProgramCampusSettingsWire` and the owner document.
 *
 * `name` and `description` are one line each, with a length cap from 2.0.0
 * (P01 r3 Opus L3: uncapped, a PATCH could store text that `GET /settings`
 * serves uncached to every owner). A string value must: hold no C0 control
 * character, LF and TAB included (DECISIONS 71), so it is single-line; not be
 * blank (empty or whitespace only) — send `null` to clear one; and be at most
 * 60 characters (`name`) or 280 (`description`), counted in Unicode code
 * points, as Postgres `char_length` counts. A PATCH of `offerings` breaking any
 * of these is 422 `invalid_payload` (refusal step 4), naming the
 * `<service>.name` or `<service>.description` at fault. Server validation
 * only, no CHECK: the jsonb has one writer, the settings PATCH. The manifest
 * serves both caps (`SettingValueSpecWire`, arm `offerings`), and an editor
 * reads them from there.
 */
export interface ServiceOfferingWire {
  /** Seed false for boarding, board-and-train and private-lesson at both
   *  campuses and for day-care at Fayetteville; true for the rest
   *  (§2.6:3719-3721). Editable by any role, so turning one on is a
   *  deliberate act in the settings editor (§2.6:3722; DECISIONS 69). */
  offered: boolean;
  /** Whether the owner app shows the tile; seeded as `offered`
   *  (§2.6:3719-3721). */
  client_visible: boolean;
  /** NON-OMIT: display name. `null` = NOT SEEDED — no design line gives the
   *  seed text (P01-contract notes item D6). At most 60 characters, one line,
   *  never blank (see the type). */
  name: string | null;
  /** NON-OMIT: as `name`. At most 280 characters, one line, never blank. */
  description: string | null;
}

/**
 * `GET/PATCH /staff/settings/day` — the GLOBAL row of `day_program_settings`
 * (`location IS NULL`; M1.07, design.md:6141; the `g`-scoped keys of
 * §3.4:5751-5781).
 */
export interface DayProgramGlobalSettingsWire extends SettingsAuditWire {
  /** NON-OMIT: always `null` — the global row's key, not an absence. */
  location: null;
  /** Months; seed 3 (§3.4:5760). */
  booking_horizon_months: number;
  /** Dogs; seed 5 (§3.4:5773). */
  max_dogs_per_booking_count: number;
  /** Minutes; seed 20 (§3.4:5765). */
  day_school_one_on_one_minutes: number;
  /** Cents; seed 0, on the global row (§3.4:5757; §2.1:1767-1768). The one
   *  day price — there is no day-school price anywhere (R1). */
  after_school_price_cents: number;
  /** Seed `17:00` (§3.4:5775). */
  occupied_block_end_time: string;
  /** Fraction; seed 1 (§3.4:5774). */
  midstay_day_charge_fraction: number;
  /** Fraction; seed 1 (§3.4:5781). The credits a turn-away, *Didn't come* and
   *  an unmarked send-home return, read from 6.0.0-lg5.1. A PATCH refuses any
   *  value but 0 or 1, as on the next key (§2.3:2482-2483; question 20 (a)). */
  sent_home_before_training_return_fraction: number;
  /** Fraction; seed 0; a PATCH refuses any value but 0 or 1 (§3.4:5780). The
   *  credits a send-home marked finished returns, read from 6.0.0-lg5.1. */
  sent_home_after_training_return_fraction: number;
  /** Fraction; seed 1 (§3.4:5762). */
  closure_return_fraction: number;
}

/**
 * `GET/PATCH /staff/settings/day/:location` — one CAMPUS row of
 * `day_program_settings` (M1.07, design.md:6141; the `c`-scoped keys of
 * §3.4:5751-5781, plus E03's `offerings`). No day-school price column (R1)
 * and no `capacity_override_dogs` column: that key's store is the per-date
 * `day_capacity` row (§2.3:2305-2308; P01-contract notes item D3), edited by
 * `PUT` and `DELETE /staff/day-capacity/:location/:date`.
 *
 * A PATCH that lowers `daily_capacity_dogs` or unticks a weekday from
 * `open_weekdays_list` can answer 422 `capacity_below_booked` (4.0.0-lg3.1;
 * refusal step 5, `PatchStaffSettingsRequest`).
 */
export interface DayProgramCampusSettingsWire extends SettingsAuditWire {
  /** NON-OMIT: the campus this row belongs to. */
  location: LocationKey;
  /** jsonb, every service at this campus (E03). A PATCH replaces the whole
   *  map, all seven services. */
  offerings: Record<ServiceCategory, ServiceOfferingWire>;
  // No `day_school_offered_flag` / `daycare_offered_flag` columns: whether
  // day school or daycare runs at a campus has ONE store, `offerings[service]
  // .offered` (one value, one store, §2.1:1825; DECISIONS 53, D2). The §3.4
  // keys `day.day_school_offered_flag` (:5764) and `day.daycare_offered_flag`
  // (:5767) are registry aliases into this map.
  /** ISO-8601 weekdays, 1 = Monday … 7 = Sunday (Postgres `isodow`); seed
   *  `[1, 2, 3, 4, 5]`, Monday to Friday (§3.4:5776). */
  open_weekdays_list: number[];
  /** Seed `07:30` (§3.4:5769). */
  dropoff_open_time: string;
  /** Seed `08:30` (§3.4:5768). */
  dropoff_close_time: string;
  /** Seed `16:30` (§3.4:5778). */
  pickup_open_time: string;
  /** Seed `17:30`; also the *Didn't come* clock (§3.4:5777). */
  pickup_close_time: string;
  /** Seed `07:30` (§3.4:5779). */
  same_day_cutoff_time: string;
  /** Dogs; seed 15 (§3.4:5763). */
  daily_capacity_dogs: number;
  /** Seed `17:30` (§3.4:5770). */
  late_pickup_call_time: string;
  /** Cents; seed 0 (§3.4:5771). */
  late_pickup_fee_cents: number;
  /** Minutes; seed 0 (§3.4:5772). */
  late_pickup_grace_minutes: number;
  /** Seed `17:30` (§3.4:5758). */
  after_school_start_time: string;
  /** Seed `18:30` (§3.4:5756). */
  after_school_end_time: string;
  /** Dogs; seed 10 at Fayetteville, 5 at Bentonville (§3.4:5755). */
  after_school_capacity_count: number;
}

/** A `day_program_settings` row, either tier — discriminate on `location`
 *  (`null` = global). The ledger's name (§1.1:655). Which arm a route returns
 *  is fixed by its path (see the section header). */
export type DayProgramSettingsWire = DayProgramGlobalSettingsWire | DayProgramCampusSettingsWire;

/**
 * `GET/PATCH /staff/settings/dog` — the `dog_gate_settings` singleton (M1.08,
 * design.md:6142: "as DOG-U02 wrote it" plus E01's four gate booleans and
 * `card_required_for_evaluation_booking_enabled`). No `descriptor_list`
 * column (`dog_descriptors` is that store), no `intake_field_override_mode`,
 * and no `evaluation_gated_categories` until M2.04 lands it (§3.1:5709).
 * `DOG-U03`'s `BookingRuleWire` and its routes are never built (§1.1:660-662).
 */
export interface DogGateSettingsWire extends SettingsAuditWire {
  /** Months; seed 6 (§3.1:5720). */
  spay_neuter_required_by_age_months: number;
  /** Seed `['day-school', 'day-care']`; registry key
   *  `dog.spay_neuter_gated_service_list` (§3.1:5718). */
  spay_neuter_gated_categories: ServiceCategory[];
  /** Seed `09:00` (§3.1:5719). */
  spay_neuter_reminder_time: string;
  /** Seed true; registry key `dog.card_required_at_board_train_confirm_enabled`
   *  (§3.1:5707). */
  card_required_at_board_train_confirm: boolean;
  /** Seed TRUE (§1.1:661; §3.1:5708; 05- #8) — DOG-U02's nullable
   *  `card_required_for_evaluation_booking` and M1.08's positional NULL are
   *  superseded (P01-contract notes item D4). */
  card_required_for_evaluation_booking_enabled: boolean;
  /** Seed `['custom']`; registry key `dog.gate_override_allowed_gate_list`
   *  (§3.1:5714). */
  gate_override_allowed_gate_keys: string[];
  /** Seed `['card-on-file']`; registry key `dog.staff_dog_exempt_gate_list`
   *  (§3.1:5721). */
  staff_dog_exempt_gate_keys: string[];
  /** Seed true (§3.1:5712; E01). */
  gate_card_on_file_enabled: boolean;
  /** Seed true (§3.1:5713; E01). */
  gate_evaluation_enabled: boolean;
  /** Seed true (§3.1:5715; E01). */
  gate_vaccines_enabled: boolean;
  /** Seed true (§3.1:5711; E01). */
  gate_agreements_enabled: boolean;
}

/**
 * `GET/PATCH /staff/settings/eval` — the GLOBAL row of `evaluation_settings`
 * (`location IS NULL`; M1.09, design.md:6143, two tiers with tier CHECKs).
 * No price column — `eval.price_cents` is the campus's evaluation
 * `service_rates` row (§1.1:673-675) — and no
 * `verdict_correction_window_hours` (onboarding cut 4).
 */
export interface EvaluationGlobalSettingsWire extends SettingsAuditWire {
  /** NON-OMIT: always `null` — the global row's key, not an absence. */
  location: null;
  /** Months; seed 3 (§3.2:5730). NON-OMIT: `null` switches the
   *  re-evaluation clock off (EVAL-53; DECISIONS 62). Inert until S14. */
  reeval_after_months_unseen: number | null;
  /** Hours; seed 0 = off (§3.2:5727). */
  failed_rebook_wait_hours: number;
}

/** `GET/PATCH /staff/settings/eval/:location` — one CAMPUS row of
 *  `evaluation_settings` (M1.09). */
export interface EvaluationCampusSettingsWire extends SettingsAuditWire {
  /** NON-OMIT: the campus this row belongs to. */
  location: LocationKey;
  /** NON-OMIT: `null` = no daily limit, which IS the seed (§3.2:5728;
   *  M1.09 `max_per_day_dogs NULL`) — a seeded meaning, not NOT SEEDED. */
  max_per_day_dogs: number | null;
}

/** An `evaluation_settings` row, either tier — discriminate on `location`
 *  (`null` = global). The ledger's name (§1.1:657). */
export type EvaluationSettingsWire = EvaluationGlobalSettingsWire | EvaluationCampusSettingsWire;

/**
 * `GET/PATCH /staff/settings/mig` — the `migration_settings` singleton
 * (M1.10, design.md:6144; keys §3.16:5980-5988). No
 * `invite_link_lifetime_days` (q103, E39) and no expiry-anchor column. Never
 * on the owner document.
 */
export interface MigrationSettingsWire extends SettingsAuditWire {
  /** Families; seed 5, a ceiling (§3.16:5988). */
  pilot_family_count: number;
  /** Months; seed 1 (§3.16:5980). */
  full_transfer_after_pilot_months: number;
  /** Seed true (§3.16:5982). */
  import_credit_balances_enabled: boolean;
  /** Months; seed 1 (§3.16:5985). */
  imported_credit_expiry_months: number;
  /** Seed true (§3.16:5983). */
  import_unpaid_balances_enabled: boolean;
  /** Months; seed 12 (§3.16:5987). */
  invite_recent_within_months: number;
  /** Seed 1 (§3.16:5981). */
  gingr_retention_billing_cycles: number;
}

/**
 * `GET/PATCH /staff/settings/msg` — the `messaging_settings` singleton
 * (M1.11, design.md:6145; columns MSG-U02's, in its seed order, plus
 * `reply_signature_mode`), and the two responder first names, resolved on the
 * server (§1.1:680-682) — the only two fields on a settings wire that are not
 * columns, so neither is in a PATCH body.
 */
export interface MessagingSettingsWire extends SettingsAuditWire {
  /** Seed false; registry key `msg.referral_subtopic_enabled_flag`
   *  (§3.13:5934). */
  referral_subtopic_enabled: boolean;
  /** NON-OMIT: `null` until `npm run staff:provision` sets it (to Amber's
   *  row), and again after `--expire` of that staffer (§3.13:5939;
   *  §2.1:2007-2021). */
  school_default_responder_staff_id: string | null;
  /** NON-OMIT: as above, set to Shanthi's row (§3.13:5937). */
  school_backup_responder_staff_id: string | null;
  /** Seed false; registry key `msg.school_default_responder_out_flag`
   *  (§3.13:5938). */
  school_default_responder_out: boolean;
  /** Seconds; seed 60 (§3.13:5940). */
  video_max_duration_seconds: number;
  /** Megabytes; seed 100 (§3.13:5941). */
  video_max_size_mb: number;
  /** Seed 10; registry key `msg.max_attachments_per_message_count`
   *  (§3.13:5932). */
  max_attachments_per_message: number;
  /** Characters; seed 4000 (§3.13:5933). */
  max_text_length_chars: number;
  /** Hours; seed 24 (§3.13:5936). */
  request_reply_window_hours: number;
  /** Seed `'staffer_first_name'` (§3.13:5935; M1.11). */
  reply_signature_mode: ReplySignatureMode;
  /** NOT A COLUMN — that staffer's first name, resolved on the server from
   *  the staff row `school_default_responder_staff_id` names (§1.1:682,
   *  MSG-U02). NON-OMIT: `null` exactly when that id is `null`. */
  school_default_responder_first_name: string | null;
  /** NOT A COLUMN — as above, from `school_backup_responder_staff_id`. */
  school_backup_responder_first_name: string | null;
}

/**
 * `GET/PATCH /staff/settings/notif` — the `notification_settings` singleton
 * (M1.12, design.md:6146; columns NOTIF-U02's, in its seed order, plus the
 * four §1.1:675-680 bears at birth). No `push_receipt_check_delay_minutes`.
 */
export interface NotificationSettingsWire extends SettingsAuditWire {
  /** Seed `21:00` (§3.12:5924). */
  quiet_hours_start_time: string;
  /** Seed `08:00` (§3.12:5923). */
  quiet_hours_end_time: string;
  /** Seed `['payment-failed', 'closure', 'staff-reply']` (§3.12:5922). */
  quiet_hours_bypass_types: QuietHoursClass[];
  /** Seed `08:00` (§3.12:5926). */
  scan_send_time: string;
  /** Hours; seed 24 (§3.12:5913). */
  booking_reminder_lead_hours: number;
  /** Days; seed 7 (§3.12:5915). */
  card_expiry_warning_days_before: number;
  /** NON-OMIT: `null` until Allison supplies the school's address (the
   *  preflight refuses it null) — §3.12:5918; M1.12 "NULL sender". */
  email_sender_address: string | null;
  /** Seed `['everyone', 'campus', 'class', 'day-school-families']`
   *  (§3.12:5914). */
  broadcast_audience_list: BroadcastAudienceKind[];
  /** Hours; seed 24 (§3.12:5916). */
  cash_payment_due_reminder_lead_hours: number;
  /** Seed `'NWA School for Dogs'` (§3.12:5919). */
  email_sender_display_name: string;
  /** jsonb (M1.12). Seed day-school `'push_only'`; day-care, group-class and
   *  evaluation `'push_then_email'` (§3.12:5925). A PATCH replaces the whole
   *  record. */
  reminder_channel_by_program: Record<ReminderProgram, NotificationChannelMode>;
  /** Seed `'push_then_email'` (§3.12:5920). */
  expiry_notice_channel: NotificationChannelMode;
  /** Minutes; seed 5 (§3.12:5917). */
  email_inflight_alarm_minutes: number;
}

/**
 * The `value` each `payment_settings` key holds, by key (M1.13,
 * design.md:6147, seeded whole; keys §3.7:5830-5841). Every key's scope is
 * `'global'` except `charge_timing_mode`, one row per service. No
 * `refund_any_staff_limit_cents`, and `pay.auto_renew_enabled` (per package)
 * is not a row here.
 */
export interface PaymentSettingValueByKey {
  /** Seed 3, bounded 1..5 (§3.7:5832). */
  card_attempts_max_count: number;
  /** Minutes; seed 2, bounded 1..5 (§3.7:5841). */
  seat_hold_max_minutes: number;
  /** Minutes; seed 10, bounded 1..60 (§3.7:5838). */
  processing_hold_max_minutes: number;
  /** Seed `['vet-bill', 'damage', 'other']` (§3.7:5834; M1.13). An invoice
   *  kind is a string checked against this list. */
  custom_invoice_kind_list: string[];
  /** Seed `['vet-bill', 'damage']` (§3.7:5835; M1.13). */
  custom_invoice_card_kind_list: string[];
  /** Cents; seed 0 = owner and manager only (§3.7:5839). Editable by the
   *  owner and the manager (`money` class, §3.7): Allison's 11-02 answer,
   *  "Shanthi or Amber" (DECISIONS 73). */
  refund_any_role_limit_cents: number;
  /** Days; seed 30 (§3.7:5837). */
  price_change_notice_days: number;
  /** Seed 30 (§3.7:5836). */
  max_sessions_per_booking_count: number;
  /** Seed `'original_card'`, the one value any design line names
   *  (§3.7:5831). */
  automatic_return_instrument_mode: 'original_card';
  /** One row per service (scope = the service): `'at_confirm'` for
   *  day-school, group-class, package, retail, event; `'at_close_out'` for
   *  private-lesson and board-and-train; no boarding row, no day-care row
   *  (§3.7:5833; M1.13). */
  charge_timing_mode: PaymentChargeTimingMode;
}

/** A `payment_settings` key (M1.13's ten). */
export type PaymentSettingKey = keyof PaymentSettingValueByKey;

/**
 * One `payment_settings` row (PAY-U02's shape, `(key, scope, value jsonb)`,
 * PRIMARY KEY `(key, scope)`; §2.1:1756-1759). `GET/PATCH
 * /staff/settings/pay` returns EVERY row, so the domain's response is
 * `PaymentSettingWire[]` (the ledger's singular name, §1.1:658). A union
 * discriminated on `key`: narrowing `key` types `value`.
 */
export type PaymentSettingWire = {
  [K in PaymentSettingKey]: {
    key: K;
    /** `'global'` for an org-wide row — never null (§1.1:650-651); the
     *  service for a `charge_timing_mode` row. Not `ServiceCategory`:
     *  `package`, `retail` and `event` are scopes too. */
    scope: string;
    value: PaymentSettingValueByKey[K];
    updated_at: string;
    /** NON-OMIT: as `SettingsAuditWire.updated_by_staff_id`. */
    updated_by_staff_id: string | null;
  };
}[PaymentSettingKey];

/**
 * `GET/PATCH /staff/settings/rpt` — the `reports_settings` singleton (M1.15,
 * design.md:6148; columns RPT-U02's, in its seed order). `curriculum_levels`
 * is M9.03's table, not here.
 */
export interface ReportsSettingsWire extends SettingsAuditWire {
  /** Seed false; registry key `rpt.events_enabled_flag` (§3.17:5997). */
  events_enabled: boolean;
  /** Dogs; seed 5; registry key `rpt.event_max_dogs_per_rsvp_count`
   *  (§3.17:5995). */
  event_max_dogs_per_rsvp: number;
  /** Seed false; registry key `rpt.gallery_enabled_flag` (§3.17:5998). */
  gallery_enabled: boolean;
  /** Dogs; seed 60; registry key `rpt.gallery_max_dogs_count` (§3.17:5999). */
  gallery_max_dogs: number;
  /** Seed 60, a labelled PLACEHOLDER; registry key
   *  `rpt.gallery_rate_limit_requests_per_minute` (§3.17:6000). */
  gallery_rate_limit_per_minute: number;
  /** Seed 25, `CHECK BETWEEN 1 AND 25` (25 = `MAX_UPLOAD_BYTES`): it can only
   *  be lowered in v1 (§3.17:6001; M1.15). */
  media_max_upload_megabytes: number;
}

/**
 * `GET/PATCH /staff/settings/vax` — the `vaccine_settings` singleton (M1.16,
 * design.md:6149; columns VAX-U08's). The other `vax.*` keys are columns or
 * rows of `required_vaccines` (§3.3:5733-5747), not of this table.
 */
export interface VaccineSettingsWire extends SettingsAuditWire {
  /** MIME types; seed `['application/pdf', 'image/jpeg', 'image/png',
   *  'image/heic', 'image/heif']` (M1.16) — "PDF and photo"; registry key
   *  `vax.proof_file_type_list` (§3.3:5740). */
  proof_file_types: string[];
  /** Months; seed 4 (§3.3:5742). */
  typical_full_vaccination_age_months: number;
}

/**
 * `GET/PATCH /staff/settings/staff` — the `staff_settings` singleton (M1.21,
 * design.md:6153; keys §3.14:5947-5952; shape §1.1:685-694). New
 * 2.0.0-lg1.2 (P02; STAFF-U07, PAY-U25, CASH-U20). Never on the owner
 * document.
 *
 * Who may do each money verb, as data. A role passes a verb's guard (read at
 * the verb, when each lands at design 5.0.0 and later) when it is `owner` OR is
 * on that verb's list: the
 * owner role passes every verb whatever the lists hold (STAFF-09), so a list
 * without `'owner'` still lets the owner through. `StaffMeWire.capabilities`
 * mirrors each list for the caller. Each list is NON-EMPTY (a
 * `CHECK (cardinality(…) > 0)` per column), so an empty list in a PATCH is
 * 422 `invalid_payload`; a member outside `StaffRole`, or a role repeated in one
 * list, is 400 `bad_request` (build DECISIONS 59). Read each list as a set:
 * order carries no meaning.
 *
 * Every field here is a `roles`-class key (§1.1:687-688; §3.14:5954-5956):
 * only the owner role may PATCH it, and a manager's or a trainer's PATCH
 * naming any of them is 403 `forbidden` + `RefusedKeysDetails`. Any staff
 * role may GET it, as every settings domain. This domain is the one whose
 * class this file states, because every one of its keys has the same class
 * and the design states it with the shape; the registry stays the authority.
 */
export interface StaffSettingsWire extends SettingsAuditWire {
  /** Who refunds money, any amount up to what was paid; also the end-of-day
   *  *Returned* action. Seed `['owner', 'manager']`; registry key
   *  `staff.refund_role_list` (§3.14:5947; F2, R4, answer 11). Mirrored by
   *  `capabilities.refund_money`, which is true for every role while
   *  `pay.refund_any_role_limit_cents` is above 0. Its verbs land at design
   *  6.0.0. */
  refund_roles: StaffRole[];
  /** Who adds or removes credits by hand and moves a lot's expiry. Seed
   *  `['owner', 'manager']`; registry key `staff.credit_hand_edit_role_list`
   *  (§3.14:5948; A11, R4). Mirrored by `capabilities.edit_credits`. Read at
   *  the three verbs it names there. */
  credit_hand_edit_roles: StaffRole[];
  /** Who records a cash or check desk sale, and *Mark paid* on an open custom
   *  invoice. Seed `['owner', 'manager', 'trainer']`; registry key
   *  `staff.desk_sale_role_list` (§3.14:5949; A7, A10, s12). Mirrored by
   *  `capabilities.desk_sale`. Its verbs land at design 6.1.0. */
  desk_sale_roles: StaffRole[];
  /** Who raises, charges and voids a custom invoice. Seed
   *  `['owner', 'manager']`; registry key `staff.custom_invoice_role_list`
   *  (§3.14:5950; R8, s14, s18). Mirrored by `capabilities.custom_invoice`.
   *  Its verbs land at design 6.1.0. */
  custom_invoice_roles: StaffRole[];
  /** Who sees the end-of-day sheet's totals. Seed
   *  `['owner', 'manager', 'trainer']`; registry key
   *  `staff.cash_day_totals_role_list` (§3.14:5951; s15, SIGNOFF.md:118: "any
   *  memeber for now, but later we may have roles for viewing"). Mirrored by
   *  `capabilities.cash_day_totals`. The sheet lands at design 6.1.0. */
  cash_day_totals_roles: StaffRole[];
  /** Minutes with no key or pointer event before the portal signs its
   *  staffer out, at the shared front-desk computer. Integer, seed 30,
   *  `CHECK BETWEEN 1 AND 60`, so 61 is 422 `invalid_payload`; registry key
   *  `staff.portal_idle_signout_minutes` (§3.14:5952; M1.21). Read by the
   *  portal's idle sign-out (STAFF-U11, design §2.10:4641-4650). */
  portal_idle_signout_minutes: number;
}

/**
 * One service's cancellation policy, a row of `cancellation_policy_settings`
 * (M5.07; design §1.1:1050-1061, §2.7:4115-4126, §3.8:5849-5871; CXL-U02). New
 * 6.0.0-lg5.2. One row per `ServiceCategory`, seven, the evaluation's included
 * (§3.8:5855, "one row per service and one for the evaluation"). STORED ONLY:
 * no v1 code reads any column here (money cut 3; 12-:67-69 "no true penalty"),
 * so no cancel forfeits, withholds or warns, and a PATCH naming any of them is
 * 422 `setting_inert`. Seeds: `window_state` `'none'`, `window_hours` `null`,
 * both fractions 0, `flat_fee_cents` 0, `unpaid_no_show_close_after_hours` 24
 * and `no_show_declare_mode` `'staff_only'` on every row but boarding's, which
 * is `'unset'` with its fractions, fee and declare mode NOT SEEDED and its
 * hours 24. NON-OMIT, every field: `null` = NOT SEEDED, and no reader may
 * default it.
 */
export interface CancellationPolicyWire extends SettingsAuditWire {
  category: ServiceCategory;
  window_state: CancellationWindowState;
  /** Hours before the session, at least 1; `null` on every seeded row
   *  (§3.8:5871). */
  window_hours: number | null;
  /** Fraction (§3.8:5863). */
  forfeit_fraction: number | null;
  /** Fraction (§3.8:5865). */
  no_show_forfeit_fraction: number | null;
  /** Cents (§3.8:5862). */
  flat_fee_cents: number | null;
  /** Hours, at least 1 (§3.8:5870). */
  unpaid_no_show_close_after_hours: number;
  /** §3.8:5864. */
  no_show_declare_mode: CancellationNoShowDeclareMode | null;
}

/**
 * The `cancellation_global_settings` singleton (M5.07; design §1.1:1055-1058,
 * §3.8:5861-5869; CXL-U02). New 6.0.0-lg5.2. Stored only but
 * `per_dog_cancel_enabled`. NON-OMIT: `null` = NOT SEEDED.
 */
export interface CancellationGlobalPolicyWire extends SettingsAuditWire {
  /** Seed true (§3.8:5866; s11). The one live `cxl` key: while it is false the
   *  owner's `POST /bookings/:id/dogs/:dogId/cancel` answers 409
   *  `per_dog_cancel_off` and her `dog_shares[].can_cancel` reads `false`; a
   *  staff cancel ignores it. Read since 6.0.0-lg5.1, editable from
   *  6.0.0-lg5.2. */
  per_dog_cancel_enabled: boolean;
  /** Seed true (§3.8:5867). Stored only. */
  staff_entered_client_cancel_follows_owner_rules_enabled: boolean;
  /** Seed true (§3.8:5868). Stored only. */
  staff_initiated_cancel_full_return_enabled: boolean;
  /** NOT SEEDED (§3.8:5861; answer 13: a missed or called-off class meeting
   *  returns nothing). No value set is designed. Stored only. */
  class_missed_meeting_money_return_mode: string | null;
  /** NOT SEEDED (§3.8:5869). No value set is designed. Stored only. */
  started_run_cancel_return_mode: string | null;
}

/**
 * `GET/PATCH /staff/settings/cxl` — the `cxl` domain over M5.07's two tables
 * (design §1.1:1050-1061; CXL-U02). New 6.0.0-lg5.2. Never on the owner
 * document (§3.8:5852). It replaces `GET /staff/cancel-window`, `PATCH
 * /staff/cancel-window/:category`, `CancelWindowSettingWire` and
 * `PatchStaffCancelWindowRequest`, removed: M5.08 drops their table.
 *
 * `policies` holds every `cancellation_policy_settings` row, in no promised
 * order (key them by `category`); `global` is the singleton. Each carries its
 * own audit pair. The stored-only editor: every key is inert but
 * `per_dog_cancel_enabled` (§3.8:5851-5853).
 */
export interface CancellationSettingsWire {
  policies: CancellationPolicyWire[];
  global: CancellationGlobalPolicyWire;
}

/**
 * What `GET` and `PATCH /staff/settings/:domain[/:location]` return, by
 * domain (§1.1:635-636: "each returning its `<Domain>SettingsWire`"). `day`
 * and `eval` return the global arm on the bare path and the campus arm on
 * `/:location`; `pay` returns every row; `cxl` both of its tables. §16 pins
 * this map's keys to `SettingsDomain`.
 */
export interface SettingsWireByDomain {
  acct: AccountSettingsWire;
  alum: AlumniSettingsWire;
  cash: CashSettingsWire;
  cred: CreditSettingsWire;
  day: DayProgramSettingsWire;
  dog: DogGateSettingsWire;
  eval: EvaluationSettingsWire;
  mig: MigrationSettingsWire;
  msg: MessagingSettingsWire;
  notif: NotificationSettingsWire;
  pay: PaymentSettingWire[];
  rpt: ReportsSettingsWire;
  vax: VaccineSettingsWire;
  staff: StaffSettingsWire;
  cxl: CancellationSettingsWire;
}

/** `GET /staff/settings/:domain[/:location]` response (200) — the domain's
 *  current row(s), read from Postgres. Any staff role reads every key. */
export type GetStaffSettingsResponse<D extends SettingsDomain = SettingsDomain> =
  SettingsWireByDomain[D];

/** `PATCH /staff/settings/:domain[/:location]` response (200) — the same
 *  shape as the GET, read back after the write in the same transaction. A
 *  replay of a completed `Idempotency-Key` returns the original body. */
export type PatchStaffSettingsResponse<D extends SettingsDomain = SettingsDomain> =
  SettingsWireByDomain[D];

/** The owner document's per-campus `day` keys (§1.1:612-613). */
export type OwnerDayCampusSettingsWire = Pick<
  DayProgramCampusSettingsWire,
  | 'open_weekdays_list'
  | 'dropoff_open_time'
  | 'dropoff_close_time'
  | 'pickup_open_time'
  | 'pickup_close_time'
  | 'same_day_cutoff_time'
  | 'after_school_start_time'
  | 'after_school_end_time'
  | 'late_pickup_call_time'
>;

/** The owner document's `day` section (§1.1:612-615): the global keys
 *  (horizon, max dogs per booking, one-on-one minutes, after-school price)
 *  and each campus's keys. **Never a day-school price** — the $60 is the two
 *  single-day catalog rows (R1). */
export type OwnerDaySettingsWire = Pick<
  DayProgramGlobalSettingsWire,
  | 'booking_horizon_months'
  | 'max_dogs_per_booking_count'
  | 'day_school_one_on_one_minutes'
  | 'after_school_price_cents'
> & {
  by_location: Record<LocationKey, OwnerDayCampusSettingsWire>;
};

/** The owner document's `gates` section — E01's four switches, read from
 *  `dog_gate_settings.gate_*_enabled`, under §1.1:615's names. */
export interface OwnerGateSettingsWire {
  card_on_file: boolean;
  evaluation: boolean;
  vaccines: boolean;
  agreements: boolean;
}

/** One campus's evaluation price on the owner document (§1.1:616-617). */
export interface OwnerEvaluationCampusSettingsWire {
  /** Cents, read from the row `GET /rates` (category `evaluation`, this
   *  location) selects — the price's one store (C8); `evaluation_settings`
   *  holds no price. NON-OMIT: `null` where that read would 404. M3.05 seeds
   *  both campuses, so that takes a closed or voided row — a campus with no
   *  row emits `null`, never a default. */
  price_cents: number | null;
}

/** The owner document's `eval` section (§1.1:616-617). */
export type OwnerEvaluationSettingsWire = Pick<
  EvaluationGlobalSettingsWire,
  'reeval_after_months_unseen'
> & {
  by_location: Record<LocationKey, OwnerEvaluationCampusSettingsWire>;
};

/**
 * The owner document's `cred` section (§1.1:617-619; §2.1:1883-1884: the app
 * words "1 credit, expires 19 Oct" and the 7-day notice from the first two).
 *
 * 5.0.0 adds two more, read from the same `credit_settings` row (build
 * DECISIONS 216; P18 mobile G5, G6):
 *   - `booking_outlives_lot_expiry_enabled`: while true, a credit pays a date
 *     past its lot's expiry, so the calendar greys no date as "no credit
 *     reaches this date" (design §2.4:3184-3187) and the server sends no
 *     `credit_expired_before_date`.
 *   - `single_day_purchase_max_count`: the most single days one purchase's
 *     `count` may carry (`PostCreditPackagesPurchaseRequest`), so the shop's
 *     stepper stops there rather than meeting 422 `count_not_allowed`.
 */
export type OwnerCreditSettingsWire = Pick<
  CreditSettingsWire,
  | 'expiry_enforced_enabled'
  | 'expiry_warning_lead_days'
  | 'booking_outlives_lot_expiry_enabled'
  | 'single_day_purchase_max_count'
>;

/** One class on the owner document's `cls` section (§1.1:619-620: per class,
 *  price, weeks, capacity; no age limits, no default schedule). Read from
 *  today's live `group_classes` row (`schema.sql:489-499`) under its column
 *  names; design 7.0.0's S36 moves the price per campus to
 *  `group_class_prices` (M7.02, M7.07), which re-types this entry then. */
export interface OwnerClassSettingsWire {
  key: GroupClassKey;
  /** Cents per dog. */
  price_per_dog_cents: number;
  weeks: number;
  capacity: number;
}

/** The owner document's `msg` section — reply window, referral subtopic flag,
 *  limits (§1.1:620-621); no responder, no sign-off. */
export type OwnerMessagingSettingsWire = Pick<
  MessagingSettingsWire,
  | 'request_reply_window_hours'
  | 'referral_subtopic_enabled'
  | 'max_attachments_per_message'
  | 'max_text_length_chars'
  | 'video_max_duration_seconds'
  | 'video_max_size_mb'
>;

/** The owner document's `notif` section — the reminder lead and the three
 *  quiet-hours keys, served but read by nothing in v1 (§1.1:621-622). */
export type OwnerNotificationSettingsWire = Pick<
  NotificationSettingsWire,
  | 'booking_reminder_lead_hours'
  | 'quiet_hours_start_time'
  | 'quiet_hours_end_time'
  | 'quiet_hours_bypass_types'
>;

/** The owner document's `rpt` section (§1.1:622). */
export type OwnerReportsSettingsWire = Pick<
  ReportsSettingsWire,
  'events_enabled' | 'gallery_enabled' | 'media_max_upload_megabytes'
>;

/** The owner document's `vax` section (§1.1:623). */
export type OwnerVaccineSettingsWire = Pick<
  VaccineSettingsWire,
  'proof_file_types' | 'typical_full_vaccination_age_months'
>;

/** The owner document's `pay` section — the `charge_timing_mode` rows and
 *  `max_sessions_per_booking_count`, both served and read by nothing in v1
 *  (§1.1:623-624). */
export interface OwnerPaymentSettingsWire {
  /** scope (the service) → mode, one entry per `charge_timing_mode` row. */
  charge_timing_mode: Record<string, PaymentChargeTimingMode>;
  max_sessions_per_booking_count: number;
}

/**
 * `GET /settings` `[auth]` — the owner settings document (SET-U01, E51;
 * §1.1:608-627; §2.1:1870-1887): every domain's public subset in one read.
 *
 * Built from Postgres on EVERY call — no cache, no invalidation hook, no TTL
 * (conflict 19) — on the ordinary `authenticate` guard (no
 * `authenticateVerified`, conflict 8). The route adds no principal-kind gate:
 * the document holds nothing per-family, so any principal with a mirror row
 * reads the same bytes. It never reads `staff_settings`, `cash_settings`,
 * `migration_settings`, `account_settings` or `alumni_settings`.
 *
 * **No `cxl` section, ever in v1** (the cancellation rows are stored-only
 * from design 6.0.0); **no `mig` section** (§1.1:624-626). Served from 2.0.0
 * with no mobile reader yet; the first is DAY-U09 (S19, design 4.0.0). A
 * settings PATCH is reflected by the very next `GET /settings`
 * (design.md:1880-1881).
 */
export interface OwnerSettingsWire {
  /** Per campus, every service (E03; §1.1:611-612). */
  offerings: Record<LocationKey, Record<ServiceCategory, ServiceOfferingWire>>;
  day: OwnerDaySettingsWire;
  gates: OwnerGateSettingsWire;
  eval: OwnerEvaluationSettingsWire;
  cred: OwnerCreditSettingsWire;
  /** Live classes only (`group_classes.expired_at IS NULL`). */
  cls: OwnerClassSettingsWire[];
  msg: OwnerMessagingSettingsWire;
  notif: OwnerNotificationSettingsWire;
  rpt: OwnerReportsSettingsWire;
  vax: OwnerVaccineSettingsWire;
  pay: OwnerPaymentSettingsWire;
}

/** `GET /settings` response (200). */
export type GetSettingsResponse = OwnerSettingsWire;

// ---- (b) response wires (continued): the settings manifest (2.0.0) --------
//
// The portal's one settings screen hosts every domain's editor as manifest
// entries (E50; design §2.10:4943-4958), and the manifest "is read from §2.1's
// registry … one rule with the server's". So the server SERVES it, built from
// `src/lib/settingsRegistry.ts` on every call, rather than the portal holding
// a copy that would drift between deploys (a stale `inert` flag would draw a
// field the server refuses with 422). The portal holds no class-to-role map:
// `editable` arrives computed, as `GET /me`'s capabilities do (STAFF-U12).

/**
 * Where a key's current value is read: in the response of
 * `GET /staff/settings/:domain` (`tier: 'global'`, the bare path — the one row
 * of every domain but `day` and `eval`, and their global row) or of
 * `GET /staff/settings/:domain/:location` for each campus (`tier: 'campus'`;
 * `day` and `eval` only). `field` is that response's key — a column, so NOT
 * always the registry key without its prefix (`acct.signup_field_requirement_map`
 * is `signup_fields`) — and on `pay` the `key` of the `PaymentSettingWire`
 * rows holding it: one row (scope `'global'`) for every pay key but
 * `charge_timing_mode`, which has one row per service scope. On `cxl` (from
 * 6.0.0-lg5.2) `field` is the column's name in `CancellationSettingsWire`'s
 * `global` for a global key, and on every row of its `policies` for a
 * per-service key. `path`, when present, walks into that field's jsonb value
 * (`['day-school', 'offered']` inside `offerings`); omitted otherwise.
 */
export interface SettingReadWire {
  tier: 'global' | 'campus';
  field: string;
  path?: string[];
}

/**
 * Where a key is edited — the registry's store kind (design §2.10:4951-4958):
 *   · `here` — the settings PATCH writes it: PATCH the path `read` names with
 *     `{ [read.field]: value }`; `refused_keys` and `inert_keys` name it the
 *     same way. Whether THIS caller may is `editable`.
 *   · `via` — part of another key's value (a jsonb path); `key` is the registry
 *     key that edits the whole (`day.day_school_offered_flag` →
 *     `day.offerings`). Never a field of its own.
 *   · `elsewhere` — a catalog row that another route, a seed step or a later
 *     unit edits: *read-only here*, and the editor names it as a link, never
 *     a field. `note` is the registry's description of that editor, display
 *     prose only: key behavior on `catalog`, never on `note`.
 */
export type SettingEditorWire =
  | { kind: 'here' }
  | { kind: 'via'; key: string }
  | { kind: 'elsewhere'; catalog: SettingCatalog; note: string };

/**
 * Whether a key is inert: stored, with no reader in this release, so a PATCH
 * naming it is 422 `setting_inert` (`SettingInertDetails`; question 28) and the
 * editor shows it read-only under one label, "stored, not read in this
 * release" (design §2.10:4947-4951). `false` = live. Otherwise `kind` says
 * why: `'stored'`, §3 marks the key *stored* (no v1 reader); `'deferred'`, live
 * in the design but held inert until a later unit of this build lands its
 * reader (the 11-02 re-cut). `note`, when present, is the registry's display
 * prose; omitted otherwise. Un-inerting a key changes this value to `false` —
 * data, never shape.
 */
export type SettingInertWire = false | { kind: 'stored' | 'deferred'; note?: string };

/**
 * What a key's value is, so a generic editor can render an input and check it
 * before the server does — the same registry entry that generates the
 * domain's zod schema (design §2.1:1858-1859), served. Discriminate on `type`,
 * the registry's own names. The server's 400 and 422 stay the gate; a client
 * check is a courtesy. Every list and record is replaced whole by a PATCH.
 *   · `boolean`.
 *   · `integer` — a whole number in [`min`, `max`]; `max` is 2147483647
 *     (int4) where the registry sets none (DECISIONS 65). `nullable` allows
 *     `null`.
 *   · `fraction` — a JSON number in [0, 1]; `one_of`, when present, lists the
 *     only values allowed; omitted otherwise.
 *   · `time` — `HH:MM`, 24-hour, America/Chicago.
 *   · `enum` — one of `values`; `nullable` allows `null`. For the per-scope
 *     `pay.charge_timing_mode` it describes each row's `value`; that key's
 *     PATCH body is a scope → value map (`PatchStaffSettingsPayRequest`).
 *   · `enum-list` — a list of members of `values`.
 *   · `integer-list` — whole numbers in [`min`, `max`]; `non_empty` refuses
 *     `[]`, `distinct` refuses a repeat (DECISIONS 61).
 *   · `text` — one line (no C0 control character, DECISIONS 66 and 71), never
 *     blank; `nullable` allows `null`.
 *   · `text-list` — a list of such strings.
 *   · `staff-id` — a `staff.id`; `nullable` allows `null`.
 *   · `record` — an object with exactly `keys`, each value one of
 *     `value.values`, or `null` where `value.nullable`. `fixed` (4.0.0-lg3.1;
 *     omitted when the record has none) names the keys that may hold only
 *     the value given: `{ email: 'mandatory' }` on the sign-up map
 *     (design §2.2:2244). An editor shows such a key read-only at that value,
 *     and a PATCH naming another is 422 `invalid_payload` (refusal step 4).
 *     `value.values` still lists the whole set.
 *   · `offerings` — `Record<ServiceCategory, ServiceOfferingWire>` over
 *     `services`; each `name` and `description` holds at most
 *     `name_max_length` and `description_max_length` characters (60 and 280;
 *     the rules are on `ServiceOfferingWire`).
 *   · `role-list` — a set of members of `values` (the three staff roles, in
 *     the pgEnum's order): at least one, none repeated (build DECISIONS 59).
 *     An editor renders one checkbox per member of `values`.
 *   · `catalog` — no value the settings PATCH carries (editor `elsewhere`).
 */
export type SettingValueSpecWire =
  | { type: 'boolean' }
  | { type: 'integer'; min: number; max: number; nullable: boolean }
  | { type: 'fraction'; one_of?: number[] }
  | { type: 'time' }
  | { type: 'enum'; values: string[]; nullable: boolean }
  | { type: 'enum-list'; values: string[] }
  | { type: 'integer-list'; min: number; max: number; non_empty: boolean; distinct: boolean }
  | { type: 'text'; nullable: boolean }
  | { type: 'text-list' }
  | { type: 'staff-id'; nullable: boolean }
  | {
      type: 'record';
      keys: string[];
      value: { values: string[]; nullable: boolean };
      fixed?: Record<string, string>;
    }
  | {
      type: 'offerings';
      services: ServiceCategory[];
      name_max_length: number;
      description_max_length: number;
    }
  | { type: 'role-list'; values: StaffRole[] }
  | { type: 'catalog' };

/**
 * One registry key, as the settings editor needs it. Every field is the
 * server's, computed from the key's registry entry ("every key to (role
 * class, store, editor, inert)", design §2.1:1779-1780) and, for `editable`,
 * from the caller's role. The editor's four cases (design §2.10:4947-4958), in
 * this order:
 *   1. `inert` is not `false` → read-only, under "stored, not read in this
 *      release";
 *   2. `editor.kind` is not `'here'` → read-only here, naming its editor;
 *   3. `editable` → a field;
 *   4. otherwise → the value, read-only: a `price` column for every role
 *      (a catalog price is case 2), a `money` key for the trainer, a `roles`
 *      key for all but the owner.
 * NON-OMIT: `class` and `read` emit an explicit `null`, never omitted.
 */
export interface SettingsManifestEntryWire {
  /** The registry key, `<domain>.<name>` (`cred.expiry_enforced_enabled`) —
   *  the design's and §3's name for it. Not the PATCH body key: that is
   *  `read.field`. */
  key: string;
  /** The key's domain (its prefix), served so that no client parses `key`. */
  domain: SettingsDomain;
  /** The key's role class, or `null` for a catalog fact §3 gives no class (a
   *  package's campus, program or credit count; a vaccine row's facts), which
   *  no role edits in v1. */
  class: SettingClass | null;
  /** Where the value is read, or `null` for an `elsewhere` key, whose value
   *  no settings GET carries. */
  read: SettingReadWire | null;
  editor: SettingEditorWire;
  inert: SettingInertWire;
  /** True exactly when a PATCH naming this key, sent by THIS caller with a
   *  value in range, would be accepted: `editor.kind` is `'here'`, `inert` is
   *  `false`, and the caller's role may edit `class`. So in v1 a `price` key
   *  is `false` for every role, the owner included (question 27 → (a); the
   *  same rule as `capabilities.edit_prices`), a `roles` key is `true` for the
   *  owner alone, a `money` key for the owner and the manager, and a live
   *  `ops` key for every role. Computed on each call, like `GET /me`'s
   *  capabilities; the PATCH re-checks regardless. */
  editable: boolean;
  value: SettingValueSpecWire;
}

/**
 * `GET /staff/settings/manifest` `[staff]` — every registry key, in ONE
 * document (build DECISIONS 85, J27). Any staff role; an owner (family)
 * principal is 403 `forbidden`. Built from the registry on every call, so it
 * is exactly what this server's PATCH enforces: a key whose store has not
 * landed is not in the registry and not here (a PATCH naming it is 400), and
 * a key un-inerted by a later unit reads `inert: false` from that deploy on.
 *
 * `entries` holds every registry key once, in the registry's order: stable
 * within a release and grouped by domain, but a client reads it as a set keyed
 * by `key` and groups by `domain`. No values: each entry's `read` names the
 * settings GET that carries its value, so the editor reads this document once
 * and each domain's row from its own route.
 */
export interface StaffSettingsManifestWire {
  entries: SettingsManifestEntryWire[];
}

/** `GET /staff/settings/manifest` response (200). */
export type GetStaffSettingsManifestResponse = StaffSettingsManifestWire;

// ---- (c) request bodies + query shapes -------------------------------------

/** The two audit fields — server-stamped, never in a PATCH body. */
export type SettingsAuditKey = keyof SettingsAuditWire;

/**
 * `PATCH /staff/settings/pay` body. One optional key per `payment_settings`
 * key (§16 pins the key set): a global-scope key carries its value; the one
 * per-scope key, `charge_timing_mode`, carries a scope → mode map of the
 * rows it edits, and a scope with no row is 400.
 */
export interface PatchStaffSettingsPayRequest {
  card_attempts_max_count?: number;
  seat_hold_max_minutes?: number;
  processing_hold_max_minutes?: number;
  custom_invoice_kind_list?: string[];
  custom_invoice_card_kind_list?: string[];
  refund_any_role_limit_cents?: number;
  price_change_notice_days?: number;
  max_sessions_per_booking_count?: number;
  automatic_return_instrument_mode?: 'original_card';
  charge_timing_mode?: Record<string, PaymentChargeTimingMode>;
}

/** A `cancellation_policy_settings` column a PATCH edits row by row. */
export type CancellationPolicyColumn = Exclude<
  keyof CancellationPolicyWire,
  'category' | SettingsAuditKey
>;

/**
 * `PATCH /staff/settings/cxl` body (6.0.0-lg5.2; CXL-U02). One optional key per
 * column of the two tables: a `global` column carries its value, and a
 * `cancellation_policy_settings` column a category → value map of the rows it
 * edits (`charge_timing_mode`'s shape on `pay`). Every key but
 * `per_dog_cancel_enabled` is inert, so in v1 that is the one key a PATCH can
 * change; any other is 422 `setting_inert` (refusal step 3).
 */
export type PatchStaffSettingsCxlRequest = Partial<
  Omit<CancellationGlobalPolicyWire, SettingsAuditKey>
> & {
  [K in CancellationPolicyColumn]?: Partial<Record<ServiceCategory, CancellationPolicyWire[K]>>;
};

/**
 * The `PATCH /staff/settings/:domain[/:location]` body, by domain: every
 * column of the domain's row, each optional (§1.1:628-630). `day` and `eval`
 * take the GLOBAL tier's columns on the bare path and the CAMPUS tier's on
 * `/:location`; a key of the other tier is 400 there (unknown key).
 * `location` is the path's, never the body's. §16 pins this map's keys to
 * `SettingsDomain`.
 */
export interface SettingsPatchByDomain {
  acct: Partial<Omit<AccountSettingsWire, SettingsAuditKey>>;
  alum: Partial<Omit<AlumniSettingsWire, SettingsAuditKey>>;
  cash: Partial<Omit<CashSettingsWire, SettingsAuditKey>>;
  cred: Partial<Omit<CreditSettingsWire, SettingsAuditKey>>;
  day:
    | Partial<Omit<DayProgramGlobalSettingsWire, SettingsAuditKey | 'location'>>
    | Partial<Omit<DayProgramCampusSettingsWire, SettingsAuditKey | 'location'>>;
  dog: Partial<Omit<DogGateSettingsWire, SettingsAuditKey>>;
  eval:
    | Partial<Omit<EvaluationGlobalSettingsWire, SettingsAuditKey | 'location'>>
    | Partial<Omit<EvaluationCampusSettingsWire, SettingsAuditKey | 'location'>>;
  mig: Partial<Omit<MigrationSettingsWire, SettingsAuditKey>>;
  msg: Partial<
    Omit<
      MessagingSettingsWire,
      | SettingsAuditKey
      | 'school_default_responder_first_name'
      | 'school_backup_responder_first_name'
    >
  >;
  notif: Partial<Omit<NotificationSettingsWire, SettingsAuditKey>>;
  pay: PatchStaffSettingsPayRequest;
  rpt: Partial<Omit<ReportsSettingsWire, SettingsAuditKey>>;
  vax: Partial<Omit<VaccineSettingsWire, SettingsAuditKey>>;
  staff: Partial<Omit<StaffSettingsWire, SettingsAuditKey>>;
  cxl: PatchStaffSettingsCxlRequest;
}

/**
 * `PATCH /staff/settings/:domain[/:location]` body (§1.1:628-649;
 * §2.1:1850-1869). Staff-only; `Idempotency-Key` REQUIRED; the idempotency
 * `requestHash` covers `{domain, location, ...body}` (`location` is `null`
 * on a path without one), so one key sent to a second campus is 422
 * `idempotency_mismatch` and nothing is written twice.
 *
 * Partial: the editor sends its dirty set and EVERY key in the body is an
 * edit — no comparison against the stored value. A jsonb-backed field is one
 * key and is replaced whole. An empty body `{}` is 400 `bad_request`
 * (nothing to edit — P01-contract notes item J9). `updated_by_staff_id` is
 * stamped from the caller.
 *
 * Atomic, refused in this order (one test per adjacent pair):
 *   1. 400 `bad_request` — the route's strict zod parse: an unknown key (a
 *      key whose store has not landed is unknown) or a bad shape. Malformed
 *      JSON is Fastify's parser error, 400 with code `internal`.
 *   2. 403 `forbidden` + `RefusedKeysDetails` — a key off the caller's
 *      role class.
 *   3. 422 `setting_inert` + `SettingInertDetails` — a key with no v1 reader.
 *   4. 422 `invalid_payload` (no details) — a value out of range, Postgres
 *      `23514` included.
 *   5. 422 `capacity_below_booked` + `CapacityBelowBookedDetails` —
 *      `/day/:location` only: the body lowers `daily_capacity_dogs` or unticks
 *      a weekday from `open_weekdays_list`, and a booked date within the
 *      horizon would fall below its count (4.0.0-lg3.1; DAY-67; design
 *      §2.3:2334-2340), every affected date's lock held in one transaction.
 * A refused body writes nothing.
 */
export type PatchStaffSettingsRequest<D extends SettingsDomain = SettingsDomain> =
  SettingsPatchByDomain[D];

// ---- (d) per-endpoint error detail unions ----------------------------------

/**
 * Every `details` arm `PATCH /staff/settings/:domain[/:location]` can carry:
 *   1. `refused_keys`  — rides 403 `forbidden` (refusal step 2).
 *   2. `setting_inert` — rides 422 `setting_inert` (refusal step 3).
 *   3. `capacity_below_booked` — rides 422 `capacity_below_booked` (refusal
 *      step 5), `/day/:location` only.
 * The endpoint's other refusals — 400 `bad_request`, 422 `invalid_payload`,
 * 422 `idempotency_mismatch`, 409 `idempotency_inflight`, an owner
 * principal's 403 `forbidden` — carry no `details`. `GET` carries none.
 */
export type PatchStaffSettingsErrorDetails =
  | RefusedKeysDetails
  | SettingInertDetails
  | CapacityBelowBookedDetails;

// (e) domain-owned pure helpers — NONE. Every settings value ships resolved
//     (the responder first names included); no client recomputes one.

// <<< domain:settings =========================================================

// ============================================================================
// §16 · wire tuple conformance (orchestrator-owned)
// ============================================================================
//
// Tuple ↔ union completeness, compile-time. Bidirectional `Equal` proves SET
// equality (a member missing from a tuple narrows `TUPLE[number]` and fails;
// an extra member widens it and fails). Lives IN wire.ts — with its own local
// helpers, since this file cannot import — so the guard travels with every
// generated client copy. Erasable (`type`-only); proven breakable at 1.13.0
// by mutating one tuple member and watching `tsc` fail.
//
// `SESSION_PROGRAMS` is deliberately absent: it is a SUBSET of ReportProgram
// (satisfies-guarded at its declaration), so an `Equal` pin would fail by
// design. `INVOICE_DEEP_LINK_REASONS` and every full-union tuple above are
// pinned.
//
// 2.0.0-lg1.1 adds three KEY-SET pins beside the tuple pins (same `Equal`,
// applied to `keyof`): the two settings by-domain maps and the pay PATCH body
// must cover exactly their union, so a domain appended to `SETTINGS_DOMAINS`
// fails `tsc` until both maps gain it (2.0.0-lg1.2's `'staff'` and
// 6.0.0-lg5.2's `'cxl'` were each proven red that way, by a mutant missing from
// one map),
// and a `payment_settings` key cannot be added to one of the pay shapes alone.
//
// 2.0.0 adds one RESERVED-SEGMENT pin: `manifest` is a static path segment
// under `/staff/settings/` (`GET /staff/settings/manifest`), which the router
// matches before `:domain`, so a domain named `'manifest'` would be
// unreachable on GET. The pin makes that a `tsc` error at the append.

type Expect<T extends true> = T;
type Equal<A, B> =
  (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;

export type WireTupleConformance = [
  Expect<Equal<(typeof API_ERROR_CODES)[number], ApiErrorCode>>,
  Expect<Equal<(typeof SERVICE_CATEGORIES)[number], ServiceCategory>>,
  Expect<Equal<(typeof LOCATIONS)[number], LocationKey>>,
  Expect<Equal<(typeof RATE_UNITS)[number], RateUnit>>,
  Expect<Equal<(typeof REPORT_PROGRAMS)[number], ReportProgram>>,
  Expect<Equal<(typeof NOTIFICATION_DEEP_LINK_KINDS)[number], NotificationDeepLinkKind>>,
  Expect<Equal<(typeof INVOICE_DEEP_LINK_REASONS)[number], InvoiceDeepLinkReason>>,
  Expect<Equal<(typeof BOOKING_MODES)[number], BookingMode>>,
  Expect<Equal<(typeof GROUP_CLASS_KEYS)[number], GroupClassKey>>,
  Expect<Equal<(typeof NOTIFICATION_TYPES)[number], NotificationType>>,
  Expect<Equal<(typeof MEDIA_PURPOSES)[number], MediaPurpose>>,
  Expect<Equal<(typeof CHARGE_BLOCKERS)[number], ChargeBlocker>>,
  Expect<Equal<(typeof WITHDRAW_MONEY_OUTCOMES)[number], WithdrawMoneyOutcome>>,
  // 1.13.0 lane TUPLE-PIN ADDs (§8, bookings): the per-endpoint 422 arm-kind
  // tuples — the runtime membership value for type-erased contract tests; these
  // pins guard the missing-member direction (WC-A1).
  Expect<
    Equal<(typeof POST_BOOKINGS_ERROR_DETAIL_KINDS)[number], PostBookingsErrorDetails['kind']>
  >,
  Expect<
    Equal<(typeof POST_REQUESTS_ERROR_DETAIL_KINDS)[number], PostRequestsErrorDetails['kind']>
  >,
  // 2.0.0-lg1.1 (§ settings): the domain tuple, then the key-set pins.
  Expect<Equal<(typeof SETTINGS_DOMAINS)[number], SettingsDomain>>,
  Expect<Equal<keyof SettingsWireByDomain, SettingsDomain>>,
  Expect<Equal<keyof SettingsPatchByDomain, SettingsDomain>>,
  Expect<Equal<keyof PatchStaffSettingsPayRequest, PaymentSettingKey>>,
  // 2.0.0 (§ settings): `manifest` is never a settings domain.
  Expect<Equal<Extract<SettingsDomain, 'manifest'>, never>>,
  // 3.0.0-lg2.1 (§ settings): the sign-up field order.
  Expect<Equal<(typeof SIGNUP_FIELDS)[number], SignupField>>,
  // 5.0.0-lg4.2: no pgEnum backs the tier, so this is its one pin.
  Expect<Equal<(typeof CREDIT_TIERS)[number], CreditTier>>,
];
